// ============================================================
// data/starter-activities.js — Corrective starter activities by misconception tag
// Loaded after data/forge-data.js and data/misconception-labels.js, before
// any page that offers a starter: teacher.html.
//
// Until this file existed, MC_STARTERS lived inline in teacher.html. It is
// split out for the same reason MC_LABELS was: the starter is content, it is
// edited far more often than the dashboard around it, and a second page will
// want it.
//
// A starter is the five-minute board activity a teacher runs when a
// misconception keeps firing. Every entry targets ONE specific error and
// makes the student commit to an answer before the reveal — that commitment
// is the point, so a starter that only restates the correct fact is not
// worth having.
//
// Scope: the tags a heatmap can actually aggregate — those used by two or
// more questions. There are 1,199 of them and 386 have a starter.
// Single-use tags (2,770 of them) are per-question identifiers rather than
// misconception categories; getStarterActivity() falls back to a generic
// drill built from the resolved label for those.
//
// The 200 aggregatable tags still without a starter are almost all tags that
// happen to be used once in each of two different subjects, rather than a
// cluster a single teacher would ever see on one heatmap. The subjects with a
// genuine within-subject taxonomy — psych, gcse-geo, econ, soc and now
// gcse-econ — are fully covered.
//
// GCSE Economics was retagged in full: its 420 questions previously carried
// 420 tags unique to themselves, so nothing aggregated and every starter fell
// back to the generic drill. They now use 76 shared MC-GE-* tags, averaging
// 5.5 questions per tag with none used only once. That change alone removed
// 418 single-use tags and added 75 aggregatable ones, all with starters below.
// The remaining subjects listed in CLAUDE.md still need the same treatment.
//
// Shapes in use: sort, classify, distinguish, correct, diagnose, diagram,
// chain, compare, evaluate, apply, match, trace, sequence, rewrite, graph,
// trigger, explain, scenario, calculate. `items` renders as a list to work
// through; `headers`/`rows` renders as a table to complete; `prompt` is
// board text; `answer` is the reveal, shown to the teacher only.
// ============================================================

var MC_STARTERS = {
  "MC-INF-01":{type:"sort",title:"Inflation or Disinflation?",instruction:"Sort these statements into Inflation, Disinflation, or Deflation. One fits two categories — be ready to justify.",items:["Price level rising at 4%","Price level rising at 2%, down from 4%","Price level falling","CPI at 103, up from 101","The rate of inflation is slowing","Prices are lower than last year"]},
  "MC-INF-03":{type:"diagnose",title:"Diagnose the Diagram",instruction:"A student drew AD/AS to show demand-pull inflation but made two errors. Identify both and correct them.",prompt:"Student labelled the shift 'AD moves right' and wrote 'result: higher prices AND higher output', showing the new equilibrium on a vertical LRAS."},
  "MC-INF-07":{type:"correct",title:"Spot the Error",instruction:"Find and correct the error in this student sentence.",prompt:"'The Bank of England's MPC must keep inflation at 0%, as higher prices damage the economy.'",answer:"Target is 2% CPI (symmetric). The MPC writes to the Chancellor if inflation exceeds 3% or falls below 1%."},
  "MC-GRO-01":{type:"distinguish",title:"Level vs Rate",instruction:"Label each GDP figure as 'level of GDP', 'rate of growth', or 'both'. Write one sentence explaining the difference.",items:["UK GDP: £2.2 trillion","GDP grew by 0.4% last quarter","GDP per capita rose from £32,000 to £33,500","The economy is 18% larger than in 2010"]},
  "MC-GRO-03":{type:"diagram",title:"Gap Check",instruction:"Draw an AD/AS diagram showing a positive output gap. Label actual GDP, potential GDP, and the price level. Explain in one sentence why it is called 'positive'.",prompt:"Common error: students draw actual GDP below potential and still call it positive."},
  "MC-EMP-01":{type:"classify",title:"Who Counts?",instruction:"Decide whether each person is ILO unemployed, claimant count unemployed, or economically inactive. One person may fit two categories.",items:["Jake, 19, not working but looking and available","Priya, 35, left work to care for children","Marcus, 24, working 3 hours/week (wants more)","Aisha, 28, claiming Universal Credit while job hunting","Lena, 67, retired"]},
  "MC-EMP-03":{type:"evaluate",title:"Short Run or Long Run?",instruction:"Mark each claim T (true in short run), L (long run only), or F (false). Justify each.",items:["Lower unemployment always means higher inflation","The long-run Phillips curve is vertical","The MPC can reduce unemployment permanently by cutting rates","Worker expectations adjust — removing the permanent trade-off"]},
  "MC-BOP-02":{type:"correct",title:"Spot the Confusion",instruction:"Identify the conceptual error and rewrite correctly.",prompt:"'The UK's current account deficit is the same as the government's fiscal deficit — both measure the gap between government income and spending.'"},
  "MC-BOP-03":{type:"diagram",title:"Draw the J-Curve",instruction:"Sketch a J-curve showing the effect of sterling depreciation on the current account over time. Label the initial worsening phase, turning point, and improvement phase. Add a 6-word explanation of why it worsens first.",prompt:"Common error: students draw immediate improvement after depreciation."},
  "MC-AD-01":{type:"correct",title:"Fix the Formula",instruction:"A student wrote: AD = C + S + G + (X − M). Identify the error and correct it. Explain why savings belongs in a different model.",answer:"AD = C + I + G + (X − M). Savings is a withdrawal from the circular flow, not a component of AD."},
  "MC-AD-04":{type:"diagram",title:"What Happens to Prices?",instruction:"On an AD/AS diagram, show a rightward shift in AD. Mark the new equilibrium. Does the price level rise or fall? Why does the answer depend on where the economy is on the SRAS curve?",prompt:"Common error: students state AD shifting right always causes lower prices."},
  "MC-AS-01":{type:"sort",title:"SRAS or LRAS?",instruction:"Sort these factors into 'shifts SRAS only', 'shifts LRAS only', or 'shifts both'. Justify one controversial placement.",items:["Oil price rise","Worker productivity improvement","Infrastructure investment","Rise in nominal wages","Technological innovation","Consumer confidence falls"]},
  "MC-FIS-01":{type:"distinguish",title:"Policy Match",instruction:"Match each action to 'fiscal' or 'monetary'. Three are ambiguous — annotate why.",items:["MPC cuts the base rate","Chancellor raises income tax","Government increases road spending","BoE buys government bonds (QE)","Government introduces Help to Buy","MPC raises rates to 5.25%"]},
  "MC-MON-04":{type:"chain",title:"QE Transmission Chain",instruction:"Complete the chain from start to finish. Each arrow must be a specific mechanism, not 'the economy improves'.",prompt:"BoE buys £60bn of government bonds → [step] → [step] → [step] → aggregate demand rises. Common error: students say QE 'prints money that goes straight to consumers'."},
  "MC-NI-01":{type:"classify",title:"Injection or Withdrawal?",instruction:"Classify each item as Injection (J) or Withdrawal (W). Then write the equilibrium condition using I, G, X, S, T, M.",items:["Consumer spending on imports","Government NHS spending","Household savings","Export revenue from UK services","Corporation tax receipts","Business investment"]},
  "MC-SI-01":{type:"correct",title:"Fix the Stat",instruction:"A student wrote: 'Asch found that 37% of participants conformed.' Identify the error and write the three correct Asch statistics.",answer:"37% = conformity on critical trials. 75% = participants who conformed at least once. ~32% = overall conformity rate across all trials."},
  "MC-SI-03":{type:"correct",title:"Milgram: Check the Figure",instruction:"A student wrote: 'Milgram showed that most people refused to obey.' Correct this and name one variation that significantly reduced obedience.",answer:"65% delivered maximum 450V in the baseline. Obedience fell to 40% when authority gave orders by phone; to 20% when the study moved from Yale."},
  "MC-MEM-01":{type:"diagram",title:"Reconstruct the MSM",instruction:"From memory, draw the Multi-Store Model. Label all three stores with capacity and duration. Mark the two processes between them. Identify one criticism.",prompt:"Common error: students reverse transfer direction or omit the rehearsal loop."},
  "MC-MEM-08":{type:"scenario",title:"Which Type of Interference?",instruction:"State whether proactive or retroactive interference is operating in each scenario. Write one sentence explaining the direction of disruption.",items:["You learned French first — your Spanish keeps coming out as French","You learn a new phone PIN and can no longer recall the old one","New revision notes keep pushing out the original version","Old work password resurfaces instead of the current one"]},
  "MC-ATT-01":{type:"correct",title:"Bowlby: Spot the Error",instruction:"Find and correct the error.",prompt:"'Bowlby argued that infants form equal attachments to all caregivers simultaneously and that any of these can serve as the primary attachment figure.'",answer:"Bowlby argued for monotropy — one primary attachment that is qualitatively stronger. This forms the internal working model; other attachments are secondary."},
  "MC-EDU-02":{type:"apply",title:"Hidden Curriculum in Practice",instruction:"Read this extract: 'Students line up in silence, are rewarded for punctuality, and are streamed by assessed ability from Year 7.' Link each feature to a specific element of the correspondence principle (Bowles & Gintis). Which social class does each element benefit?"},
  "MC-MET-01":{type:"evaluate",title:"Ethical Matrix",instruction:"Complete this matrix for covert participant observation. Then decide: is it ever justifiable? Apply one BPS ethical guideline.",headers:["Ethical issue","Problem for covert obs","How researcher might respond"],rows:[["Informed consent","",""],["Right to withdraw","",""],["Deception","",""],["Protection from harm",""," "]]},
  "MC-TEC-01":{type:"diagram",title:"Boundary Types",instruction:"Draw cross-sections of a destructive boundary and a constructive boundary. Label plate types, direction of movement, crust destroyed/created, and hazards at each. Explain why oceanic crust subducts rather than continental.",prompt:"Common error: students reverse which plate subducts or omit oceanic vs continental labelling."},
  "MC-TEC-02":{type:"compare",title:"Why did Haiti lose more lives than Christchurch?",instruction:"Complete this comparison table for the two earthquakes, then write a two-sentence conclusion explaining why development level mattered more than magnitude.",headers:["Factor","Haiti 2010","Christchurch 2011"],rows:[["Magnitude","7.0","6.3"],["Deaths","~230,000","185"],["Building quality","",""],["Emergency services","",""],["GDP per capita","",""],["Conclusion: why the difference?","",""]]},
  "MC-TEC-03":{type:"correct",title:"Why do composite volcanoes explode?",instruction:"A student wrote: 'Composite volcanoes erupt explosively because they are very tall and the pressure builds up inside.' Find the two errors in this explanation and write the correct version.",prompt:"Correct explanation must include: silica-rich (acidic) magma from subducted oceanic crust, high viscosity preventing gas escape, pressure builds until explosive release. Tall = shield volcano (basaltic, effusive). Height is a consequence, not a cause.",answer:"Composite volcanoes erupt explosively because silica-rich magma from the subducted plate is highly viscous — it traps gases which build until a violent explosive eruption occurs. The height of the volcano is a result of previous eruptions, not the cause of explosivity."},
  "MC-TEC-04":{type:"classify",title:"Earthquakes — which boundary?",instruction:"Classify each earthquake example as destructive, constructive, or conservative boundary. One is a trap — be ready to justify.",items:["2010 Haiti — conservative plate boundary (Caribbean/North American plates sliding)",  "2004 Indian Ocean — destructive boundary (subduction triggered megathrust)","San Andreas Fault, California — conservative (transform fault)","Mid-Atlantic Ridge — constructive boundary (can produce earthquakes)","2011 Tohoku, Japan — destructive (Pacific plate subducting under Eurasian)"]},
  "MC-TEC-06":{type:"diagram",title:"Focus or epicentre?",instruction:"Draw a cross-section diagram of an earthquake. Label: the focus (hypocentre), the epicentre, seismic waves, and the fault line. Then write one sentence defining each term precisely.",prompt:"Common error: students say the epicentre is where the earthquake originates — it is the point on the SURFACE directly ABOVE the focus. The focus (hypocentre) is the underground origin point. Shallow-focus earthquakes (<70km) cause more surface damage than deep-focus events.",answer:"Focus: the point underground where the earthquake originates and energy is released. Epicentre: the point on the Earth's surface directly above the focus — where shaking is usually most intense."},
  "MC-TEC-07":{type:"explain",title:"Why is Iceland so volcanically active?",instruction:"Iceland sits on the Mid-Atlantic Ridge (constructive boundary). But that alone does not explain its exceptional volcanic activity. Write a two-part explanation: (1) what the constructive boundary contributes, (2) what the hot spot adds — and mark Iceland's position on a blank Atlantic diagram.",prompt:"Constructive boundary: plates diverge → magma rises to fill gap → effusive basaltic eruptions (e.g. Eyjafjallajökull fissure eruptions). Hot spot: a fixed mantle plume of unusually hot material beneath the crust — independently generates extra volcanic activity. Iceland sits above BOTH simultaneously, making it more active than any other constructive boundary location.",answer:"Two factors combine: (1) The Mid-Atlantic Ridge causes plates to diverge, allowing basaltic magma to rise — producing regular effusive eruptions. (2) A mantle hot spot beneath Iceland provides an additional source of heat independent of the boundary, further raising volcanic output. Neither factor alone explains Iceland's exceptional activity."},
  "MC-BUS-02":{type:"calculate",title:"Break-Even Check",instruction:"Selling price: £20, variable cost per unit: £12, fixed costs: £40,000. Show full workings using the contribution method. Explain why the formula uses contribution, not profit.",prompt:"Common error: students divide price by fixed costs rather than fixed costs by contribution per unit."},
  "MC-CHEM-02":{type:"graph",title:"Ionisation Energy Jumps",instruction:"Sketch a graph of successive ionisation energies for sodium. Mark the large jump and explain why it occurs where it does.",prompt:"Common error: students describe all jumps as equal or fail to link the large jump to a new electron shell."},
  "MC-CRIM-01":{type:"sort",title:"Crime, Deviance, or Both?",instruction:"Sort each behaviour and explain your reasoning. Identify one example where the classification has changed over time.",items:["Shoplifting","Wearing pyjamas to a funeral","Cheating on a partner","Cannabis possession","Tax avoidance (legal schemes)","Honour-based violence"]},
  "MC-BIO-03":{type:"sequence",title:"Replication Steps",instruction:"Put these events in the correct order, then annotate each with the enzyme responsible and its specific function.",items:["DNA polymerase adds complementary nucleotides","Helicase unwinds the double helix","Free nucleotides are activated","Two identical double helices produced","Hydrogen bonds between base pairs break","DNA ligase joins Okazaki fragments"]},
  "MC-HIST-04":{type:"chain",title:"Fire to Dictatorship",instruction:"Complete the causal chain. Each link must be a specific event or law.",prompt:"Reichstag Fire (Feb 1933) → [step] → [step] → [step] → Hitler has dictatorial powers (July 1933). Common error: jumping from fire directly to Enabling Act without naming the Decree of the Reich President."},
  "MC-LAW-02":{type:"apply",title:"Intent or Recklessness?",instruction:"Classify each scenario as direct intent, oblique intent (Woollin), or Cunningham recklessness. Cite the defining case.",items:["D shoots V with aim of killing","D blows up plane for insurance — passengers die","D throws stone at window knowing it might break — it does","D drives at high speed in residential area — child killed"]},
  "MC-PHYS-01":{type:"correct",title:"Forces vs Motion",instruction:"A student wrote: 'When an object moves at constant velocity, a net forward force must be acting.' Correct this using Newton's First Law and draw a free body diagram for a car at constant speed.",prompt:"Common error: students assume motion requires ongoing force — confusing Aristotelian with Newtonian mechanics."},
  "MC-CS-01":{type:"trace",title:"Trace the Loop",instruction:"Trace through this loop for i = 1 to 5 and record the output. Then identify the off-by-one error and rewrite to print only values 2, 3, 4.",prompt:"FOR i ← 1 TO 5\n  IF i MOD 2 ≠ 0 THEN OUTPUT i\nENDFOR"},
  "MC-MATH-01":{type:"correct",title:"Chain Rule Check",instruction:"A student differentiated y = sin(3x²) and wrote dy/dx = cos(3x²). Find the error and write the correct derivative showing all steps.",prompt:"Common error: differentiating the outer function only, not multiplying by the derivative of the inner function."},
  "MC-DE-04":{type:"correct",title:"Word Order Fix",instruction:"Each sentence has a subordinate clause word-order error. Underline and rewrite correctly.",items:["Ich denke, dass er kommt morgen.","Sie sagt, obwohl sie ist müde.","Wir wissen, weil er hat das gemacht.","Er hofft, dass sie kommt nicht."]},
  "MC-RS-04":{type:"distinguish",title:"Which Problem of Evil?",instruction:"Label each argument as Logical PoE, Evidential PoE, or theodicy. Identify the philosopher and write one counter-argument for the theodicy.",items:["God and evil are logically incompatible (Mackie)","The quantity of suffering makes God's existence improbable (Rowe)","Evil is necessary for soul-making (Hick)","Evil entered through free will and original sin (Augustine)"]},
  "MC-HSC-03":{type:"match",title:"Erikson Stage Match",instruction:"Match each behaviour to the correct Erikson stage and conflict. Write one consequence of failing to resolve each.",items:["A toddler insists on dressing themselves","A 6-year-old compares their reading to classmates","A teenager changes friendship group every term","A 40-year-old mentors junior colleagues","A 75-year-old writes their memoirs with pride"]},
  "MC-FR-03":{type:"trigger",title:"Subjunctive Triggers",instruction:"Highlight the trigger in each sentence and conjugate the verb correctly. Then write your own sentence using 'il faut que' with an irregular subjunctive.",items:["Je veux que tu (venir) avec moi.","Il est possible qu'elle (être) absente.","Nous partons avant qu'il (pleuvoir).","Bien qu'il (faire) froid, ils sont sortis."]},
  "MC-RS-06":{type:"compare",title:"Bentham vs Mill",instruction:"Complete this comparison table. Then write two sentences evaluating where Mill's qualitative distinction creates a practical problem.",headers:["Feature","Bentham","Mill"],rows:[["Basis of judgement","",""],["How pleasures counted","",""],["Type of utilitarianism","",""],["Key criticism","",""]]},
  "MC-HSC-04":{type:"rewrite",title:"Command Word Upgrade",instruction:"Rewrite this student answer at the 'assess' level. Question: 'Assess the effectiveness of person-centred care for an elderly patient with dementia.'",prompt:"Student: 'Person-centred care means putting the patient at the centre. It involves respecting their wishes and dignity. It is used in care homes across the UK.'"},
  "MC-FR-05":{type:"correct",title:"Si Clause Fix",instruction:"Find and correct the error in each conditional sentence. Write the rule in your own words below each.",items:["Si j'aurais de l'argent, j'achèterais une voiture.","Si tu viendrais, je serais content.","S'il pleuvrait, nous resterons à la maison.","Si j'aurais su, je n'aurais pas dit ça."]},
  "MC-HIST-01":{type:"evaluate",title:"Doomed from the Start?",instruction:"A student claims the Weimar Republic was structurally doomed from 1919. Your job: write one paragraph SUPPORTING this view, then one paragraph CHALLENGING it. Each paragraph must cite at least two specific pieces of evidence.",prompt:"Support: Article 48 emergency powers, proportional representation producing unstable coalitions, stab-in-the-back myth undermining legitimacy from the outset, war guilt clause economic damage. Challenge: Republic survived hyperinflation (1923), Stresemann's golden years (1924–29) with GDP recovery, cultural flourishing, Dawes Plan stability. Common error: students list structural factors only and ignore the contingency of the Depression — Weimar was NOT doomed until 1929."},
  "MC-HIST-02":{type:"chain",title:"Failure to Long-term Gain",instruction:"The Munich Putsch failed. Complete this chain showing how a military failure became a long-term political asset. Each arrow must name a specific consequence or action.",prompt:"16 November 1923: Putsch collapses, Hitler arrested → [step: trial and speech] → [step: Mein Kampf and national platform] → [step: strategic shift] → [outcome by 1933]. Common error: students say Hitler 'learned from his mistakes' without specifying the decision to pursue power through legal means — the key strategic conclusion from the trial."},
  "MC-HIST-03":{type:"correct",title:"Did Germans Vote Hitler into Power?",instruction:"Find and correct the two factual errors in this student sentence. Then add one sentence that explains how Hitler actually became Chancellor.",prompt:"'Hitler became Chancellor in January 1933 because the Nazi Party won over 50% of the vote in the November 1932 election, giving them a democratic mandate.'",answer:"Error 1: Nazi vote share in November 1932 was 33.1% — their vote had FALLEN from 37.4% in July 1932. Error 2: Hitler was not elected Chancellor — he was appointed by President Hindenburg on 30 January 1933 after backroom deals involving von Papen, who believed he could control Hitler. Correct sentence: Hitler became Chancellor through elite miscalculation, not popular mandate."},
  "MC-HIST-05":{type:"compare",title:"Browning vs Goldhagen",instruction:"Complete this table comparing the two historians' arguments. Then write a two-sentence judgement: which interpretation has stronger evidential support and why?",headers:["Feature","Browning (Ordinary Men)","Goldhagen (Hitler's Willing Executioners)"],rows:[["Primary cause of killing","",""],["Evidence used","Battalion 101 testimonies",""],["Nature of perpetrators","Ordinary, pressured",""],["Role of ideology","Secondary",""],["Main criticism","","Monocausal, ignores peer pressure"]]},
  "MC-HIST-06":{type:"chain",title:"Truman Doctrine Transmission",instruction:"The Truman Doctrine (1947) marked a permanent shift in US foreign policy. Complete this chain — each link must be a specific claim, not a vague assertion.",prompt:"Soviet pressure on Greece and Turkey (1946–47) → [step: British withdrawal] → [step: Truman's speech to Congress, March 1947] → [step: the doctrine's key commitment] → [consequence for US foreign policy 1947–1989]. Common error: students describe the Doctrine as 'helping Greece' without stating the universal principle — that the US would support free peoples resisting communist subjugation anywhere in the world. This is what made it a doctrine, not just an aid package."},
  "MC-HIST-07":{type:"evaluate",title:"Berlin Blockade — Who Won?",instruction:"Write two sentences: one arguing the Blockade was a Soviet victory, one arguing it was a Western victory. Then write a third sentence giving your overall judgement with one piece of supporting evidence.",prompt:"Soviet case: forced Allies to concede German partition was permanent; demonstrated Western vulnerability in Berlin. Western case: airlift succeeded (277,000 flights, 2.3m tonnes), Soviet capitulation in May 1949, NATO formed April 1949, FRG founded May 1949. Common error: students say Soviets 'gave up' without noting the political consequences — the crisis accelerated exactly the Western alliance the Soviets sought to prevent."},
  "MC-HIST-08":{type:"correct",title:"Cuban Missile Crisis Resolution",instruction:"A student wrote: 'Kennedy stood firm and forced Khrushchev to back down.' Find three problems with this account and rewrite it accurately in three sentences.",prompt:"Problems: (1) 'Stood firm' ignores the secret deal — removal of Jupiter missiles from Turkey was a real US concession; (2) 'forced Khrushchev' implies Soviet defeat — both sides compromised; (3) ignores the public pledge not to invade Cuba. The crisis is better described as a mutual face-saving compromise than a US victory."},
  "MC-HIST-09":{type:"sort",title:"Détente or Containment?",instruction:"Sort each policy/event as primarily 'détente' (reducing Cold War tensions) or 'containment' (resisting Soviet expansion). Two are genuinely ambiguous — be ready to argue both ways.",items:["SALT I (1972)","Nixon visits China (1972)","Helsinki Accords (1975)","Carter boycotts Moscow Olympics (1980)","US arms mujahideen in Afghanistan","Ford refuses to meet Solzhenitsyn","Jackson-Vanik Amendment (1974)","Reagan 'Evil Empire' speech (1983)"]},
  "MC-HIST-12":{type:"chain",title:"Why did the USSR Collapse?",instruction:"Historians disagree about the relative weight of internal vs external causes. Complete both chains, then write one sentence judging which was more important.",prompt:"Internal chain: Command economy stagnation → [step] → [step] → [outcome: 1991]. External chain: Arms race cost → [step: Afghanistan] → [step] → [outcome: 1991]. Common error: students attribute collapse solely to Gorbachev's reforms or solely to Reagan's arms race pressure — examiners credit multi-causal analysis that identifies the interaction between economic weakness and political reform."},
  "MC-HIST-13":{type:"evaluate",title:"Korea — Limited War or Global Crisis?",instruction:"Write one sentence arguing Korea showed Cold War restraint, and one sentence arguing it nearly became World War Three. Then add a judgement: which interpretation better fits the evidence?",prompt:"Restraint case: both superpowers avoided direct confrontation, MacArthur dismissed for wanting to escalate, armistice restored original boundary — war ended where it started. Escalation risk case: MacArthur pushed to Yalu River triggering Chinese intervention (300,000 troops), nuclear weapons considered, Truman declared national emergency. Key judgement: the war demonstrated that both sides feared escalation — limited war became the Cold War norm precisely because Korea showed the alternative."},

  // ---- GCSE Geography — coasts, rivers, hazards, ecosystems, energy ----
  "MC-COAST-01":{type:"classify",title:"Which Erosion Process?",instruction:"Name the erosion process in each description. Two are commonly swapped — be ready to say which and why.",items:["Waves compress air into a crack until the rock shatters","Pebbles carried by waves scrape and grind the cliff face","Rocks knock against each other and become smaller and rounder","Seawater dissolves the calcium carbonate in limestone"],answer:"1 Hydraulic action, 2 Abrasion, 3 Attrition, 4 Solution. Hydraulic action and abrasion are the pair students swap: hydraulic action needs no rock-on-rock contact, which is exactly why it works so well on Holderness's soft boulder clay."},
  "MC-COAST-02":{type:"correct",title:"Why Does the Headland Stick Out?",instruction:"Find the error in this student sentence and rewrite it in one accurate sentence.",prompt:"'Headlands form because the hard rock grows outwards faster than the soft rock around it.'",answer:"Nothing grows. Differential erosion: the clay is eroded quickly to form a bay, while the chalk resists and is left protruding. It is the difference in the RATE OF EROSION, not a difference in rate of formation."},
  "MC-COAST-03":{type:"sequence",title:"Fill the Missing Stage",instruction:"A student wrote the headland sequence as: crack → arch → stack → stump. Insert the missing stage in the right place, then write one sentence for each arrow explaining what the waves are actually doing.",answer:"crack → CAVE → arch → stack → stump. Waves widen a weakness into a cave; erosion cuts through the headland to form an arch; the arch roof collapses leaving an isolated stack; the stack is undercut and eroded down to a stump."},
  "MC-COAST-04":{type:"diagram",title:"Draw the Zigzag",instruction:"Draw a beach with waves approaching at an angle. Add arrows for swash and backwash, then mark the net direction of sediment movement. Finally, mark where a spit would form and explain why it forms there and not elsewhere.",prompt:"Common error: students draw backwash returning at the same angle as swash. Backwash returns straight down the beach under gravity — that is what makes the movement a zigzag rather than a straight line."},
  "MC-COAST-05":{type:"evaluate",title:"Solved for Whom?",instruction:"A student says the Mappleton groynes 'solved erosion for the Holderness coast'. Write one sentence on who benefits, one on who loses, and a judgement on whether 'solved' is the right word.",prompt:"Mappleton: rock groynes plus revetment protect the village and the B1242 coast road.",answer:"Groynes trap sediment moving by longshore drift, so the protected stretch keeps its beach — but settlements downdrift (e.g. Great Cowden) lose their sediment supply and erode faster. The problem is displaced along the coast, not removed. 'Managed' is defensible; 'solved' is not."},
  "MC-COAST-06":{type:"distinguish",title:"Storm Beach or Summer Beach?",instruction:"For each statement, decide whether it describes constructive or destructive waves, then explain in one sentence why a beach can be wide in summer and narrow after a winter storm.",items:["Strong backwash drags material offshore","Swash is stronger than backwash, building the beach up","Low frequency, long wavelength, spilling","High frequency, steep, plunging"],answer:"1 destructive, 2 constructive, 3 constructive, 4 destructive. Storm waves move sediment offshore into bars; calmer constructive waves return it, so a narrow post-storm beach is not necessarily permanent loss."},
  "MC-RIV-01":{type:"distinguish",title:"Where Does the River Erode?",instruction:"For each part of the long profile, state whether vertical erosion, lateral erosion or deposition dominates — and give the landform that results.",items:["Upper course, steep gradient, high energy","Middle course, gentler gradient","Lower course, very low gradient, wide floodplain"],answer:"Upper: vertical erosion → V-shaped valley, waterfalls, interlocking spurs. Middle: lateral erosion → meanders. Lower: deposition → floodplain, levees, delta. The error to correct is 'erosion happens everywhere' — energy and gradient fall downstream, so deposition takes over."},
  "MC-RIV-02":{type:"diagram",title:"Cross-Section of a Meander",instruction:"Draw a cross-section through a meander. Label the river cliff, the slip-off slope, the deepest water and the fastest flow. Add a curved arrow showing helicoidal flow, then write one sentence linking the flow to the asymmetry.",prompt:"Common error: students say the outside bend erodes 'because the water hits it'. That describes the result, not the mechanism.",answer:"Helicoidal (corkscrew) flow carries the fastest current to the outside bend, undercutting it into a river cliff, then sweeps eroded material across the bed and deposits it on the slower inside bend as a slip-off slope."},
  "MC-RIV-03":{type:"chain",title:"Why Tewkesbury?",instruction:"Complete the chain. Each link must be a specific physical or locational factor, not 'it rained a lot'.",prompt:"Wettest summer on record (2007) → [step: antecedent conditions] → [step: what the confluence does] → thousands of homes flooded and the town cut off.",answer:"Prior rainfall had already saturated the ground, so infiltration was minimal and surface runoff was rapid → Tewkesbury sits at the confluence of the Severn and the Avon, so two flood peaks arrive and combine at the same place → discharge exceeded channel capacity. Rainfall alone does not explain why Tewkesbury specifically flooded."},
  "MC-HAZ-01":{type:"correct",title:"Pinatubo — Boundary and Effect",instruction:"A student wrote the sentence below. Find both errors and write the correct version, including one measurable global effect.",prompt:"'Pinatubo erupted on a constructive boundary in 1991, and its effects were limited to the Philippines.'",answer:"Error 1: Pinatubo sits on a DESTRUCTIVE (subduction) boundary. Error 2: the effects were global — sulfur dioxide injected into the stratosphere cooled global average temperatures by roughly 0.5°C for about two years."},
  "MC-HAZ-02":{type:"evaluate",title:"Big Impact, No Deaths?",instruction:"Eyjafjallajökull killed almost nobody but is studied as a major hazard event. Write two sentences justifying its inclusion, then state the general principle in one sentence.",prompt:"2010: over 100,000 flights cancelled across European airspace.",answer:"The eruption was small (far below Pinatubo's VEI 6) and Iceland is sparsely populated near the volcano, so direct deaths were minimal — but ash grounded European aviation for days, stranding passengers and disrupting freight and perishable exports worldwide. Principle: hazard impact is measured in economic and social disruption, not only in deaths."},
  "MC-HAZ-03":{type:"correct",title:"What Actually Flooded New Orleans?",instruction:"Find the error and rewrite accurately in two sentences.",prompt:"'New Orleans flooded because Katrina's Category 5 winds were strong enough to destroy the city.'",answer:"Katrina had weakened to a strong Category 3 by landfall. The flooding was caused by storm surge overwhelming and breaching the levees in a city much of which lies below sea level — a defence failure, not wind damage."},
  "MC-HAZ-04":{type:"distinguish",title:"Wind or Water?",instruction:"Haiyan had among the highest landfall wind speeds ever recorded, yet most of the roughly 6,300 deaths had a different cause. Name it, then write one sentence explaining why the same killer appears in both Haiyan and Katrina.",answer:"Storm surge. In both events the sea, driven ashore by low pressure and wind, caused most deaths — Tacloban's surge reached over 5m. Wind destroys buildings; water drowns people. The difference in death toll between Haiyan and Katrina reflects preparedness and income level, not the physics."},
  "MC-MGT-01":{type:"sort",title:"Monitor, Predict, Protect or Plan?",instruction:"Sort each action into one of the four hazard management strategies. Two could be argued into a second category — be ready to justify.",items:["Seismometers recording tremors in real time","Earthquake-resistant buildings with cross-bracing","Annual evacuation drills in schools","Forecasting where a hurricane will make landfall","Tsunami warning sirens along a coast","Zoning laws banning building on a floodplain"],answer:"Monitor: seismometers, warning sirens (arguably protect). Predict: hurricane landfall forecasting. Protect: earthquake-resistant buildings. Plan: drills, zoning laws. The distinction students miss is monitoring (tracking what is happening now) versus prediction (forecasting what will happen)."},
  "MC-GEO-BIO-01":{type:"chain",title:"Climate to Biodiversity",instruction:"Complete the chain, then use it to explain why tropical rainforest and desert sit at opposite ends of the biodiversity range.",prompt:"Temperature and precipitation → [step] → [step] → level of biodiversity.",answer:"Climate determines growing season length → growing season determines net primary productivity (plant growth) → plant growth determines the food and habitat available, and so biodiversity. Hot and wet all year = long growing season = high biodiversity; hot and dry = short or absent growing season = low biodiversity."},
  "MC-GEO-BIO-05":{type:"sort",title:"Four Kinds of Ecosystem Service",instruction:"Sort each into provisioning, regulating, cultural or supporting. One is regularly misfiled — find it.",items:["Timber for construction","Forests absorbing CO2 and moderating climate","A woodland used for recreation and wellbeing","Wetlands filtering pollutants from water","Nutrient cycling in soil","Medicinal plants"],answer:"Provisioning (goods): timber, medicinal plants. Regulating (processes): carbon absorption, water filtration. Cultural: recreation. Supporting: nutrient cycling. The commonly misfiled one is water filtration — students call it provisioning because it involves water, but the service is the PROCESS, not the resource."},
  "MC-GEO-BIO-08":{type:"correct",title:"Deforestation and the Carbon Cycle",instruction:"A student wrote the sentence below. It states a real effect but misses the direct one. Add the missing mechanism and explain which is larger.",prompt:"'Deforestation affects the carbon cycle because fewer trees means less oxygen is produced.'",answer:"The direct effect is on CARBON, not oxygen: felling removes a carbon sink (trees can no longer absorb CO2 by photosynthesis) AND, if the timber is burned or left to rot, releases stored carbon back to the atmosphere. So deforestation both removes future absorption and creates an immediate emission."},
  "MC-GEO-BIO-11":{type:"compare",title:"Malthus vs Boserup",instruction:"Complete the table, then write one sentence saying which theory the Green Revolution supports and why.",headers:["Feature","Malthus","Boserup"],rows:[["View of population growth","",""],["What happens when resources run short","",""],["Role of technology","",""],["Overall outlook","",""]],answer:"Malthus: population grows geometrically while food grows arithmetically; shortage causes checks (famine, disease, war); technology is not assumed; pessimistic. Boserup: population growth is the driver of innovation; shortage causes necessity-led invention; technology expands the ceiling; optimistic. The Green Revolution supports Boserup — rising demand produced higher-yielding crops rather than mass famine."},
  "MC-FOR-02":{type:"match",title:"Adaptation to Function",instruction:"Match each rainforest adaptation to the problem it solves. Then name one adaptation that solves a problem NOT on this list.",items:["Drip tips on leaves","Buttress roots","Lianas","Waxy leaf surface","Shallow root systems"],answer:"Drip tips — shed heavy rain fast, preventing mould and leaf damage. Buttress roots — provide support because nutrients (and so roots) stay shallow. Lianas — reach the canopy light without building a trunk. Waxy surface — repels water. Shallow roots — capture nutrients from the thin topsoil where they are concentrated. The key link students miss: shallow roots are WHY buttresses are needed."},
  "MC-FOR-04":{type:"chain",title:"Keystone Collapse",instruction:"Complete the chain showing how a dam far from the forest changes the forest itself. Each arrow must be a specific transfer.",prompt:"Dam blocks salmon migration → [step] → [step] → [step] → forest nutrient levels fall.",answer:"Salmon cannot reach upstream spawning grounds → bears and wolves lose a key seasonal food source, so populations fall or move → fewer salmon carcasses are carried into the forest and left to decompose → the marine-derived nitrogen they deliver to soils is lost. This is what 'disproportionate to their numbers' means — salmon are a nutrient pump between ocean and forest."},
  "MC-FOR-11":{type:"evaluate",title:"Does REDD Work?",instruction:"Write one sentence explaining what REDD actually pays for, then one strength and one weakness. Finish with a judgement on whether it reduces global emissions or relocates them.",answer:"Developed countries and TNCs fund forest protection in developing countries to offset their own emissions. Strength: channels money to conservation and can involve local communities. Weaknesses: no agreed definition of 'forest' (plantations can count), leakage (logging moves to an unprotected area), and it permits continued emissions at source. Judgement: it can reduce deforestation locally while leaving the emitter's behaviour unchanged."},
  "MC-FOR-12":{type:"distinguish",title:"Is This Sustainable Forestry?",instruction:"For each practice, decide sustainable or not, and give the reason in six words or fewer.",items:["Replanting two trees for every one felled","Clear-felling a block then moving on","Selective logging of mature trees only","Replacing natural taiga with a single-species plantation"],answer:"1 Sustainable — replacement exceeds removal. 2 Not — no replacement, habitat destroyed. 3 Sustainable — canopy and habitat retained. 4 Not — biodiversity lost even though tree cover returns. The test is whether the FOREST persists, not whether trees do."},
  "MC-ENE-01":{type:"sort",title:"Renewable, Non-Renewable or Recyclable?",instruction:"Sort each source. One category surprises most students — identify it and explain why it exists.",items:["Natural gas","Wind","Biofuel","Coal","Geothermal","Nuclear","Tidal","Oil"],answer:"Non-renewable: gas, coal, oil. Renewable: wind, geothermal, tidal. Recyclable: biofuel, nuclear. The surprise is 'recyclable' — biofuel can be regrown and nuclear fuel can be reprocessed, so neither is strictly finite nor strictly infinite. Calling nuclear 'renewable' is the error to correct."},
  "MC-ENE-03":{type:"explain",title:"Coal in the Ground, Unused",instruction:"The UK has large coal reserves that are barely touched. Give one physical, one economic and one political reason. Then say which is decisive and why.",answer:"Physical: remaining seams are deep, thin and expensive to reach. Economic: imported coal and gas have been cheaper than domestic deep-mined coal. Political: climate commitments and the phase-out of coal-fired generation removed the market. Decisive: political — the demand was legislated away, so no price would justify extraction."},
  "MC-ENE-07":{type:"distinguish",title:"What Makes It 'Unconventional'?",instruction:"Write a one-sentence definition of 'unconventional', then complete the table for tar sands and shale gas.",headers:["Feature","Tar sands","Shale gas"],rows:[["Where it is found","",""],["Extraction method","",""],["Main environmental cost","",""]],answer:"Unconventional = the fuel cannot be extracted by simply drilling and pumping; it needs additional processing or stimulation. Tar sands: bitumen-rich sands (Athabasca, Canada), surface mining and steam treatment, huge water use and tailings ponds — nearly 60% of Canada's oil output. Shale gas: gas trapped in shale rock, hydraulic fracturing, groundwater contamination and induced seismicity."},
  "MC-ENE-09":{type:"chain",title:"Energy Gap to Insecurity",instruction:"Define an energy gap in one sentence, then complete the chain to show why it is a security problem and not just an accounting one.",prompt:"Domestic demand exceeds domestic supply → [step] → [step] → energy security falls.",answer:"The shortfall must be imported → the country depends on other states, or on a single supplier or route, for a necessity → supply can be interrupted or repriced for reasons outside its control (conflict, sanctions, market shocks). Security means uninterrupted, affordable and accessible supply — an import-dependent country can fail on any of the three."},
  "MC-RVF-01":{type:"correct",title:"Write a Bradshaw Hypothesis",instruction:"Using Bradshaw's model, write a hypothesis testable across the three Darent sites (Westerham → Park Farm → Lullingstone). Then state which variables should DECREASE downstream.",prompt:"Weak version: 'The river changes downstream.' Why does this score nothing?",answer:"A usable hypothesis is directional and measurable, e.g. 'Discharge increases with distance downstream from Westerham.' Increasing downstream: width, depth, velocity, discharge, load quantity. Decreasing: gradient and load particle size. The weak version cannot be proved false, so it cannot be tested."},
  "MC-RVF-04":{type:"explain",title:"Why Three Velocity Readings?",instruction:"Students time a float at the left bank, centre and right bank. Explain why the readings differ, then explain why they repeat each three times.",answer:"Friction with the bed and banks slows the water at the edges, so velocity peaks in the centre (the thalweg). Three positions capture that variation instead of over-reporting one point; three repeats at each position allow a mean that reduces the effect of one-off errors — an eddy, a snagged float, or slow reaction time on the stopwatch."},
  "MC-RVF-05":{type:"calculate",title:"Discharge — Show the Method",instruction:"Cross-sectional area 1.8 m², mean velocity 0.4 m/s. Calculate discharge, writing both formulas and the substitution. Then state the units and explain why method marks are lost more often than the answer.",answer:"Cross-sectional area = width × mean depth. Discharge = area × velocity = 1.8 × 0.4 = 0.72 m³/s. Students who write only '0.72' lose the method marks; those who omit or invent units lose more. The unit is cubic metres per second — volume passing a point per second."},

  // ---- GCSE Geography — development, India, UK human, urbanisation, enquiry ----
  "MC-DEV-01":{type:"compare",title:"Why Not Just Use GDP?",instruction:"Complete the table, then name one thing HDI still fails to capture.",headers:["Measure","What it includes","What it misses"],rows:[["GDP per capita","",""],["HDI","",""]],answer:"GDP per capita: average economic output per person; misses health, education, distribution, informal economy, environmental cost. HDI: life expectancy (health), mean/expected years of schooling (education) and GNI per capita (economic), scored 0–1; still misses inequality, political freedom, gender disparity and environmental quality. Development is multi-strand, so a single economic indicator gives a partial picture."},
  "MC-DEV-03":{type:"classify",title:"Developing, Emerging or Developed?",instruction:"Classify each country description using Edexcel B's three categories, then state the single feature that most clearly separates emerging from developing.",items:["Low human development, inadequate services, subsistence agriculture dominant","Rapid industrial-led growth, rising incomes, widening internal inequality","High human development, service-dominated economy, ageing population"],answer:"1 Developing, 2 Emerging, 3 Developed. The separating feature is the RATE and SOURCE of change: emerging economies are growing rapidly on the back of industrialisation, which is why their inequality often widens as growth concentrates in urban cores."},
  "MC-DEV-04":{type:"sort",title:"Sort the Causes of Inequality",instruction:"Sort each cause into environmental, historical or political/economic. One belongs in two categories — argue for it.",items:["Colonial extraction of raw materials","Landlocked position with no port access","Trade rules favouring processed over raw exports","Endemic malaria reducing workforce productivity","Corruption and weak governance","Neo-colonial debt repayment"],answer:"Environmental: landlocked position, malaria. Historical: colonialism, neo-colonial debt. Political/economic: trade rules, governance. Trade rules are the arguable one — they are a present-day economic structure with an explicitly historical origin."},
  "MC-DEV-06":{type:"sequence",title:"Rostow's Five Stages",instruction:"Put the stages in order and give one feature of each. Then write the single strongest criticism of the model.",items:["Age of mass consumption","Traditional society","Drive to maturity","Pre-conditions for take-off","Take-off"],answer:"1 Traditional society (subsistence, barter) → 2 Pre-conditions (surpluses traded, infrastructure) → 3 Take-off (industrial and regional growth) → 4 Drive to maturity (technology spreads across the economy) → 5 Mass consumption. Criticism: it is Eurocentric and assumes every country can follow the path the West took, ignoring that colonised economies started from extraction, not a blank slate."},
  "MC-DEV-07":{type:"diagram",title:"Draw the Core and Periphery",instruction:"Draw two boxes labelled core and periphery. Add arrows for what flows each way, labelling each arrow with a specific good or payment. Then write one sentence on why Frank says the relationship keeps the periphery poor.",answer:"Periphery → core: coffee, cocoa, sugar, minerals — low-value raw materials. Core → periphery: manufactured goods, loans, and the profits repatriated by TNCs. Frank's claim is that the periphery is not 'undeveloped' but ACTIVELY UNDERDEVELOPED — the terms of trade transfer value to the core, so participation in the system entrenches the gap rather than closing it."},
  "MC-DEV-08":{type:"sort",title:"Top-Down or Bottom-Up?",instruction:"Sort each scheme, then write one sentence on the trade-off between the two approaches.",items:["A World Bank-funded hydroelectric dam","An NGO distributing low-cost water filters","A new international airport","Village-level microfinance loans","A national motorway programme"],answer:"Top-down: dam, airport, motorway. Bottom-up: water filters, microfinance. Trade-off: top-down delivers scale and national infrastructure but is expensive, imposed, and often displaces people; bottom-up is cheap, appropriate and locally owned but rarely transforms a national economy."},
  "MC-DEV-14":{type:"distinguish",title:"Which DTM Stage?",instruction:"For each description, give the DTM stage. Then state exactly what is happening to the GAP between birth and death rates in stage 3.",items:["High birth rate, high death rate, low total population","Death rate falling fast, birth rate still high","Birth rate falling rapidly, death rate low and falling slowly","Both rates low, population stable","Birth rate below death rate, population declining"],answer:"1, 2, 3, 4, 5. In stage 3 the gap is NARROWING — population still grows, but at a decelerating rate. Students routinely say population falls in stage 3; it does not, it grows more slowly."},
  "MC-DEV-15":{type:"diagnose",title:"Read the Pyramid",instruction:"A pyramid has a very narrow base and a wide top. State the DTM stage, name a country that fits, and list two consequences the government must plan for. Then say what a very WIDE base would have indicated instead.",answer:"Narrow base, wide top = stage 5 (e.g. Japan) — ageing population, low fertility. Consequences: rising dependency ratio, pension and healthcare costs, shrinking workforce. A very wide concave base = stage 2 (e.g. Niger) — youthful, high birth and death rates, pressure on schools rather than pensions."},
  "MC-DEV-16":{type:"calculate",title:"Dependency Ratio — Show the Working",instruction:"30 million young dependents, 10 million old dependents, 80 million of working age. Write the formula, substitute, and state what the answer MEANS in a sentence. Then say whether a ratio of 50 is high or low, and for whom that matters.",answer:"(young + old) ÷ working population × 100 = (30 + 10) ÷ 80 × 100 = 50. Fifty dependents for every hundred workers. That is comparatively low — a demographic dividend. High ratios (over 100) mean each worker supports more than one dependent, straining tax revenue, pensions and services."},
  "MC-IND-01":{type:"correct",title:"India by the Numbers",instruction:"Fix the three errors in this student sentence, then add the one statistic that best captures the gap between India's total size and its individual living standards.",prompt:"'India is the largest country in the world by area, has the largest population, and its high GDP per capita makes it a developed country.'",answer:"Seventh largest by AREA; second largest by POPULATION (1.3+ billion); fifth largest ECONOMY (overtook the UK in Sept 2022) with GDP around US$3.18 trillion. The decisive statistic is GDP PER CAPITA — around US$2,250, far below developed-country levels. Large total, small average."},
  "MC-IND-02":{type:"compare",title:"GDP Share vs Employment Share",instruction:"Complete the table for India, then write one sentence explaining why the two columns tell different stories.",headers:["Sector","Share of GDP","Share of employment"],rows:[["Agriculture","",""],["Industry","",""],["Services","",""]],answer:"Agriculture: small and falling share of GDP but still the largest single EMPLOYER (from ~75% of workers to just over 50% by 2011). Services: dominate GDP. The gap is the exam trap — it shows low agricultural productivity: half the workforce producing a small fraction of output, which is precisely why rural incomes lag."},
  "MC-IND-05":{type:"compare",title:"Delhi vs Bihar",instruction:"Complete the table from memory, then write one sentence stating which figure you would use in an exam and why one well-learned pair beats five half-remembered ones.",headers:["Indicator","Delhi (urban core)","Bihar (rural periphery)"],rows:[["Life expectancy","",""],["Literacy","",""],["GDP per capita","",""],["Fertility rate","",""]],answer:"Life expectancy 72.9 vs 68.7 years; literacy 86.21% vs 69.83%; GDP per capita US$7,500 vs US$630; fertility 1.6 vs 3.0. The GDP per capita pair is the strongest single citation — a twelvefold gap inside one country makes the regional inequality point instantly."},
  "MC-IND-06":{type:"explain",title:"34% Urban — Why Does That Matter?",instruction:"State India's urban proportion and annual rural-urban migration figure, then explain in two sentences why being only a third urban is significant for the FUTURE rather than the present.",answer:"34% urban in 2021 (475 million people), growing about 2% a year, with roughly 20 million migrating from rural to urban areas annually. Significance: India is still majority rural, so it has decades of urbanisation ahead — the infrastructure, housing and service pressures already visible in Mumbai will intensify, and the largest absolute urban growth in world history is still to come."},
  "MC-IND-07":{type:"chain",title:"Development to Demography",instruction:"Complete both chains with specific mechanisms, then state which DTM stage India is now entering.",prompt:"Chain A: Economic growth → [step] → life expectancy rises from 45 (1960) to 70 (2021). Chain B: Economic growth → [step] → [step] → fertility falls.",answer:"Chain A: better diets, wider healthcare availability and cleaner water reduce infant and infectious-disease mortality. Chain B: more girls educated and more women in paid work → later marriage, contraception available and desired family size falls. India is moving into stage 3 — birth rate falling rapidly while death rate is already low."},
  "MC-IND-11":{type:"chain",title:"Untreated Sewage — Follow It Downstream",instruction:"Only about 30% of India's sewage is treated. Complete the chain to a named consequence, then add the two industrial pollutants that compound it.",prompt:"70% of sewage untreated → [step] → [step] → named river consequence.",answer:"Untreated sewage discharges directly into watercourses → bacterial and nutrient loading raises disease risk and deoxygenates water → the Ganges and Indus rank among the world's ten most polluted rivers, with cholera and typhoid risk for those using them. Compounding it: industrial waste water carrying mercury, lead and arsenic, plus heavy pesticide use including DDT, banned elsewhere."},
  "MC-IND-13":{type:"evaluate",title:"Evidence of Influence",instruction:"Rank these four pieces of evidence from strongest to weakest as proof of India's growing GEOPOLITICAL influence, and justify your top choice in one sentence.",items:["Membership of BRICS, G20 and the Asian Development Bank","The IMF attributing about 15% of global growth to India","A growing role in ASEAN negotiations","Second largest population in the world"],answer:"Strongest is usually the IMF's 15% of global growth — it is quantified, independent and economic weight is what converts into diplomatic leverage. Population is weakest: size is a precondition for influence, not evidence of it. Membership of institutions shows recognition; a role in negotiations shows influence being exercised."},
  "MC-URB-01":{type:"distinguish",title:"Regeneration or Just Building?",instruction:"Write a one-sentence definition of urban regeneration, then decide which of these count as regeneration and which are simply construction.",items:["Converting derelict docks into offices and flats","Building a housing estate on greenfield land","Extending the Jubilee Line to Canary Wharf","Demolishing a tower block and leaving the site empty"],answer:"Regeneration is a planned, long-term attempt to reverse decline in a RUN-DOWN area, improving economy, environment and social conditions together. 1 and 3 qualify — Docklands reversed decline after the Port of London's container trade moved downstream. 2 is greenfield development, not regeneration. 4 is demolition without renewal."},
  "MC-URB-02":{type:"chain",title:"Why the Docks Closed",instruction:"Complete the chain. Each link must name a specific cause, not 'things changed'.",prompt:"1960s–80s: London's docks and East End manufacturing shed jobs → [step: shipping technology] → [step: geography of ports] → [step: overseas production] → deindustrialisation.",answer:"Containerisation required far larger ships and mechanised handling → those ships needed deep water, so trade moved downstream to Tilbury and Felixstowe, stranding the upstream docks → cheaper overseas labour and automation removed the remaining manufacturing base. Deindustrialisation is the long-term decline of manufacturing, not a single closure."},
  "MC-URB-03":{type:"correct",title:"Migration Adds More Than Numbers",instruction:"A student says international migration 'just increases London's population'. Give two ways this understates it, each with a specific London example.",answer:"It reshapes ethnic and cultural composition, producing distinctive neighbourhoods (Brick Lane's Bangladeshi community, Southall's Punjabi community) — a change in character, not just count. It also alters the age structure and labour supply: migrants are disproportionately of working age, which lowers the dependency ratio and fills roles in health, construction and hospitality."},
  "MC-URB-04":{type:"chain",title:"Counter-Urbanisation in Cornwall",instruction:"Complete the chain from national trend to local consequence. Then name the group that loses out and explain why.",prompt:"Retirees and second-home buyers move to coastal Cornwall → [step] → [step] → some villages feel 'empty' for much of the year.",answer:"Demand for a fixed housing stock rises sharply → prices rise faster than local wages, and homes shift to second-home or holiday-let use → properties stand empty outside the season, so shops, buses and schools lose year-round custom. The losers are young local people, priced out of the area they grew up in — an affordability gap, not a housing shortage in the raw sense."},
  "MC-URB-05":{type:"evaluate",title:"Eden — What Was Reclaimed?",instruction:"State what the Eden Project site was before, then give one economic and one environmental benefit. Finish with one limitation of relying on a single attraction.",answer:"A disused china clay pit near St Austell — derelict and environmentally scarred. Economic: thousands of jobs and over a million visitors a year, diversifying away from declining primary industry. Environmental: reclamation of degraded land plus an education and conservation role. Limitation: visitor numbers are seasonal and vulnerable to recession or fashion, so it concentrates rather than spreads Cornwall's economic risk."},
  "MC-URB-06":{type:"evaluate",title:"Has Tourism Replaced Mining?",instruction:"A student says the shift from tin mining and fishing to tourism means Cornwall's economy has simply swapped one industry for another. Write one sentence agreeing and two challenging.",answer:"Agree: tourism is now the dominant sector, as mining once was. Challenge 1: tourism is strongly seasonal, so many jobs are part-time, low-paid and insecure — annual income is not comparable to year-round industrial work. Challenge 2: tourism drives the second-home demand that prices out the same local population it employs, so the replacement carries a cost mining did not."},
  "MC-MUM-01":{type:"distinguish",title:"Two Sources of Megacity Growth",instruction:"Mumbai grew from about 3 million in 1950 to over 20 million today. Name the two components of that growth, then explain which dominates in a rapidly urbanising lower-middle-income country and why.",answer:"Natural increase (births minus deaths) and rural-urban migration. In rapidly urbanising cities migration usually dominates initially — but migrants are overwhelmingly of childbearing age, so they RAISE natural increase too. The two are compounding, not alternative, which is why 'purely births' and 'purely migration' are both wrong."},
  "MC-MUM-02":{type:"sort",title:"Push, Pull — and Reality",instruction:"Sort each factor as push or pull. Then write one sentence on why the pull factors often fail to materialise.",items:["Drought and failed harvests","Perceived availability of jobs","Lack of land ownership in the village","Better schools and hospitals","Rural poverty and debt"],answer:"Push: drought, landlessness, rural poverty. Pull: jobs, schools and hospitals. The reality gap: Mumbai's FORMAL job market and housing supply cannot absorb arrivals at the rate they come, so many migrants enter informal work and informal settlements — the pull is a perception of opportunity, not a guarantee of it."},
  "MC-MUM-03":{type:"correct",title:"Dharavi Is Not Only Deprivation",instruction:"A student calls Dharavi 'just an area of poverty'. Give three specific pieces of evidence that complicate this, then write a balanced one-sentence description.",prompt:"Roughly 1 million people in about 2.1 km², in the middle of Mumbai.",answer:"Evidence: a major informal industrial centre (recycling, leather, pottery, garments) turning over hundreds of millions of dollars a year; extremely high employment participation; strong community networks and social organisation. Balanced description: Dharavi combines severe deficits in sanitation, density and tenure security with a highly productive informal economy — describing only one half misrepresents it."},
  "MC-MUM-04":{type:"classify",title:"Whose Problem Is It?",instruction:"For each problem, decide whether it affects mainly informal settlements or the whole city. Then state the general principle in one sentence.",items:["Traffic congestion on arterial roads","Lack of household sanitation","Air pollution","Overcrowding on suburban rail","Water supply shortfalls"],answer:"Whole city: congestion, air pollution, rail overcrowding, water shortfalls. Mainly informal areas: household sanitation. Principle: rapid unplanned growth strains CITY-WIDE systems — the mistake is assuming the problems of rapid urbanisation are confined to slums, when the middle-class commuter and the Dharavi resident share the same failing infrastructure."},
  "MC-MUM-05":{type:"evaluate",title:"Judge the Redevelopment",instruction:"The Dharavi Redevelopment Project proposes demolition and rehousing in high-rise flats, part-funded by selling reclaimed land. Write one sentence for it, two against, and a judgement.",answer:"For: replaces insecure housing with formal flats and legal sanitation. Against 1: high-rise flats cannot house the ground-floor workshops the informal economy depends on, so rehousing destroys livelihoods along with housing. Against 2: eligibility rules exclude many residents who cannot prove long tenure. Judgement: it improves the housing metric while damaging the economy that makes the location valuable to residents — a classic top-down scheme measuring the wrong outcome."},
  "MC-MUM-06":{type:"compare",title:"Sites and Services vs Demolition",instruction:"Complete the table, then say which approach you would recommend and on what evidence.",headers:["Feature","Sites and services","Dharavi-style redevelopment"],rows:[["Who builds the housing","",""],["Cost to government","",""],["Speed","",""],["Effect on livelihoods","",""]],answer:"Sites and services: residents build incrementally on a legal plot with water, power and sanitation provided; low public cost; slow but continuous; livelihoods preserved because people stay in place and control their own layout. Redevelopment: contractor-built; high cost, part-funded by land sales; fast but disruptive; livelihoods often destroyed. Bottom-up trades speed for ownership and appropriateness."},
  "MC-ENQ-01":{type:"rewrite",title:"Fix the Hypothesis",instruction:"Rewrite this hypothesis so it is directional and measurable, then write the rule for what makes a hypothesis testable in your own words.",prompt:"'The river is different at different points.'",answer:"Usable version: 'River discharge increases with distance downstream from the source.' The rule: a hypothesis must state a DIRECTION of change in a MEASURABLE variable, so that data can show it false. 'Is different' cannot be disproved, so it cannot be tested."},
  "MC-ENQ-03":{type:"sort",title:"Primary or Secondary?",instruction:"Sort each source. Two are arguable — say why.",items:["Your own river depth measurements","Census population data","A photograph you took at the site","An old photograph from the local archive","A questionnaire you administered","An Environment Agency flood map"],answer:"Primary (collected first-hand): your measurements, your photograph, your questionnaire. Secondary (collected by others, reused): census, archive photograph, flood map. The arguable pair are the photographs — the distinction is not the medium but WHO collected it and when."},
  "MC-ENQ-04":{type:"classify",title:"Name the Sampling Method",instruction:"Identify the sampling method in each case, then state the main weakness of the one used for sites every 200m along a transect.",items:["Sites every 200 metres along a transect","Grid squares selected using random numbers","Sampling 10 people from each age group in proportion to the population","Interviewing whoever is willing to stop"],answer:"1 Systematic, 2 Random, 3 Stratified, 4 Opportunistic (convenience). Systematic's weakness: not every site has an equal chance of selection, so a regular interval can coincide with a regular feature (every 200m falling on a road junction) and build bias into what looks like objective coverage."},
  "MC-ENQ-09":{type:"calculate",title:"Mode, Mean, Median — All Three",instruction:"For the data set 2, 3, 3, 4, 5, 5, 5, 8: calculate the mode, mean and median, showing working for each. Then say which best represents the set and why.",answer:"Mode = 5 (occurs three times). Mean = 35 ÷ 8 = 4.375. Median = mean of the 4th and 5th ranked values = (4+5) ÷ 2 = 4.5. The mode is the only one that must be an actual value in the set; the mean is pulled upward by the 8. For a small skewed set like this the median is usually the fairest summary."},
  "MC-ENQ-11":{type:"distinguish",title:"Conclusion or Evaluation?",instruction:"Label each statement C (conclusion) or E (evaluation). Then write one sentence stating the difference.",items:["The hypothesis was supported: discharge increased downstream","Only three sites were sampled, which is too few to generalise","Velocity rose from 0.2 to 0.6 m/s between sites 1 and 3","The float method was affected by wind on the day","Site 2 was chosen for access, not representativeness"],answer:"C: 1, 3. E: 2, 4, 5. A conclusion returns to the hypothesis and answers it using the data. An evaluation turns on the ENQUIRY ITSELF — sample size, site selection, method reliability, conditions — and asks how much confidence the conclusion deserves."},
  "MC-ENQ-12":{type:"explain",title:"Float vs Flow Meter",instruction:"Explain why a flow meter would improve on a float, naming the specific source of error the float introduces. Then give one reason a class might still use a float.",answer:"The float depends on a stopwatch started and stopped by hand, so human reaction time adds an error of a few tenths of a second to every reading — significant over a 10m stretch where the total time may be under 30 seconds. It also measures only surface velocity, which is faster than the mean. A flow meter reads directly at a set depth. Floats are still used because they are cheap, robust and need no calibration."},
  "MC-URF-02":{type:"explain",title:"Why Stratford?",instruction:"Explain what makes Stratford unusually good for a regeneration enquiry, naming three contrasting sites within walking distance and what each represents.",answer:"Regeneration is investment to reverse decline in a run-down area, and Stratford compresses the whole sequence into a small area: Carpenters Estate (1960s social housing, partly vacant pending redevelopment) represents pre-regeneration decline; the Olympic Park and East Village represent large-scale planned investment; Old Stratford represents the pre-existing town centre absorbing the change. A student can survey all three in one afternoon and compare directly."},
  "MC-URF-03":{type:"classify",title:"Does It Belong on an EQS?",instruction:"Decide which features belong on an Environmental Quality Survey and which do not. Then state the scale an EQS normally uses.",items:["Litter","River discharge","Building condition","Graffiti","Green space","Traffic volume"],answer:"All belong except river discharge — that is a river fieldwork measurement, and it is a standard exam distractor. An EQS scores features on a BIPOLAR scale, typically −2 to +2, so each factor runs from a clearly negative to a clearly positive description rather than being simply present or absent."},
  "MC-URF-05":{type:"distinguish",title:"Closed, Scale or Open?",instruction:"Classify each question type, then state one advantage and one disadvantage of the statement/scale format used near Carpenters Estate.",items:["'How long have you lived here?'","'The regeneration has improved this neighbourhood' — strongly agree to strongly disagree","'What are your views on the regeneration?'"],answer:"1 Closed, 2 Statement/scale, 3 Open. Advantage of the scale: responses are directly comparable and quickly quantified into a chart. Disadvantage: it forces a complex opinion onto a fixed line and cannot capture WHY — which is why a good questionnaire pairs it with an open follow-up."},
  "MC-DEC-01":{type:"distinguish",title:"Is It a Geographical Issue?",instruction:"Decide which of these is a genuine geographical issue suitable for Paper 3, and say what disqualifies the others.",items:["Whether to build a road through a rainforest","The height of Mount Everest","Where to site a new reservoir","How a stretch of coastline should be managed","The population of Mumbai in 2021"],answer:"Issues: the road, the reservoir, the coastline. The others are FACTS, not issues — they have a single correct answer. A geographical issue is a genuine dilemma that combines physical and human geography, affects different groups differently, and has more than one defensible answer."},
  "MC-DEC-02":{type:"diagnose",title:"Why Did This Score Level 1?",instruction:"A student's decision-making answer lists only the advantages of their chosen option and ignores every source suggesting problems. Explain what the mark scheme rewards, then rewrite the opening sentence of a Level 3 answer.",answer:"Levels-based marking rewards a BALANCED, well-evidenced argument that uses multiple sources across the booklet — including those favouring a rival option — and then justifies the choice despite them. A one-sided answer cannot reach the top level however accurate it is. Level 3 opening: 'Option B is the strongest choice, although Figure 4 shows a real environmental cost that must be weighed against it.'"},
  "MC-DEC-03":{type:"sort",title:"Environmental, Economic or Social?",instruction:"Sort each piece of evidence, then explain why the same fact can sometimes sit in two categories.",items:["350 construction jobs created","Loss of 40 hectares of woodland","120 households displaced","£45m investment in the local economy","Increased air pollution near the new road","Improved hospital access for a rural village"],answer:"Economic: jobs, investment. Environmental: woodland loss, air pollution. Social: displacement, hospital access. Overlap is real — air pollution is environmental in cause and social in effect (health). Saying so explicitly is what separates a strong answer from a mechanical one."},
  "MC-DEC-08":{type:"distinguish",title:"Describe, Explain, Justify",instruction:"Write the same content three ways about a proposed reservoir — once for each command word, one sentence each. Then state which assessment objective each serves.",answer:"Describe: 'Figure 3 shows the reservoir would flood 40 hectares of farmland in the valley floor.' (AO1/AO3 — features and patterns from evidence.) Explain: 'The valley floor floods because the dam raises water levels behind it.' (AO1/AO2 — reasons and causes.) Justify: 'The reservoir should still proceed, because Figure 5 shows the water shortfall affects 200,000 people, which outweighs the loss of 40 hectares.' (AO3 — a defended choice weighing evidence.)"},
  "MC-DEC-12":{type:"evaluate",title:"Why Include Contradictory Sources?",instruction:"A booklet contains one report predicting job creation and another predicting job losses from the same scheme. Explain why both are included, then say what a strong answer does with the contradiction.",answer:"Real geographical issues have contested evidence, and the sources have different authors with different interests — a mining company's own forecast is not as impartial as an independent economic study. A strong answer does not pick one and ignore the other, nor split the difference: it evaluates the SOURCE (who produced it, what they gain, what method they used) and weighs the evidence accordingly, saying so explicitly."},

  // ---- A-Level Psychology — Approaches, Biopsychology, Attachment, Memory, Social Influence ----
  "MC-APP-ORIGINS":{type:"correct",title:"What Did Wundt Actually Ask For?",instruction:"Find the error in this student sentence and write the correct version, including the year and place.",prompt:"'Wundt's introspection asked participants to describe their feelings and childhood memories in their own words.'",answer:"Introspection was STRUCTURED and standardised: trained participants broke down their conscious experience of a controlled stimulus into its component sensations, images and feelings, under identical conditions each time. Leipzig, 1879 — the first psychology laboratory. The point was replicability, which is why free description of memories is the opposite of the method."},
  "MC-APP-OPERANT":{type:"sort",title:"The Reinforcement Grid",instruction:"Draw a 2×2 grid: rows 'behaviour increases / decreases', columns 'something added / removed'. Place each example, then state the rule for the word 'negative'.",items:["A child is praised for tidying up","A rat presses a lever to switch off a loud noise","A driver is fined for speeding","Painkillers remove a headache, so you take them again","A student loses phone privileges for missing homework"],answer:"Positive reinforcement: praise. Negative reinforcement: switching off the noise, taking painkillers. Positive punishment: the fine. Negative punishment: losing phone privileges. The rule: 'reinforcement' ALWAYS means the behaviour increases; 'negative' means something is REMOVED, not that the outcome is unpleasant. Negative reinforcement and punishment are opposites, not synonyms."},
  "MC-APP-SLT":{type:"sequence",title:"ARMM in Order",instruction:"Name Bandura's four mediational processes in order and say what happens at each. Then explain what they add that behaviourism lacks.",answer:"Attention (you must notice the model) → Retention (you must remember what you saw) → Motor reproduction (you must be physically able to do it) → Motivation (you must want to, shaped by vicarious reinforcement). They sit between observing a model and imitating it. They are cognitive — internal processes standing between stimulus and response, which is exactly what traditional behaviourism refuses to include."},
  "MC-APP-COG":{type:"apply",title:"Schema in Action",instruction:"Write a one-sentence definition of a schema, then explain what your 'restaurant' schema predicts. Finish by giving one advantage and one cost of relying on schemas.",answer:"A schema is a package of knowledge built from experience that tells you what to expect and how to behave. The restaurant schema predicts being seated, given a menu, ordering, eating, then paying — so you can act without deliberating. Advantage: it lets you process huge amounts of information quickly. Cost: it distorts what you notice and recall, filling gaps with what SHOULD have happened rather than what did."},
  "MC-APP-BIO":{type:"distinguish",title:"Genotype or Phenotype?",instruction:"Label each as genotype, phenotype or both. Then explain why identical twins are the standard illustration.",items:["The DNA sequence a person inherits","Height at age 18","Eye colour","Being a carrier of a recessive allele with no visible sign","A twin who smokes and develops a cough"],answer:"Genotype: DNA sequence, carrier status. Phenotype: height, the cough. Eye colour is both — it is a visible characteristic produced by the code. Identical twins share a genotype but differ in phenotype (height, weight, health), proving the phenotype is the genotype INTERACTING with environment, not a readout of it."},
  "MC-APP-PSYDYN":{type:"compare",title:"Id, Ego, Superego",instruction:"Complete the table, then answer: what does the ego actually DO?",headers:["Structure","Present from","Principle","Conscious?"],rows:[["Id","","",""],["Ego","","",""],["Superego","","",""]],answer:"Id: from birth, pleasure principle, entirely unconscious. Ego: from about age 2, reality principle, partly conscious. Superego: from about age 5 (end of the phallic stage), morality principle, partly conscious. The ego is not a 'middle amount of personality' — it is the MEDIATOR, using defence mechanisms to manage the conflict between the id's demands and the superego's prohibitions."},
  "MC-APP-HUM":{type:"scenario",title:"Spot the Condition of Worth",instruction:"For each parental statement, decide whether it imposes a condition of worth or offers unconditional positive regard, and rewrite the conditional ones.",items:["'I love you.'","'I'll be proud of you if you get an A.'","'Good girls don't get angry.'","'I'm disappointed in what you did, but I love you.'"],answer:"Unconditional: 1 and 4 — 4 separates the behaviour from the person, which is the key move. Conditions of worth: 2 and 3. Rogers argued children internalise these, so self-acceptance becomes conditional and the gap between self-concept and ideal self widens — producing incongruence. Rewrites should praise or criticise the ACT, never the child's worth."},
  "MC-APP-COMPARE":{type:"classify",title:"Rank the Approaches on Free Will",instruction:"Place each approach on a line from hard determinism to free will, then justify the two ends.",items:["Behaviourist","Biological","Psychodynamic","Cognitive","Humanistic"],answer:"Hard determinism: behaviourist (environmental) and biological (genetic/neural) — behaviour is fully caused by forces outside conscious control. Psychodynamic: psychic determinism, unconscious conflict. Cognitive: soft determinism — choice within limits. Humanistic: free will, standing alone. That position is why the humanistic approach rejects the scientific reductionism of the others and treats people as active agents."},
  "MC-BIO-NS":{type:"diagram",title:"Branch the Nervous System",instruction:"Draw the nervous system as a branching diagram, dividing it twice. Label every branch, then name what each division does in four words or fewer.",answer:"Nervous system → central (brain, spinal cord) and peripheral. PNS → somatic (voluntary movement, carries sensory and motor information) and autonomic. Autonomic → sympathetic (arousal, fight-or-flight) and parasympathetic (rest and digest). The common error is putting the spinal cord in the PNS — it is central; the nerves LEAVING it are peripheral."},
  "MC-BIO-SYNAPSE":{type:"chain",title:"Across the Gap",instruction:"Complete the chain, then answer in one sentence: which parts are electrical and which chemical?",prompt:"Action potential arrives at presynaptic terminal → [step] → [step] → [step] → postsynaptic neuron is excited or inhibited.",answer:"Vesicles fuse with the membrane and release neurotransmitter into the synaptic cleft → neurotransmitter diffuses across and binds to receptors on the postsynaptic membrane → the signal is converted back into an electrical impulse (excitatory or inhibitory depending on the neurotransmitter and receptor). Transmission WITHIN a neuron is electrical; BETWEEN neurons it is chemical. Synaptic transmission is also unidirectional — a frequent exam point."},
  "MC-BIO-FIGHT":{type:"sequence",title:"Order the Acute Stress Response",instruction:"Put the stages in order, then name the hormone released and two of its physical effects.",items:["Adrenal medulla releases adrenaline","Amygdala appraises the threat","Sympathetic branch of the ANS is activated","Hypothalamus is signalled"],answer:"Amygdala appraises → hypothalamus signalled → sympathetic branch activated → adrenal medulla releases adrenaline. Effects: increased heart rate and blood pressure, dilated pupils, diverted blood from digestion to skeletal muscle, glucose released. This is the SAM pathway and it is acute — do not confuse it with the slower HPA axis, which handles sustained stress via cortisol."},
  "MC-BIO-LOCAL":{type:"distinguish",title:"Localisation or Holism?",instruction:"Label each claim L (localisation) or H (holistic), then name the region responsible for each function listed.",items:["Damage to a specific area removes a specific function","Every part of the brain contributes to every process","Broca's area","Wernicke's area","The motor cortex"],answer:"L: 1, 3, 4, 5. H: 2. Broca's area — speech PRODUCTION, left frontal lobe. Wernicke's area — language COMPREHENSION, left temporal lobe. Motor cortex — voluntary movement, frontal lobe (contralateral control). Localisation theory replaced the earlier holistic view; plasticity research is what partially rehabilitates holism."},
  "MC-BIO-SPLIT":{type:"chain",title:"Follow the Route",instruction:"Trace the pathway for an object shown to the LEFT visual field of a split-brain patient. Then explain why the patient can pick the object up with their left hand but cannot name it.",answer:"Left visual field → right hemisphere. In an intact brain the corpus callosum would carry this to the language centres in the LEFT hemisphere, so the person could name it. With the callosum cut, the information cannot cross. The right hemisphere controls the left hand, so the patient can select the object by touch — demonstrating the information IS there, just not available to the language centres. That dissociation is Sperry's whole point."},
  "MC-BIO-PLAST":{type:"compare",title:"Maguire vs Draganski",instruction:"Define plasticity in one sentence, then complete the table. Finish by stating what the two studies together show that neither shows alone.",headers:["Study","Participants","Finding"],rows:[["Maguire (2000)","",""],["Draganski (2006)","",""]],answer:"Plasticity is the brain's capacity to reorganise by forming new synaptic connections in response to learning and experience. Maguire: London taxi drivers, significantly more grey matter in the posterior hippocampus, correlated with years of service. Draganski: medical students, changes in the parietal cortex and hippocampus measured before and after final exams. Together: Maguire shows long-term structural change, Draganski shows it over MONTHS — so plasticity is not confined to childhood or to extreme cases."},
  "MC-BIO-SCAN":{type:"compare",title:"Pick the Right Scan",instruction:"Complete the table, then state which technique you would choose to study the timing of a response, and why.",headers:["Technique","What it measures","Main strength","Main weakness"],rows:[["fMRI","","",""],["EEG","","",""],["Post-mortem","","",""]],answer:"fMRI: blood oxygenation; excellent spatial resolution (1–2mm) and non-invasive; poor temporal resolution (~5s delay). EEG: electrical activity; excellent temporal resolution (milliseconds); poor spatial resolution. Post-mortem: physical brain structure after death; allows deep-brain examination; no causal link to living behaviour and no consent from the deceased. For timing, choose EEG — fMRI is too slow."},
  "MC-BIO-RHYTHM":{type:"sort",title:"Circadian, Infradian or Ultradian?",instruction:"Sort each rhythm by its duration, then state the rule that decides each category.",items:["Sleep-wake cycle","Menstrual cycle","Stages of sleep within one night","Core body temperature variation","Seasonal affective disorder","The 90-minute BRAC"],answer:"Circadian (about 24 hours): sleep-wake cycle, core body temperature (lowest around 4am). Infradian (LONGER than 24 hours): menstrual cycle (~28 days), SAD (annual). Ultradian (SHORTER than 24 hours): sleep stages, the 90-minute basic rest-activity cycle. The rule is duration relative to a day — 'infra' means below the FREQUENCY of daily, which is why it means a longer cycle. That inversion is what students get wrong."},
  "MC-ATT-02":{type:"sequence",title:"Eight Episodes, Five Behaviours",instruction:"Name the five behaviours the Strange Situation measures, then explain why reunion behaviour matters more than separation behaviour for classification.",answer:"Proximity seeking, exploration and secure-base behaviour, stranger anxiety, separation anxiety, and response to reunion. Reunion is decisive because it distinguishes types that look similar on separation: a Type A infant shows little distress AND avoids the caregiver on return, while a Type B infant shows distress but is easily soothed. It is a CONTROLLED OBSERVATION, not an experiment or interview — a frequent exam slip."},
  "MC-ATT-03":{type:"correct",title:"Is a Calm Baby Securely Attached?",instruction:"A student describes a Type B infant as 'one who doesn't cry at all when the caregiver leaves'. Say which type they have actually described, then give the correct description of all three.",answer:"They have described Type A (insecure-avoidant): little distress on separation, ignores or avoids the caregiver on reunion. Type B (secure): MODERATE distress, easily soothed on reunion, uses the caregiver as a safe base to explore. Type C (insecure-resistant): intense distress, but resists comfort on reunion — seeks and rejects simultaneously. Secure means well-REGULATED distress, not absent distress."},
  "MC-ATT-04":{type:"evaluate",title:"Judge the Strange Situation",instruction:"Sort each statement into strength or limitation, then write one sentence on the culture-bias criticism.",items:["Standardised and replicable with clear behavioural categories","May cause distress to the infant","High inter-rater reliability","Categories may not transfer across cultures","Lab-based and therefore artificial"],answer:"Strengths: standardisation, inter-rater reliability. Limitations: ethical distress, artificiality, cultural transferability. On culture bias: the procedure assumes separation anxiety indicates attachment quality, but in cultures where infants are rarely separated from mothers (Japan) distress may be extreme for reasons of unfamiliarity, and in cultures encouraging independence (Germany) low distress may be adaptive — so an imposed etic can misclassify normal behaviour as insecure."},
  "MC-ATT-05":{type:"chain",title:"From Infancy to Adult Relationships",instruction:"Complete the chain, then name the study that provides supporting evidence.",prompt:"Early attachment experience → [step] → [step] → adult relationship style.",answer:"The infant forms an internal working model — a mental representation of self, caregiver and what relationships are like → this acts as a TEMPLATE for expectations of others (trustworthy and responsive, or unreliable) → those expectations shape how the person behaves in later relationships, confirming the model. Hazan and Shaver's 'love quiz' found adult attachment styles correlated with recalled childhood attachment. The model is a set of expectations, not a memory."},
  "MC-ATT-06":{type:"distinguish",title:"Deprivation, Separation, Privation",instruction:"Define each of the three terms, then classify each case. Say which one Bowlby's hypothesis is actually about.",items:["A child in hospital for two weeks, visited daily","A child whose mother dies when they are 18 months old","A child raised in an institution who has never formed an attachment"],answer:"Separation: brief, attachment intact. Deprivation: prolonged loss of an existing attachment. Privation: an attachment never formed. Cases: 1 separation, 2 deprivation, 3 privation. Bowlby's maternal deprivation hypothesis concerns DEPRIVATION during the critical period (0–2.5 years), claiming irreversible damage — low IQ, delinquency, affectionless psychopathy. Rutter's key criticism is precisely that Bowlby conflated deprivation with privation."},
  "MC-ATT-07":{type:"evaluate",title:"44 Thieves — What Does It Prove?",instruction:"State Bowlby's findings with the figures, then give the two strongest methodological criticisms.",answer:"Of 44 juvenile thieves, 14 showed affectionless psychopathy, and 12 of those 14 had experienced prolonged early separation from their mothers, against just 2 of the remaining 30. Criticisms: (1) Bowlby conducted the assessments and the interviews himself knowing his hypothesis — investigator bias; (2) it is correlational and retrospective, relying on parental recall of events years earlier, so it cannot establish that separation CAUSED the psychopathy rather than accompanying poverty or family disruption."},
  "MC-ATT-08":{type:"compare",title:"Harlow vs Bowlby",instruction:"Complete the table, then state what Harlow's work disproves and what it does NOT establish.",headers:["Feature","Harlow (1958)","Bowlby"],rows:[["Species studied","",""],["Core claim","",""],["Method","",""]],answer:"Harlow: rhesus monkeys; contact comfort matters more than food; lab experiment with wire and cloth surrogates. Bowlby: humans; monotropy and the internal working model within a critical period; observation and interview. Harlow DISPROVES cupboard love — frightened infants ran to the cloth mother, not the feeding wire mother. He does NOT establish monotropy in humans; the surrogate-reared monkeys were later socially and sexually abnormal, which supports the critical-period idea but by extrapolation across species."},
  "MC-MEM-02":{type:"correct",title:"7±2, and What the ± Means",instruction:"A student says STM capacity is 'about 5 items'. Correct it, explain what chunking does to that figure, and give the later revision.",prompt:"Is BBCITVFBI nine items or three?",answer:"Miller's magic number is 7±2 — the range is part of the finding, not decoration. Chunking increases EFFECTIVE capacity by recoding items into meaningful units: BBCITVFBI is nine letters or three chunks, and capacity is measured in chunks. Cowan (2001) later argued four chunks is more accurate. The error is quoting a single number and dropping both the range and the chunking qualification."},
  "MC-MEM-03":{type:"diagnose",title:"What Could the MSM Not Explain?",instruction:"Name the MSM limitation that motivated the working memory model, then draw the WMM with all four components labelled.",prompt:"Evidence: people perform two VERBAL tasks together much worse than one verbal and one visual task.",answer:"The MSM treats STM as UNITARY — one store. If that were true, any two concurrent tasks would compete equally. They do not, so there must be separate subsystems. The WMM: central executive (attention controller) directing the phonological loop (verbal, subdivided into the phonological store and articulatory process) and the visuo-spatial sketchpad (visual and spatial), with the episodic buffer added in 2000 to integrate information and link to LTM."},
  "MC-MEM-04":{type:"correct",title:"The Central Executive Is Not a Store",instruction:"A student calls the central executive 'a big memory store with lots of capacity'. Give the two errors, then state what it actually does.",answer:"Error 1: it is not a store — it holds no information itself. Error 2: its capacity is LIMITED, not large — you cannot attend to everything at once. The central executive is the attentional controller: it decides what to focus on and allocates work to the slave systems. It is also the least well specified part of the model, which is the standard evaluation point — 'attention' is not a precise mechanism."},
  "MC-MEM-05":{type:"distinguish",title:"Response Bias or Memory Change?",instruction:"Loftus and Palmer found 'smashed' produced higher speed estimates than 'contacted' (about 41mph vs 32mph). State the two competing explanations, then say which finding from Experiment 2 decides between them.",answer:"Response bias: the verb influences the ANSWER GIVEN, leaving the memory intact. Substitution/memory change: the verb alters the stored memory itself. Experiment 2 decides it — a week later, the 'smashed' group were significantly more likely to report broken glass that was never in the film. Reporting a detail that did not exist cannot be explained by biased estimation of a real one, so post-event information had altered the memory."},
  "MC-MEM-06":{type:"classify",title:"Is It a Cognitive Interview Technique?",instruction:"Mark each Y or N. For each N, name what it actually is. Then state which technique the ENHANCED version adds.",items:["Report everything, including trivial detail","Mental reinstatement of context","Asking leading questions to prompt recall","Changing the temporal order of recall","Recalling from another person's perspective","Repeating the question until the answer changes"],answer:"Y: report everything, mental reinstatement, change of order, change of perspective — the four techniques. N: leading questions (the standard police interview practice the CI was designed to REPLACE) and repeating until the answer changes (pressure, which reduces accuracy). The enhanced CI adds social dynamics — building rapport, controlling eye contact and minimising anxiety."},
  "MC-SI-02":{type:"distinguish",title:"Kelman's Three Types",instruction:"Label each scenario compliance, identification or internalisation, then state which involves genuine private change and which is most durable.",items:["Agreeing with friends about a band in public, disagreeing privately","Adopting a new team's values while working there, dropping them on leaving","Becoming genuinely vegetarian after living with vegetarian housemates"],answer:"1 Compliance, 2 Identification, 3 Internalisation. Internalisation involves genuine private acceptance and is the most durable — it persists in the group's absence. Compliance is shallowest: behaviour changes, belief does not. The student error is defining compliance as 'genuinely changing your mind', which describes internalisation."},
  "MC-SI-04":{type:"correct",title:"Define the Agentic State",instruction:"Write a precise definition of the agentic state, name its opposite, and explain what triggers the shift between them.",answer:"The agentic state is acting as an AGENT of an authority figure, handing responsibility for one's actions to them — the person still knows the act is wrong but no longer feels answerable for it. Its opposite is the autonomous state, acting on one's own free will and accepting responsibility. The agentic SHIFT occurs when someone perceives another as a legitimate authority within an accepted social hierarchy. It explains why Milgram's participants showed visible distress yet continued."},
  "MC-SI-05":{type:"explain",title:"Why Consistency Works",instruction:"State Moscovici's key finding, then explain the mechanism by which a consistent minority changes a majority. Add the two other factors that strengthen minority influence.",answer:"In the blue-green slide study a consistent minority calling blue slides green produced agreement on about 8% of trials, far above an inconsistent minority. Mechanism: consistency forces the majority to engage in DEEPER PROCESSING — 'they keep saying it, maybe they have a point' — whereas an inconsistent minority is dismissed as mistaken. The other factors are commitment (the minority appears principled, e.g. through the augmentation principle of personal cost) and flexibility (rigid repetition is counterproductive)."},
  "MC-SI-06":{type:"scenario",title:"NSI or ISI?",instruction:"Label each case NSI or ISI, then state which type of conformity each typically produces and which is stronger under ambiguity.",items:["Laughing at a joke you didn't find funny so the group likes you","Copying the person next to you in a test because you don't know the answer","Following the crowd out of a building during an unclear alarm","Wearing what everyone else wears to avoid standing out"],answer:"NSI: 1, 4 — driven by the desire to be liked, produces compliance, strongest where the group can see you. ISI: 2, 3 — driven by uncertainty and the desire to be right, more likely to produce internalisation, strongest where the situation is AMBIGUOUS or the others appear expert. Asch's line task is mainly NSI (the answer is obvious); Sherif's autokinetic effect is ISI (genuinely ambiguous)."},

  // ---- A-Level Psychology — Research Methods, Issues & Debates, Cognitive Development, Forensic, Psychopathology, Stress ----
  "MC-RM-VAR":{type:"rewrite",title:"Operationalise It",instruction:"Rewrite each vague statement so both variables are operationalised precisely enough for another researcher to replicate exactly.",items:["Sleep affects memory","Noise affects concentration","Age affects reaction time"],answer:"E.g. 'Participants given 4 versus 8 hours of sleep recall fewer words from a 20-word list after 24 hours.' The test is replication: another researcher must be able to run the identical procedure from your description alone. 'Sleep' and 'memory' are constructs; '4 versus 8 hours' and 'words recalled from a 20-item list' are measurable operations."},
  "MC-RM-DESIGN":{type:"compare",title:"Three Designs, Three Problems",instruction:"Complete the table, then name the technique that controls order effects and explain how it works.",headers:["Design","Main weakness","Main strength"],rows:[["Repeated measures","",""],["Independent groups","",""],["Matched pairs","",""]],answer:"Repeated measures: order effects (practice or fatigue) and demand characteristics; but no participant variables and fewer participants needed. Independent groups: participant variables confound results; but no order effects. Matched pairs: time-consuming and never a perfect match; but controls both. Counterbalancing controls order effects — half do condition A then B, half B then A, so any practice or fatigue effect is spread evenly across both rather than favouring one."},
  "MC-RM-STATS":{type:"calculate",title:"One Outlier, Three Averages",instruction:"For the scores 2, 3, 3, 4, 88: calculate mean, median and mode. Then say which describes the data best and what that shows about the mean.",answer:"Mean = 100 ÷ 5 = 20. Median = 3. Mode = 3. The mean of 20 describes NOBODY in the set — every score is either far below it or far above it. That is the mean's weakness: it uses every value, so a single extreme score drags it. It is also its strength, and it is the most powerful measure, which is why it is preferred when data are interval and roughly symmetrical."},
  "MC-RM-TEST":{type:"match",title:"Choose the Test",instruction:"For each study, name the test. Say aloud the three decisions you make each time.",items:["Difference, independent groups, ordinal data","Difference, repeated measures, ordinal data","Correlation, ordinal data","Difference, independent groups, nominal data"],answer:"1 Mann-Whitney, 2 Wilcoxon, 3 Spearman's rho, 4 Chi-squared. The three decisions: (1) difference or correlation? (2) related design (repeated measures, matched pairs) or unrelated (independent groups)? (3) level of measurement — nominal, ordinal or interval? Students who memorise the table without the three questions cannot handle an unfamiliar scenario."},
  "MC-RM-VALID":{type:"distinguish",title:"Internal or External?",instruction:"Label each threat internal or external validity, then define both in one sentence each.",items:["A confounding variable the researcher did not control","Findings that only apply to psychology undergraduates","Participants guessing the aim and changing behaviour","Results from a 1970s study that may not hold today","An unreliable measure of the dependent variable"],answer:"Internal: confounding variable, demand characteristics, unreliable measure. External: undergraduate sample (population validity), historical change (temporal validity). Internal validity asks whether the study measured what it intended, free of confounds, so the effect can be attributed to the IV. External validity asks how far findings generalise — to other people, settings and times."},
  "MC-RM-SCIENCE":{type:"evaluate",title:"Three Jobs of Peer Review",instruction:"Name the three functions of peer review, then give one criticism of the process for each of two of them.",answer:"Functions: (1) allocating research funding; (2) validating the quality and accuracy of submitted work; (3) suggesting improvements before publication. Criticisms: anonymity can permit reviewers to bury a rival's work or protect an established position; there is publication bias towards positive, novel findings, so replications and null results go unpublished — which distorts the literature the review process is supposed to protect."},
  "MC-RM-EXPT":{type:"classify",title:"Which Kind of Experiment?",instruction:"Classify each as laboratory, field, natural or quasi-experiment. Then say what natural and quasi have in common and how they differ.",items:["Romanian orphan studies of institutionalisation","Memory tested under controlled conditions in a university lab","Helping behaviour measured on a real train","Comparing reaction times of men and women"],answer:"1 Natural, 2 Laboratory, 3 Field, 4 Quasi. Both natural and quasi lack random allocation, so causal claims are weaker. The difference: in a natural experiment the IV varies naturally through an event and the researcher measures the effect; in a quasi-experiment the IV is a pre-existing characteristic of the participant (sex, age) that cannot be manipulated at all. Natural experiments allow research that would be unethical to arrange — no committee would assign children to institutions."},
  "MC-ID-GENDER":{type:"distinguish",title:"Alpha or Beta Bias?",instruction:"Label each example, then state which type each is a form of, and why 'beta bias sounds harmless' is wrong.",items:["Freud's claim that women develop a weaker superego","Assuming fight-or-flight research on males applies to everyone","Claiming women are naturally better at nurturing","Drug trials conducted on men and dosed for all"],answer:"Alpha bias (EXAGGERATES difference, usually devaluing one sex): 1, 3. Beta bias (MINIMISES or ignores difference): 2, 4. Both are forms of androcentrism when the male is the standard. Beta bias is not harmless: ignoring difference means female physiology is never studied, so 'universal' findings and dosages are built on male data — Taylor's tend-and-befriend research exists precisely because a beta-biased literature had missed it."},
  "MC-ID-CULTURE":{type:"apply",title:"Spot the Imposed Etic",instruction:"For each case, decide whether the approach is emic, etic or an imposed etic. Then explain what makes the imposed etic an error rather than a choice.",items:["Studying one culture's child-rearing on its own terms","Seeking universal principles of memory across many cultures","Using the Strange Situation, developed in the USA, to classify Japanese infants"],answer:"1 Emic, 2 Etic, 3 Imposed etic. The error is not studying across cultures — it is taking a measure BUILT IN one culture, applying it elsewhere, and treating the results as if the measure were culture-free. Japanese infants show extreme distress on separation because it is rare in that culture, so the American scoring system misreads normal behaviour as insecure attachment. The tool imports its origin culture's assumptions."},
  "MC-ID-FREEWILL":{type:"classify",title:"Place It on the Determinism Line",instruction:"Label each position hard determinism, soft determinism or free will, then explain why soft determinism is the position most compatible with the legal system.",items:["Behaviour is entirely caused by prior events","Behaviour has causes, but people choose within those constraints","People are wholly self-determining agents","The cognitive approach's usual position","William James's position"],answer:"1 Hard determinism, 2 and 4 and 5 soft determinism, 3 free will (humanistic). Soft determinism, associated with James and adopted by the cognitive approach, holds that behaviour is caused but conscious choice operates within those constraints. It fits the legal system because law requires that people could have acted otherwise — hard determinism would make moral and criminal responsibility incoherent."},
  "MC-ID-NATURE":{type:"chain",title:"Diathesis Plus Stress",instruction:"Complete the chain, then explain why the model is INTERACTIONIST rather than a compromise between nature and nurture.",prompt:"Inherited vulnerability (diathesis) → [step] → disorder develops.",answer:"The predisposition alone does not produce the disorder — an environmental trigger (the stressor) must occur, and only then does the vulnerability express itself. Tienari's Finnish adoption study is the standard evidence: adoptees with a genetic risk of schizophrenia developed it far more often when raised in dysfunctional adoptive families. It is interactionist, not a midpoint: neither factor has an effect INDEPENDENT of the other, so the causes multiply rather than add."},
  "MC-ID-REDUCT":{type:"evaluate",title:"The Cost of Holism",instruction:"State the main criticism of holism, then give one approach that is holistic and one that is reductionist, and say what each gains and loses.",answer:"The criticism is that holism does not lend itself to rigorous scientific testing: if behaviour must be studied as an indivisible whole, no single variable can be isolated and manipulated, so predictions are hard to test and competing explanations hard to separate. Holistic: humanistic, and Jahoda's account of ideal mental health — gains validity and completeness, loses testability. Reductionist: biological (behaviour to neurotransmitters) — gains scientific credibility and effective drug treatments, loses the meaning of behaviour in context."},
  "MC-ID-IDIO":{type:"compare",title:"Idiographic vs Nomothetic",instruction:"Complete the table, then name one approach that uses each and explain why the distinction is a spectrum rather than a binary.",headers:["Feature","Idiographic","Nomothetic"],rows:[["Aim","",""],["Typical methods","",""],["Data type","",""]],answer:"Idiographic: understand the individual as unique; case studies, unstructured interviews, thematic analysis; qualitative. Used by humanistic and psychodynamic approaches. Nomothetic: establish general laws across people; experiments, correlations, psychometric testing; quantitative. Used by behaviourist, biological and cognitive approaches. It is a spectrum because case studies generate hypotheses that are then tested nomothetically — HM's case produced general claims about memory stores."},
  "MC-ID-ETHICS":{type:"evaluate",title:"Socially Sensitive Research",instruction:"Define social sensitivity as Sieber and Stanley did, then for each research area name the group at risk and the potential misuse.",items:["Heritability of intelligence","Genetic basis of sexual orientation","Reliability of eyewitness testimony"],answer:"Socially sensitive research has potential consequences for the participants or for the wider GROUP they represent. Intelligence heritability: ethnic and class groups — used historically to justify segregation and selective education policy. Sexual orientation: LGBT people — risk of framing orientation as a defect to be prevented or 'treated'. Eyewitness testimony: defendants and victims — findings change what courts accept as evidence, affecting real convictions. The point is that the ethics extend beyond the people in the room."},
  "MC-COG-PIAGET":{type:"scenario",title:"Assimilate or Accommodate?",instruction:"Label each case, then state the term for the discomfort that drives the change and complete the cycle.",items:["A child who knows 'dog' calls a cat a dog","The child learns cats and dogs are different and creates a new schema","A child who knows 'car' sees a lorry and calls it a big car","The child learns lorries carry goods and forms a separate schema"],answer:"Assimilate: 1, 3 — new information is forced into an EXISTING schema. Accommodate: 2, 4 — the schema itself is changed or a new one created. The driver is DISEQUILIBRIUM, the discomfort of a schema that no longer fits, resolved by accommodation to reach equilibration. The cycle: equilibrium → new experience → disequilibrium → accommodation → new equilibrium."},
  "MC-COG-VYGOTSKY":{type:"diagram",title:"Draw the ZPD",instruction:"Draw three nested regions: what the child can do alone, what they can do with help, and what remains out of reach. Label the ZPD, then state what Vygotsky reverses about Piaget.",answer:"The ZPD is the middle band — between current independent ability and potential ability with guidance from a more knowledgeable other. Learning happens INSIDE this zone. The reversal: for Piaget, development enables learning (a child cannot learn what their stage does not permit); for Vygotsky, LEARNING DRIVES DEVELOPMENT — instruction pitched into the ZPD pulls the child forward. That is why scaffolding is a Vygotskian idea and readiness is a Piagetian one."},
  "MC-COG-BAILLARGEON":{type:"diagnose",title:"What Did Piaget's Task Confound?",instruction:"Explain the flaw Baillargeon identified in Piaget's object permanence task, then describe how the violation of expectation method avoids it.",answer:"Piaget's search task requires the infant to REACH for a hidden object, so it confounds knowledge with motor ability — an infant may know the object still exists but lack the coordination or the memory-plus-planning to retrieve it. Failure to search is therefore not proof of failure to understand. Baillargeon measures LOOKING TIME instead: infants are familiarised with a possible event, then shown an impossible one, and look significantly longer at the impossible event — implying object permanence far earlier than Piaget claimed."},
  "MC-COG-SELMAN":{type:"explain",title:"Selman's Method and What It Found",instruction:"Name Selman's method, summarise the Holly dilemma in one sentence, and say what he was measuring — then give one limitation of the method.",answer:"Method: the clinical interview, using hypothetical scenarios. Holly has promised her father she will not climb trees but finds a friend's kitten stuck up one; children are asked how each person would feel. Selman was measuring social perspective-taking — the ability to represent another person's viewpoint as distinct from your own — and identified five levels from egocentric to societal. Limitation: it measures what children SAY about a hypothetical situation, which may not match how they act in a real one."},
  "MC-COG-TOM":{type:"explain",title:"What Makes Sally-Anne Hard?",instruction:"Describe the task in two sentences, state the correct answer, and explain precisely what cognitive step a child must take to give it.",answer:"Sally hides a marble in a basket and leaves the room; Anne moves it to a box; the child is asked where Sally will look for it. The correct answer is 'the basket'. To give it the child must represent Sally's BELIEF as separate from reality — holding in mind something they know to be false, and attributing it to another person. That is a false belief task, and Baron-Cohen used it to argue that children with autism have a specific difficulty with theory of mind rather than a general cognitive deficit."},
  "MC-COG-MIRROR":{type:"correct",title:"When Do Mirror Neurons Fire?",instruction:"Complete the definition precisely, then explain what makes the discovery significant and one reason for caution.",prompt:"'Mirror neurons are cells that fire when ___ and also when ___.'",answer:"They fire when an individual PERFORMS an action and also when they OBSERVE the same action performed by another. Rizzolatti's team found this accidentally — motor neurons in a monkey's premotor cortex fired as the monkey watched a researcher pick up food. Significance: the same cells code doing and seeing, offering a possible neural basis for imitation, intention-reading and empathy. Caution: most direct single-cell evidence is from monkeys, and the leap to human empathy and autism is inference, not demonstration."},
  "MC-COG-COMPARE":{type:"compare",title:"The Engine of Development",instruction:"Complete the table, then answer in one sentence: for each theorist, does learning cause development or does development permit learning?",headers:["Feature","Piaget","Vygotsky"],rows:[["Child is best described as","",""],["Main driver of development","",""],["Role of other people","",""],["Universal stages?","",""]],answer:"Piaget: a lone scientist constructing understanding through interaction with the physical world; driver is individual discovery through disequilibrium; others are peers who create cognitive conflict; yes, universal invariant stages. Vygotsky: an apprentice; driver is social interaction and cultural tools, especially language; the more knowledgeable other is essential; no, development is culturally variable. Piaget — development permits learning. Vygotsky — learning drives development."},
  "MC-FOR-PROFILE":{type:"compare",title:"Organised vs Disorganised",instruction:"Complete the table, then state where the typology came from and give the strongest criticism of it.",headers:["Feature","Organised offender","Disorganised offender"],rows:[["Planning","",""],["Crime scene","",""],["Victim","",""],["Likely social/work profile","",""]],answer:"Organised: planned in advance; controlled scene with little evidence left; targeted victim; likely socially and sexually competent, in skilled work, may be married. Disorganised: little planning, impulsive; chaotic scene with evidence left behind; random victim; likely socially immature, unskilled or unemployed, living alone. Source: the FBI's Behavioral Science Unit interviewed 36 sexually motivated murderers, including Bundy and Berkowitz. Criticism: a self-selecting sample of 36 manipulative offenders is a weak basis for a typology, and Canter's analysis found the two types are not statistically distinct — organised features appear across most cases."},
  "MC-FOR-GEO":{type:"distinguish",title:"Marauder or Commuter?",instruction:"Define both, then say what the circle theory assumes about offenders and what it needs in order to work.",answer:"A marauder operates OUT FROM a home base that lies within the circle enclosing their offences — so the centre of the circle approximates their base. A commuter travels AWAY from their home area to offend, so the circle contains no useful information about where they live. The assumption is that offenders reveal themselves through spatial behaviour, offending within a comfort zone they know. It needs a series of linked offences — a single crime yields no pattern — which is why geographical profiling is only useful for serial offending."},
  "MC-FOR-BIO":{type:"evaluate",title:"Lombroso — What Survives?",instruction:"State Lombroso's claim and two of his supposed atavistic features, then give the two strongest criticisms and say what, if anything, the theory contributed.",answer:"Claim (1876): criminals are a biologically primitive separate species, unable to adjust to civilised society, so offending is innate rather than chosen. Features included a strong prominent jaw, high cheekbones, extra nipples, toes or fingers. Criticisms: (1) no control group of non-criminals, so the features were never shown to distinguish anything; (2) the theory is scientifically racist, describing features common in people of African descent as primitive. Contribution: it shifted criminology towards seeking causes of offending rather than assigning moral blame — the beginning of a scientific approach, on entirely unsound evidence."},
  "MC-FOR-PSYCH":{type:"chain",title:"Eysenck's Three Dimensions",instruction:"Name the three dimensions and the biological basis of each, then complete the chain for extraversion.",prompt:"Underactive reticular activating system → [step] → [step] → offending more likely.",answer:"Extraversion (underactive RAS), neuroticism (reactive sympathetic nervous system), psychoticism (linked to high testosterone), measured by the EPQ. Chain: chronically under-aroused, the extravert seeks stimulation → they take risks and are harder to condition, since conditioning depends on responding to punishment → socialisation fails to instil the anxiety that normally inhibits offending. The criminal personality scores high on all three. Key criticism: Mischel's argument that personality is not consistent across situations undermines the idea of a stable criminal type."},
  "MC-FOR-COG":{type:"sequence",title:"Kohlberg's Six Stages",instruction:"Name the three levels and their two stages each, then state which level offenders are more likely to reason at and what characterises that reasoning.",answer:"Pre-conventional: (1) avoid punishment, (2) gain personal reward. Conventional: (3) gain approval, (4) maintain law and order. Post-conventional: (5) social contract, (6) universal ethical principles. Offenders are more likely to reason at the PRE-CONVENTIONAL level — a crime is wrong because you get caught, not because it harms someone, so if the punishment can be evaded the reason not to offend disappears. Note the qualification: this is more true of crimes involving personal gain than impulsive violence."},
  "MC-FOR-DIFF":{type:"explain",title:"Learned Like Anything Else",instruction:"State what Sutherland claims is learned, from whom, and what determines whether someone offends. Then give one strength and one limitation.",answer:"Two things are learned: attitudes towards the law, and the specific TECHNIQUES for committing offences — both acquired through interaction within intimate personal groups, not from the media or strangers. Offending follows when pro-criminal attitudes outweigh anti-criminal ones. Strength: it explains crime across all social classes, including white-collar crime, without appealing to biology or poverty. Limitation: the ratio of attitudes is not measurable, so the theory cannot be tested precisely or used to predict who will offend."},
  "MC-FOR-TREAT":{type:"apply",title:"Design a Token Economy",instruction:"Name the principle it applies, then specify: two target behaviours, what the tokens are technically called, and two exchangeable rewards. Finish with the main limitation.",answer:"Principle: operant conditioning. Target behaviours must be OPERATIONALISED IN ADVANCE — e.g. keeping a cell tidy, attending education sessions. Tokens are SECONDARY reinforcers: valueless in themselves, valuable through exchange. Rewards (primary reinforcers): phone calls, extra exercise time, canteen items. Limitation: behaviour learned for tokens rarely generalises beyond custody — once the reinforcement schedule stops on release, the behaviour extinguishes, so it manages the institution more effectively than it rehabilitates the offender."},
  "MC-PATH-DEF":{type:"evaluate",title:"Failure to Function — Where It Breaks",instruction:"Name Rosenhan and Seligman's signs, give the definition's main strength, then explain the two situations where it misclassifies.",answer:"Signs: not conforming to interpersonal rules, severe personal distress, irrational or dangerous behaviour. Strength: it takes the INDIVIDUAL'S OWN EXPERIENCE seriously and is a practical threshold for when someone needs help. It misclassifies in two directions: (1) behaviour that deviates from social norms but harms nobody — an unconventional lifestyle — can be read as dysfunction, so it is culturally relative; (2) someone with a serious disorder may continue functioning normally at work and be missed entirely. Functioning and disorder are not the same variable."},
  "MC-PATH-PHOB":{type:"chain",title:"Acquired vs Maintained",instruction:"Complete both halves of Mowrer's model with the correct conditioning type, then explain why avoidance is the reason phobias persist.",prompt:"Acquisition: neutral stimulus + frightening event → [type of conditioning]. Maintenance: avoid the stimulus → [what happens] → [type of conditioning].",answer:"Acquisition is CLASSICAL: a neutral stimulus paired with something frightening becomes a conditioned stimulus — Watson and Rayner's Little Albert. Maintenance is OPERANT: avoiding the stimulus removes the anxiety, which is NEGATIVE REINFORCEMENT, so the avoidance behaviour is strengthened. Avoidance is why phobias persist — it prevents the person from ever experiencing the feared stimulus without harm, so the association is never extinguished. That is also exactly why treatment requires exposure."},
  "MC-PATH-DEP":{type:"apply",title:"Run the ABC Model",instruction:"State what A, B and C stand for, then complete the model for the same event with a rational and an irrational belief. Say what this shows about where the emotion comes from.",prompt:"A: you fail an exam.",answer:"A = Activating event, B = Belief, C = Consequence (emotional and behavioural). Rational B: 'That went badly, I need a better revision plan' → C: disappointment, then action. Irrational B: 'I must succeed at everything or I am worthless' → C: depression, withdrawal. Same event, different consequence — so the EVENT does not cause the emotion, the BELIEF does. That is the whole basis of REBT: dispute the belief, not the event, since the event cannot be changed."},
  "MC-PATH-OCD":{type:"explain",title:"COMT and SERT",instruction:"State what each gene does, what the OCD-associated variant does to the neurotransmitter, then explain what 'candidate gene' and 'polygenic' mean here.",answer:"COMT regulates dopamine; the variant more common in OCD patients produces HIGHER dopamine levels. SERT affects serotonin transport; the associated variant produces LOWER serotonin. 'Candidate gene' means a gene suspected of contributing, not one that causes the disorder. 'Polygenic' means many genes each contribute a small amount — Taylor identified up to 230 implicated genes — so no single gene test is possible. The standard evaluation: concordance in identical twins is well short of 100%, so genes create vulnerability, not certainty."},
  "MC-STR-GAS":{type:"sequence",title:"Alarm, Resistance, Exhaustion",instruction:"Name Selye's three stages in order with what happens physiologically in each. Then explain why he called it GENERAL.",answer:"Alarm: the stressor is perceived and the sympathomedullary pathway activates — adrenaline, raised heart rate, fight-or-flight. Resistance: the body adapts and appears to cope, with cortisol sustaining the response, but resources are being depleted. Exhaustion: resources are spent, the adrenal glands can no longer maintain output, and stress-related illness follows — ulcers, immunosuppression, cardiovascular damage. It is GENERAL because Selye exposed rats to widely different stressors and found the SAME physiological response regardless of the cause."},
  "MC-STR-HPA":{type:"chain",title:"The HPA Chain in Order",instruction:"Complete the chain naming each structure and hormone. Then state what distinguishes this pathway from the SAM pathway.",prompt:"Sustained stressor → hypothalamus → [hormone] → [structure] → [hormone] → [structure] → [hormone].",answer:"Hypothalamus secretes corticotrophin releasing hormone (CRH) → anterior pituitary secretes adrenocorticotrophic hormone (ACTH) → adrenal CORTEX secretes cortisol. Distinction: SAM is the ACUTE response — fast, adrenaline, adrenal MEDULLA, seconds. HPA is the CHRONIC response — slower, cortisol, adrenal CORTEX, minutes to hours, and sustained. Cortisol maintains glucose supply but suppresses immune function, which is the link to stress-related illness."},
  "MC-STR-LIFE":{type:"evaluate",title:"What the SRRS Measures",instruction:"State what the SRRS actually counts and give the top and bottom of its scale. Then give the two strongest criticisms.",answer:"It lists 43 life events ranked by the amount of READJUSTMENT each demands, from death of a spouse at 100 life change units down to minor violations of the law at 11; participants total the units for events in the past year. Criticisms: (1) it counts positive events (marriage, promotion) alongside negative ones as equally stressful, when the evidence suggests they differ; (2) it ignores individual differences in appraisal and ignores DAILY HASSLES, which several studies find predict health outcomes better than major life events do."},
  "MC-STR-DRUGS":{type:"chain",title:"How Benzodiazepines Calm",instruction:"Complete the chain, then contrast the mechanism with beta blockers and say which symptom each targets.",prompt:"BZ binds to GABA receptor → [step] → [step] → anxiety reduced.",answer:"The BZ enhances GABA's inhibitory effect at the receptor → more chloride ions enter the neuron → the neuron is hyperpolarised and less likely to fire, producing generalised reduced arousal. Beta blockers work entirely differently: they act on the heart and blood vessels, blocking adrenaline at beta-adrenergic receptors to lower heart rate and blood pressure. BZs target the PSYCHOLOGICAL experience of anxiety via the CNS; beta blockers target the PHYSICAL symptoms and leave the felt anxiety largely intact."},

  // ---- A-Level Economics — Themes 1 and 2 ----
  "MC-GRO-02":{type:"distinguish",title:"Actual or Potential Growth?",instruction:"For each case, state which type of growth and which diagram you would draw. Then say why examiners treat the confusion as a major error.",items:["Income tax cut raises consumer spending and short-run real GDP","Investment in education raises workforce skills","Discovery of a new oil field","Recovery from recession as spare capacity is used"],answer:"Actual growth (AD shifts right, movement along or towards LRAS): 1 and 4. Potential growth (LRAS shifts right): 2 and 3. They require DIFFERENT diagrams and different policies — actual growth uses existing capacity, potential growth expands the ceiling. An answer that treats a tax cut as raising productive potential has misunderstood which curve moves, so no amount of accurate detail afterwards can rescue it."},
  "MC-GRO-04":{type:"diagram",title:"Label the Trade Cycle",instruction:"Draw a trade cycle with a trend line. Label boom, downturn, recession, trough and recovery in the right places. Then define recession precisely and mark where it sits relative to the trend.",answer:"Sequence: boom (above trend) → downturn → recession → trough (lowest point) → recovery (GDP rising back towards trend) → boom. Recession is two consecutive quarters of NEGATIVE growth — a fall in real GDP, not merely growth below trend. Recovery is the upswing: GDP is rising, but still below trend, which is why students who draw it flat lose the mark. Output can be growing while still below potential."},
  "MC-GRO-05":{type:"explain",title:"Why PPP, Not Market Rates?",instruction:"Explain in two sentences why PPP exchange rates are used for cross-country GDP comparison, using a specific example of a non-traded good.",answer:"Market exchange rates are driven by traded goods and by speculative capital flows, so they reveal little about what money actually buys at home. A haircut, a bus fare or a bowl of rice costs far less in a low-income country, so converting at market rates understates real living standards there — PPP adjusts for the domestic cost of a comparable basket, which is why PPP-adjusted GDP per capita gaps are consistently narrower than market-rate ones."},
  "MC-GRO-06":{type:"evaluate",title:"The Easterlin Paradox",instruction:"State the paradox precisely — what holds within a country and what fails across time. Then give the two standard explanations and one policy implication.",answer:"Within a country at a point in time, richer people report greater happiness; but as a whole country grows richer over decades, average reported happiness barely moves. Explanations: (1) RELATIVE income — what matters is your position against others, and growth raises everyone; (2) the HEDONIC TREADMILL — people adapt to a higher standard and reset their expectations. Implication: raising GDP is not a sufficient objective, which is why governments have begun measuring wellbeing directly alongside output."},
  "MC-INF-04":{type:"sort",title:"What Else Pushes Costs Up?",instruction:"Wages are one cause of cost-push inflation. Sort these into cost-push causes and things that are NOT, then draw what happens on AD/AS.",items:["Oil price shock","A rise in consumer confidence","Sterling depreciation raising import prices","An increase in VAT","Government spending increase","A fall in labour productivity"],answer:"Cost-push: oil shock, depreciation, VAT rise, falling productivity (raises unit labour costs). NOT cost-push: consumer confidence and government spending — those are DEMAND-pull, shifting AD right. Cost-push shifts SRAS LEFT, raising the price level while REDUCING output — the distinguishing signature. Demand-pull raises price level and output together."},
  "MC-INF-05":{type:"evaluate",title:"Is All Deflation Bad?",instruction:"Distinguish malign from benign deflation, giving the cause and one real example of each. Then say which one Japan experienced and why it was so hard to escape.",answer:"Malign: falling AD → lower prices alongside falling output, rising unemployment, and a rising REAL debt burden → consumers delay purchases expecting further falls → a deflationary spiral. Benign: productivity gains or technological progress shift SRAS right → lower prices WITH rising output, as in consumer electronics. Japan in the 1990s–2000s experienced malign deflation; it was hard to escape because nominal interest rates hit zero, so conventional monetary policy could not lower real rates further."},
  "MC-INF-06":{type:"compare",title:"CPI vs RPI",instruction:"Complete the table, then state which is the official measure and why the other was downgraded.",headers:["Feature","CPI","RPI"],rows:[["Averaging method","",""],["Mortgage interest included?","",""],["Council tax included?","",""],["Usually higher or lower?","",""]],answer:"CPI: geometric mean; excludes mortgage interest payments and council tax; usually LOWER. RPI: arithmetic mean; includes mortgage interest; usually HIGHER. CPI is the official target measure (2%). RPI lost its National Statistic status because of a formula effect — the arithmetic mean introduces an upward bias — though it is still used for some index-linked contracts, which is why the gap between them has real fiscal consequences."},
  "MC-EMP-02":{type:"classify",title:"Which Unemployment, Which Policy?",instruction:"Classify each case and give the policy that would actually address it. The policy is the point — the wrong classification produces the wrong policy.",items:["Coal mines close permanently; workers' skills don't match tech vacancies","A graduate spends two months searching for their first job","Demand collapses in a recession and firms lay off across all sectors","Hotel staff laid off at the end of the summer season"],answer:"1 Structural → retraining, relocation support, education. 2 Frictional → better job-matching information, employment services. 3 Cyclical (demand-deficient) → expansionary fiscal or monetary policy to raise AD. 4 Seasonal → diversification of the local economy. Using demand-side policy against structural unemployment is the classic error: raising AD cannot help if the vacancies require skills the unemployed do not have."},
  "MC-EMP-04":{type:"compare",title:"Claimant Count vs ILO",instruction:"UK claimant count 1.6m, ILO unemployment 1.4m. Complete the table, then give two reasons the figures differ.",headers:["Feature","Claimant count","ILO/LFS measure"],rows:[["Data source","",""],["Who is counted","",""],["Cost and speed","",""]],answer:"Claimant count: administrative data on those claiming Universal Credit or JSA for unemployment reasons; cheap and fast but changes whenever eligibility rules change. ILO: Labour Force Survey — those out of work, actively seeking and available to start within two weeks; internationally comparable but slower and sample-based. Differences: some claimants are not actively seeking (so excluded from ILO) while some genuine job seekers do not qualify for or do not claim benefits (so excluded from the claimant count)."},
  "MC-EMP-05":{type:"diagram",title:"Label the Gap",instruction:"Draw a labour market diagram with a minimum wage set above equilibrium. Label W_min, Qd, Qs and the gap. Name the gap precisely, then say what the gap is NOT.",answer:"At W_min, quantity of labour supplied exceeds quantity demanded. The gap (Qs − Qd) is REAL-WAGE (classical) unemployment. It is NOT the total number of unemployed people in the economy, and it is NOT the number who lost jobs — part of the gap is workers newly ATTRACTED into the market by the higher wage who cannot find work. Losing that distinction is what costs the mark."},
  "MC-EMP-08":{type:"chain",title:"Why Temporary Becomes Permanent",instruction:"Complete the chain, then explain what hysteresis implies about how quickly a government should respond to a recession.",prompt:"Recession causes job losses → [step] → [step] → [step] → the unemployment persists after recovery.",answer:"Long spells out of work erode skills and up-to-date experience → workers lose contact with workplace routines and networks → employers use long unemployment as a screening signal and stop interviewing them → they become effectively unemployable, so the natural rate itself rises. Implication: acting fast matters more than acting perfectly — a temporary demand shock left untreated inflicts PERMANENT supply-side damage, which is the core argument for early intervention."},
  "MC-BOP-01":{type:"evaluate",title:"Is a 3.1% Deficit Bad?",instruction:"A student writes that the UK's current account deficit is 'very bad'. Give two conditions under which it matters and two under which it does not. Finish with the decisive question.",answer:"It matters if: financed by short-term 'hot money' that can reverse suddenly (a sudden stop → currency crisis); or if it reflects declining competitiveness and a hollowed-out export base. It does not matter much if: financed by long-term FDI, which brings productive capacity; or if it reflects strong domestic growth pulling in capital imports and investment goods. The decisive question is HOW IT IS FINANCED and WHAT THE IMPORTS ARE — deficits funding investment differ fundamentally from deficits funding consumption."},
  "MC-BOP-04":{type:"correct",title:"The Missing Condition",instruction:"A student claims a depreciation will 'definitely' improve the current account. Name the condition they have ignored, state it precisely, and explain what happens if it fails.",answer:"The Marshall-Lerner condition: a depreciation improves the current account ONLY IF PEDx + PEDm > 1. If the sum is below 1, demand is too inelastic for volume effects to outweigh the worsened price effect — imports simply cost more for roughly the same quantity — so the current account WORSENS. This also explains the J-curve: elasticities are low in the short run as contracts and habits adjust, so the balance deteriorates before it improves."},
  "MC-BOP-05":{type:"sort",title:"Four Components, One Account",instruction:"Name the four components of the current account, then classify each transaction.",items:["UK exports of cars to Germany","A UK bank selling insurance to a US firm","Dividends paid to a UK resident holding foreign shares","UK government foreign aid payment","A German tourist's hotel spending in London"],answer:"Components: trade in goods (visible balance), trade in services (invisible), primary income (investment income and wages from abroad), secondary income (transfers — aid, remittances). Classification: 1 goods, 2 services, 3 primary income, 4 secondary income, 5 SERVICES (tourism is an export of services — the standard trap, since no physical good crosses a border)."},
  "MC-BOP-06":{type:"sort",title:"Switching or Reducing?",instruction:"Sort each policy, then explain the mechanism that distinguishes the two families and give one drawback of each.",items:["Devaluation of the currency","Raising income tax","Imposing tariffs on imports","Cutting government spending","Import quotas","Raising interest rates"],answer:"Expenditure-SWITCHING (redirect spending from foreign to domestic goods without cutting total spending): devaluation, tariffs, quotas. Expenditure-REDUCING (cut total demand, so imports fall with everything else): income tax rise, spending cuts, higher rates. Drawbacks: switching invites retaliation and breaches trade agreements; reducing lowers growth and raises unemployment — it treats the deficit by shrinking the economy."},
  "MC-BOP-08":{type:"explain",title:"Why the Accounts Must Balance",instruction:"Explain in two sentences why a current account deficit must be matched elsewhere in the balance of payments, then name what the country is doing in real terms.",answer:"The balance of payments balances by construction: a current account deficit means the country buys more from abroad than it sells, and those purchases must be paid for — by selling assets to foreigners or borrowing from them, which is recorded as a financial account SURPLUS. In real terms the country is running down its net foreign asset position: consuming more than it produces and financing the gap by transferring ownership of assets or incurring future obligations."},
  "MC-AD-03":{type:"chain",title:"Confidence to AD",instruction:"Complete the chain, then state which curve moves and which definitely does NOT.",prompt:"Consumer confidence falls → [step] → [step] → AD shifts ___.",answer:"Households become uncertain about future income and employment → precautionary saving rises and big-ticket purchases are deferred → consumption falls → AD shifts LEFT. Confidence is a DEMAND-side factor: it does not change firms' production costs, so SRAS does not move, and it does not change productive capacity, so LRAS does not move. Students who shift SRAS for a confidence shock have confused a willingness-to-spend change with a cost change."},
  "MC-AD-05":{type:"chain",title:"Depreciation to Net Exports",instruction:"Trace the effect of a sterling depreciation through to AD in two branches, then name the assumption the whole chain rests on.",prompt:"Sterling depreciates → [branch X] → [branch M] → net exports → AD.",answer:"Exports branch: UK goods are cheaper in foreign currency → more competitive abroad → X rises. Imports branch: foreign goods cost more in sterling → consumers switch to domestic substitutes → M falls. Both raise (X − M), a component of AD, so AD shifts right. The assumption: the Marshall-Lerner condition holds (PEDx + PEDm > 1). Without it the volume responses are too weak and the chain fails."},
  "MC-AD-06":{type:"distinguish",title:"Move Along or Shift?",instruction:"For each change, state movement along AD or shift of AD, and give the reason. Then name the three effects that make AD slope downwards.",items:["The general price level rises","Government increases infrastructure spending","Interest rates are cut","CPI inflation falls to 1%"],answer:"Movement ALONG: 1 and 4 — only a change in the PRICE LEVEL moves you along the curve. Shift: 2 and 3 — changes to C, I, G or (X−M) from any other cause. The three effects behind the downward slope: the real balance effect (savings buy less), the interest rate effect (higher prices raise money demand and rates), and the trade effect (domestic goods become less competitive)."},
  "MC-AD-08":{type:"calculate",title:"MPC or APC?",instruction:"Income rises from £20,000 to £25,000; consumption rises from £18,000 to £21,500. Calculate both the MPC and the new APC, then state which one drives the multiplier.",answer:"MPC = change in consumption ÷ change in income = £3,500 ÷ £5,000 = 0.7. APC = total consumption ÷ total income = £21,500 ÷ £25,000 = 0.86. They are different questions: MPC is about the EXTRA pound, APC about the whole income. The MULTIPLIER depends on the MPC (or on marginal withdrawals), not the APC — using the average in the multiplier formula is the error this tests."},
  "MC-AS-02":{type:"sort",title:"Which Way Does SRAS Move?",instruction:"Sort each into 'shifts SRAS left' or 'shifts SRAS right', then state the single test that decides every case.",items:["Wage rises above productivity growth","Fall in world oil prices","Increase in VAT","Sterling appreciation lowering import costs","New energy price cap raising business tariffs"],answer:"Left (costs rise): wage rises above productivity, VAT increase, higher energy tariffs. Right (costs fall): falling oil prices, appreciation cutting import costs. The single test: does it change the COST OF PRODUCTION at each price level? If yes, SRAS moves — up-and-left for higher costs. If it changes willingness to buy rather than cost to produce, it is AD."},
  "MC-AS-04":{type:"sort",title:"What Actually Shifts LRAS?",instruction:"Sort into 'shifts LRAS right' and 'does not shift LRAS', then state the test.",items:["Investment in new capital equipment","A cut in interest rates","Improved education and training","A rise in consumer spending","Deregulation of a protected industry","Net inward migration of working-age people"],answer:"Shifts LRAS right: capital investment, education and training, deregulation, inward migration. Does not: interest rate cut and consumer spending — both raise AD only. The test: does it change the QUANTITY OR QUALITY of the factors of production, or remove a barrier to their efficient use? Anything that merely raises willingness to spend leaves productive capacity untouched."},
  "MC-AS-06":{type:"calculate",title:"Unit Labour Costs",instruction:"Wages rise 6%; productivity rises 2%. State what happens to unit labour costs, which curve moves and in which direction, and name the type of inflation produced.",answer:"Unit labour cost = wage cost per unit of output, so it rises by roughly 4% — wages are outpacing what each worker produces. Each unit costs more, so SRAS shifts LEFT, raising the price level while reducing output: COST-PUSH inflation. The reverse is the key policy point — if productivity growth matches or exceeds wage growth, wages can rise with no inflationary pressure at all, which is why productivity is the central supply-side objective."},
  "MC-AS-07":{type:"diagram",title:"Three Sections, Three Policies",instruction:"Draw the Keynesian AS curve. Label the horizontal, upward-sloping and vertical sections, and write the effect of an AD increase in each.",answer:"Horizontal section — deep recession with mass unemployment: idle workers and machines can be brought into use, so raising AD increases OUTPUT with no price rise. Fiscal stimulus is effective here. Upward-sloping section — spare capacity shrinking: AD raises both output and prices. Vertical section — full capacity: raising AD is PURELY INFLATIONARY, output cannot rise. The whole point of the shape is that the right policy depends on where the economy currently sits."},
  "MC-NI-03":{type:"distinguish",title:"GDP or GNI?",instruction:"Define both, then decide which is larger for each country and say what that reveals.",items:["Ireland, with large foreign-owned multinationals repatriating profits","The Philippines, with many citizens working abroad and sending money home"],answer:"GDP = output produced WITHIN borders regardless of ownership. GNI = GDP + net primary income from abroad. Ireland: GDP much LARGER than GNI, because profits earned in Ireland flow out to foreign owners — GDP overstates what Irish residents actually receive. Philippines: GNI larger than GDP, because remittances flow in. The gap reveals who OWNS the income, which is why GNI is the better living-standards measure."},
  "MC-NI-04":{type:"calculate",title:"Strip Out the Inflation",instruction:"Nominal GDP rises 6%; inflation is 4%. State approximate real growth and explain what real GDP holds constant. Then say which one you must use to compare 2015 with 2025.",answer:"Real growth ≈ 6% − 4% = 2%. Real GDP values output at BASE-YEAR prices, holding the price level constant so that only changes in the quantity of goods and services show up. Nominal GDP can rise purely because prices rose, with output unchanged. Any comparison across time — or any growth rate — must use REAL GDP, otherwise inflation is counted as if it were extra output."},
  "MC-NI-06":{type:"evaluate",title:"Two Marks, One Limitation",instruction:"Write a full 2-mark answer giving ONE limitation of GDP for comparing living standards: state it, then develop it. Then list three other limitations you did not use.",answer:"Model answer: 'GDP per capita ignores the DISTRIBUTION of income (1), so a country with high average income but extreme inequality may have most of its population living in poverty despite a high GDP figure (1).' The structure is point plus development — a list of five undeveloped limitations scores 1. Others available: no PPP adjustment for cost of living, excludes the informal economy, ignores environmental degradation, omits unpaid household and voluntary work, says nothing about leisure or working hours."},
  "MC-NI-08":{type:"distinguish",title:"Three Methods, One Number",instruction:"Name the three methods of measuring GDP and what each sums. Then explain why the output method uses VALUE ADDED rather than total sales.",answer:"Output/production: sum of value added by each industry. Income: sum of factor incomes — wages, profits, rent, interest. Expenditure: C + I + G + (X − M). All three yield the same figure, because one person's spending is another's income is another's output. Value added is used to avoid DOUBLE COUNTING: if you summed total sales, the steel in a car would be counted when sold to the manufacturer and again inside the finished car."},
  "MC-TECH-01":{type:"diagnose",title:"Answer the Question Set",instruction:"A student asked about METHODS OF RAISING tax revenue writes entirely about what the government could spend it on. Name the error, then list what the answer should have covered.",answer:"The error is answering an adjacent question rather than the one set — flagged explicitly in the 2022 examiner report. Methods of RAISING revenue means: which taxes (income, VAT, corporation, capital gains), at what rates, on what base; direct versus indirect; the incidence and elasticity implications; the Laffer curve; and administrative feasibility and avoidance. Spending is a different topic. No amount of accurate economics scores if it is not the economics asked for."},
  "MC-TECH-02":{type:"rewrite",title:"Add the Evaluation",instruction:"A 12-mark answer (8 KAA + 4 EV) on expansionary fiscal policy and unemployment contains only analysis. Write three evaluation sentences that would earn the EV marks.",prompt:"Question: Evaluate whether expansionary fiscal policy is the most effective way to reduce unemployment.",answer:"1. 'This depends on the TYPE of unemployment: fiscal stimulus raises AD and so addresses cyclical unemployment, but cannot help structural unemployment where the skills mismatch remains.' 2. 'The size of the effect depends on the multiplier, which is smaller where the MPM is high, so much of the stimulus leaks abroad.' 3. 'In the long run, supply-side policies such as retraining may be more effective, though they act far more slowly and cost more up front.' EV means weighing magnitude, conditions and alternatives — not adding 'however, it could be argued'."},
  "MC-MON-03":{type:"chain",title:"The Cost of Raising Rates",instruction:"Complete the chain for a rate rise, then name three trade-offs the student's claim ignores.",prompt:"Base rate rises → [step] → [step] → inflation falls.",answer:"Borrowing costs rise and saving becomes more attractive → consumption and investment fall, and the exchange rate appreciates, reducing net exports → AD falls, easing demand-pull inflation. Trade-offs ignored: (1) lower growth and higher unemployment — the Phillips curve trade-off; (2) mortgage holders and indebted firms are hit hardest, so the burden is distributionally uneven; (3) it is ineffective against COST-PUSH inflation, where the cause is supply-side, and may deepen the downturn without addressing the source."},
  "MC-SSP-01":{type:"diagram",title:"Which Curve Do Supply-Side Policies Move?",instruction:"Draw AD/LRAS and show the effect of a successful supply-side policy. State the two things it must do to count, then give the twin benefit it uniquely delivers.",answer:"LRAS shifts RIGHT. To count, a policy must either improve the QUANTITY OR QUALITY of the factors of production (labour, capital, enterprise, land) or remove a barrier to efficient use. The unique twin benefit: output rises AND the price level falls — supply-side policy is the only route to growth without inflation, which is why it is the standard evaluation counterweight to demand-side stimulus. Its weakness is the long time lag."},
  "MC-SSP-02":{type:"sort",title:"Market-Based or Interventionist?",instruction:"Sort each policy, then state the ideological difference in one sentence and give one criticism of each family.",items:["Deregulation of a protected industry","Government spending on adult skills training","Cutting corporation tax","Infrastructure investment in rail","Trade union reform","Subsidies for business R&D"],answer:"Market-based: deregulation, corporation tax cut, trade union reform. Interventionist: skills training, rail infrastructure, R&D subsidies. Difference: market-based policies remove government from markets to sharpen incentives; interventionist policies use government spending to correct market failures in provision. Criticisms: market-based policies can worsen inequality and job security; interventionist policies carry high opportunity cost and risk government failure in picking winners."},
  "MC-INQ-04":{type:"rewrite",title:"Two Marks on Inequality",instruction:"Write a 2-mark answer giving ONE cause of UK income inequality — state it, then develop it with a mechanism. Then name three other causes.",answer:"Model answer: 'Differences in education and skills cause income inequality (1), because higher-skilled workers command higher wages in a labour market where demand for graduate-level skills has grown faster than supply (1).' Others available: regional economic imbalances, discrimination, globalisation (skilled workers gain while unskilled face import competition), technological change automating routine jobs, and the design of the tax and benefit system. The mark is for the MECHANISM, not the label."},
  "MC-INQ-05":{type:"distinguish",title:"Stock or Flow?",instruction:"Classify each as income or wealth, then give the case that proves they are independent.",items:["Annual salary of £30,000","A house worth £400,000","State pension payments","A pension pot of £250,000","Dividends received this year"],answer:"Income (a FLOW, £ per year): salary, state pension payments, dividends. Wealth (a STOCK, £ at a point in time): the house, the pension pot. The proof they are independent: an asset-rich retiree with a paid-off house and a large pension pot may have a very low annual income, while a high-earning graduate with student debt has high income and NEGATIVE wealth. The 2019 examiner report flagged this confusion specifically."},
  "MC-INQ-07":{type:"calculate",title:"Progressive, Proportional or Regressive?",instruction:"For each tax, calculate the share of income paid by someone on £15,000 and someone on £60,000, then classify the tax.",items:["A flat £1,000 charge on everyone","20% of all income","UK income tax: 20% basic, 40% higher"],answer:"1: 6.7% vs 1.7% — REGRESSIVE (falls more heavily on lower incomes as a proportion). 2: 20% vs 20% — PROPORTIONAL. 3: rising marginal rate means a rising average rate — PROGRESSIVE. The definition turns on the PROPORTION OF INCOME paid, not the cash amount: VAT is regressive even though everyone pays the same rate, because lower earners spend a larger share of their income."},
  "MC-POV-01":{type:"distinguish",title:"Absolute or Relative?",instruction:"Define both with their standard thresholds, then explain how a country can eliminate one while the other rises.",answer:"Absolute poverty: a FIXED standard — can you afford the basic necessities of survival? World Bank line $2.15 a day. Relative poverty: a MOVING standard — how far below typical income are you? UK measure: below 60% of median income. A country can grow so that everyone clears the absolute threshold while incomes at the top pull away from the median, raising relative poverty. Absolute poverty measures deprivation; relative poverty measures inequality — which is why they can move in opposite directions."},
  "MC-POV-04":{type:"evaluate",title:"Which Policy Hits Absolute Poverty?",instruction:"Rank these by how DIRECTLY each reduces absolute poverty, and justify your top and bottom choices.",items:["Raising the National Living Wage","Free school meals and social housing","Cutting corporation tax to stimulate growth","Increasing Universal Credit payments"],answer:"Most direct: increasing Universal Credit and providing essentials in kind (free school meals, social housing) — they raise the floor immediately for those below it. The National Living Wage is direct but reaches only those IN WORK, missing the poorest who are not. Least direct: corporation tax cuts, which rely on a long and uncertain trickle-down chain through investment and employment. Directness matters because absolute poverty is urgent — a policy that works in five years does not feed anyone this winter."},
  "MC-FMK-01":{type:"classify",title:"Is That a Role of Financial Markets?",instruction:"Mark each Y or N. For each Y, name which of the six roles it is.",items:["Offering deposit accounts and bonds","Providing mortgages and business loans","Setting the government's fiscal policy","Operating payment and settlement systems","Forward markets in commodities and currencies","Enabling equity trading in a secondary market"],answer:"Y: 1 (facilitating saving), 2 (lending to individuals and firms), 4 (facilitating exchange of goods and services), 5 (providing forward markets to hedge risk), 6 (providing a market for equities). N: 3 — fiscal policy is set by government, not markets. The six roles are examined directly, and the equity role has two halves: raising new capital in the primary market and providing liquidity in the secondary market."},
  "MC-FMK-03":{type:"distinguish",title:"Adverse Selection or Moral Hazard?",instruction:"Label each case, then state the timing rule that separates them.",items:["Riskier borrowers are the most likely to apply for a loan","A bank takes excessive risk knowing it will be bailed out","Someone buys insurance then drives less carefully","Only people expecting to claim buy the extended warranty"],answer:"Adverse selection: 1, 4 — the problem exists BEFORE the contract, in who chooses to enter it. Moral hazard: 2, 3 — the problem arises AFTER the contract, in changed behaviour once protected. The timing rule: adverse selection is about SELECTION into the deal, moral hazard about BEHAVIOUR once inside it. Both stem from asymmetric information — the borrower knows their own risk and the lender does not — and both were central to 2008's 'too big to fail'."},
  "MC-BNK-03":{type:"evaluate",title:"Was the 2008 Bailout Right?",instruction:"Write a 4-mark evaluation: one sentence for, one against, and a judgement with a condition. Use at least two of the four concepts the examiner report identified.",answer:"For: systemic risk meant a major bank's failure would have cascaded through the payments system and the wider economy, as the run on Northern Rock demonstrated in miniature. Against: the bailout created moral hazard — banks rescued once have an incentive to take excessive risk again — and carried a large opportunity cost in public funds. Judgement: intervention was justified given the systemic threat, but only if paired with structural reform (ring-fencing, higher capital requirements) that reduces the chance of repetition — otherwise the rescue purchases stability now at the cost of a larger crisis later."},
  "MC-SD-02":{type:"diagram",title:"Which Curve Moves for a Cost Rise?",instruction:"Barista wages rise, raising the cost of producing coffee. Draw the diagram, state which curve moves and in which direction, and say what happens to price and quantity. Then state which curve definitely does NOT move.",answer:"SUPPLY shifts LEFT (up), because at every price producers will now offer less. Equilibrium price rises and quantity falls. The DEMAND curve does not move — a change in production cost has no effect on consumers' willingness to buy at a given price; the new equilibrium is reached by a MOVEMENT ALONG demand. Shifting demand for a cost change is the single most common diagram error at this level."},
  "MC-TECH-04":{type:"correct",title:"Label the Axes Properly",instruction:"A student labels the vertical axis of an AD/AS diagram 'price'. Explain why that loses marks, give the correct label for both axes, and say what 'price' would be correct for.",answer:"AD/AS is a MACROeconomic model: the vertical axis is the GENERAL PRICE LEVEL — an index of all prices, like CPI — and the horizontal axis is REAL GDP or real output. 'Price' means the price of one good, which belongs on a microeconomic supply and demand diagram. Examiners flag this consistently because the wrong label signals the student is reasoning about a single market when the question is about the whole economy."},
  "MC-TECH-05":{type:"calculate",title:"Work the Multiplier",instruction:"MPC = 0.8. Calculate the multiplier, then the final change in income from a £2bn injection. Write both formulas. Then say what happens to the multiplier if the MPM rises.",answer:"Multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5, or equivalently 1 ÷ MPW where MPW = MPS + MPT + MPM. Final ΔY = £2bn × 5 = £10bn. The mechanism: the injection becomes income, recipients spend a fraction (MPC), that spending becomes someone else's income, and so on. If the MPM rises, more of each round leaks abroad, so MPW rises, the multiplier FALLS, and the same injection produces less domestic income — which is why open economies have smaller multipliers."},

  // ---- A-Level Sociology, and single-bank tags across Business, Maths, German, Computer Science ----
  "MC-EDU-01":{type:"explain",title:"Role Allocation — and Who Disagrees",instruction:"State what Davis and Moore mean by role allocation and the mechanism they propose. Then give the Marxist objection in one sentence.",answer:"Education sifts and grades people through exams and qualifications, allocating the most talented to the most functionally important and highest-rewarded roles — so inequality of reward is functional, because it motivates the able to undertake long training. Marxist objection: the system does not measure talent neutrally, it reproduces class advantage, so what looks like meritocratic sorting is the legitimation of an inequality that already existed. Bowles and Gintis call the belief in fair sorting 'the myth of meritocracy'."},
  "MC-EDU-03":{type:"correct",title:"Answer the 'Less Intelligent' Claim",instruction:"A student writes that working-class pupils underachieve 'because they are less intelligent'. Give one external and one internal sociological factor that challenge this, each with a named sociologist.",answer:"External — material deprivation: Flaherty shows low income means no books, no tutor, no quiet study space and often part-time work, so the same ability produces lower attainment. Internal — labelling and the self-fulfilling prophecy: Becker's 'ideal pupil' research shows teachers judge working-class pupils against a middle-class standard, and the resulting streaming and low expectations depress attainment. Both explain the OUTCOME without any claim about innate ability, which is exactly why the student's claim is not a sociological explanation at all."},
  "MC-EDU-CLASS":{type:"apply",title:"Cultural Capital in the Classroom",instruction:"Read the scenario, then identify which features reward cultural capital rather than ability. Say what Bourdieu concludes from that.",prompt:"A school rewards confident class discussion, expects familiarity with museums and classical references, and marks essays for 'sophisticated expression'.",answer:"All three reward dispositions acquired at home rather than knowledge taught in school: confidence in talk, familiarity with high culture, and a valued register of language. Bourdieu's conclusion is that the education system is not neutral — it rewards the tastes, language and confidence of the dominant class, so middle-class children arrive already fluent in what schools value and APPEAR more able. Their advantage is converted into qualifications (cultural capital into educational capital) and looks like merit."},
  "MC-EDU-INSCHOOL":{type:"chain",title:"League Tables to Educational Triage",instruction:"Complete the chain, then name the group that loses out and explain why the school's behaviour is rational.",prompt:"League tables measure the % reaching a threshold grade → [step] → [step] → educational triage.",answer:"Schools are judged on the proportion crossing a single boundary → effort is concentrated on borderline pupils, where marginal input changes the published figure → pupils judged certain to pass and those judged hopeless are both deprioritised. The 'hopeless' group loses most. It is rational because the school is optimising the measure it is held to, not the education it provides — Gillborn and Youdell's A-to-C economy is a case of a performance indicator reshaping the behaviour it was meant to monitor."},
  "MC-EDU-GENDER":{type:"sort",title:"External or Internal?",instruction:"Sort each explanation for girls' improved achievement, then state which type most sociologists regard as the primary driver and why.",items:["The impact of feminism on expectations","GCSE coursework suiting girls' work patterns","More female-headed households creating breadwinner role models","Removal of gender stereotyping from textbooks","Changes in the labour market opening careers to women","Teachers' higher expectations of girls' behaviour"],answer:"External (outside school): feminism, female-headed households, labour market change. Internal (inside school): coursework, textbook destereotyping, teacher expectations. Most sociologists treat the EXTERNAL changes as primary — girls' ambitions changed first, as McRobbie's comparison of girls' magazines across decades shows, and the internal reforms then removed obstacles to acting on them. Note the standard evaluation: the gender gap is now smaller than the class gap, so gender alone is a partial explanation."},
  "MC-EDU-PERSPECTIVE":{type:"evaluate",title:"The New Right Argument",instruction:"State the New Right's diagnosis and their proposed remedy with two specific mechanisms. Then give the strongest criticism.",answer:"Diagnosis: a state monopoly has no competitive pressure, so schools have no incentive to improve and become unresponsive to parents. Remedy: apply market logic through parental choice, league tables, open enrolment and formula funding, so good schools expand and poor ones must improve or close. Criticism: the market advantages parents with the cultural capital and mobility to navigate it — Gewirtz's 'privileged-skilled choosers' — so competition redistributes existing advantage rather than raising standards evenly. Note the tension in the position: it demands a free market AND a compulsory national curriculum."},
  "MC-MET-THEORY":{type:"match",title:"Theory to Method",instruction:"Match each theoretical position to its typical methods and priority. Then explain why the pairing follows from what each believes society IS.",headers:["Position","Preferred methods","Priority"],rows:[["Positivism","",""],["Interpretivism","",""]],answer:"Positivism: questionnaires, structured interviews, official statistics; prioritises reliability, representativeness and generalisability. Interpretivism: participant observation, unstructured interviews, personal documents; prioritises validity and meaning. The pairing follows from ontology: positivists model sociology on natural science and believe society has observable external patterns that can be measured, so quantitative methods fit. Interpretivists hold that social reality is constructed through the MEANINGS actors give their actions, which cannot be captured by a tick-box — you have to ask, and listen."},
  "MC-BUS-03":{type:"correct",title:"Skimming Is the Opposite",instruction:"A student writes that price skimming means setting the lowest possible price. Correct it, then complete the table.",headers:["Strategy","Initial price","Target customer","Price over time"],rows:[["Skimming","","",""],["Penetration","","",""]],answer:"Skimming sets a HIGH initial price — the student has described penetration. Skimming: high initial price, early adopters willing to pay a premium (new smartphone launches), price falls as competition arrives and the segment is exhausted. Penetration: low initial price, mass market, price rises once market share and customer habit are established. Both are launch strategies; the choice depends on whether the product's appeal is novelty (skim) or value (penetrate)."},
  "MC-MATH-SPEC":{type:"calculate",title:"Gradient Between Two Points",instruction:"Find the gradient of the line through (2, 5) and (6, 13), writing the formula before substituting. Then do the same for (6, 13) and (2, 5) and explain why the answer is unchanged.",answer:"Gradient = (y₂ − y₁) ÷ (x₂ − x₁) = (13 − 5) ÷ (6 − 2) = 8 ÷ 4 = 2. Reversing the points gives (5 − 13) ÷ (2 − 6) = −8 ÷ −4 = 2 — unchanged, because both differences change sign and the negatives cancel. The error this catches is subtracting in a DIFFERENT ORDER on top and bottom, e.g. (13 − 5) ÷ (2 − 6) = −2, which flips the sign of the gradient."},
  "MC-DE-07":{type:"correct",title:"Grammatical, Not Natural, Gender",instruction:"Find and correct the pronoun error in each sentence, then state the rule in one line.",items:["Ich habe das Buch gelesen, weil ich ihn interessant finde.","Der Tisch ist neu — ich habe sie gestern gekauft.","Die Schule ist groß, aber es ist alt.","Das Mädchen kommt später, weil sie noch arbeitet."],answer:"1: ihn → es (das Buch, neuter). 2: sie → ihn (der Tisch, masculine, accusative). 3: es → sie (die Schule, feminine). 4: CORRECT as written in everyday usage, though strictly das Mädchen is neuter (es) — the classic case where natural and grammatical gender pull apart. Rule: the pronoun matches the GRAMMATICAL gender of the noun it replaces, not the natural gender of what the noun refers to."},
  "MC-CS-ETHICS":{type:"match",title:"Which Data Protection Principle?",instruction:"Match each scenario to the principle it breaches, then state which principle is most often forgotten in exam answers.",items:["A shop keeps customer records for fifteen years with no reason","Data is stored unencrypted on an unlocked laptop","A charity uses donor emails to sell insurance","Records still list a customer's old address after they notified a change"],answer:"1 Storage limitation (kept no longer than necessary). 2 Integrity and confidentiality (security). 3 Purpose limitation (used only for the stated purpose). 4 Accuracy (kept up to date). The one most often forgotten is STORAGE LIMITATION — students recall security and consent but rarely mention that holding data indefinitely is itself a breach, even if it is held securely and was collected lawfully."},

  // ---- GCSE Economics (OCR J205): one starter per MC-GE-* tag.
  // Tags defined by GCSE_ECON_MC_TAGS in data/forge-data.js; labels in
  // data/misconception-labels.js. Every entry targets the single error that
  // tag represents and makes students commit before the reveal.
  "MC-GE-SCARCITY":{type:"classify",title:"What Was Actually Given Up?",instruction:"For each choice, write the opportunity cost as ONE thing. Reject any answer that lists everything forgone — the opportunity cost is the next best alternative only.",items:["A council builds a health centre instead of 120 homes or a car park","You revise instead of working a paid shift or seeing friends","A bakery uses its only oven for cakes instead of bread or pastries","A government funds a hospital instead of a sports centre or road repairs"],answer:"Each answer must name ONE forgone option — the next best. The error to catch is listing every alternative, or naming the thing chosen rather than the thing sacrificed."},
  "MC-GE-FACTORS":{type:"sort",title:"Land, Labour, Capital or Enterprise?",instruction:"Sort each item into one of the four factors. Two are commonly misplaced — be ready to justify.",items:["A delivery van owned by a bakery","£10,000 in the firm's bank account","A baker's time and skill","The founder who hires staff and risks savings","Coal in the ground","A science laboratory in a school"],answer:"Van = capital. £10,000 = NOT capital — money is finance, not a factor of production; capital means man-made things used to produce. Baker's time = labour. Founder = enterprise. Coal = land. Laboratory = capital. The two traps are money-as-capital and treating the entrepreneur as ordinary labour."},
  "MC-GE-PPF":{type:"diagram",title:"Inside It, Or Moving It?",instruction:"Draw one PPF. Mark point X inside the curve and point Y on the curve. Then draw a second curve showing an outward shift. Label which change causes which movement, and commit to an answer before the reveal.",prompt:"Which of these moves you from X to Y, and which shifts the whole curve outward? (a) unemployed workers find jobs (b) investment in new technology (c) better worker training (d) factories reopen after a strike",answer:"X to Y (using existing resources more fully): (a) and (d). Outward shift (more or better resources): (b) and (c). The error is calling any improvement 'a shift' — using idle resources you already have does not move the frontier."},
  "MC-GE-SECTORS":{type:"sort",title:"Which Sector?",instruction:"Sort each activity into primary, secondary or tertiary. One is argued over every year — find it.",items:["Extracting timber from a managed forest","Providing car insurance","Baking bread in a factory","Running a hotel","Catching fish","Providing accountancy advice"],answer:"Primary: timber, fish. Secondary: baking. Tertiary: insurance, hotel, accountancy. The recurring argument is baking — students call it primary because flour is 'natural'; the sector follows what THIS firm does (processing), not where the input came from."},
  "MC-GE-SPECIALISATION":{type:"compare",title:"Both Columns Must Be Filled",instruction:"Complete both columns for a hotel that gives each worker one narrow role. An answer with an empty right-hand column scores half marks in the exam.",headers:["Benefit of division of labour","Drawback of division of labour"],rows:[["Workers get faster through repetition",""],["",""],["",""]],answer:"Benefits: speed through repetition, focused training, specialist equipment worthwhile, less time moving between tasks. Drawbacks: boredom and low motivation, higher staff turnover, workers not interchangeable when someone is absent, over-dependence on one stage of the process."},
  "MC-GE-MARKET-DEF":{type:"classify",title:"Product Market or Factor Market?",instruction:"Label each transaction P (product market) or F (factor market), then write the one-line rule that separates them.",items:["A family buys a meal in a restaurant","A company pays wages to its employees","Consumers buy train tickets","A firm hires software engineers","A business pays rent for a warehouse"],answer:"P: meal, train tickets. F: wages, hiring engineers, warehouse rent. Rule: product markets trade finished goods and services; factor markets trade the RESOURCES used to produce them (land, labour, capital, enterprise). The direction of the flow reverses — in factor markets households sell and firms buy."},
  "MC-GE-PRICE-FUNC":{type:"distinguish",title:"Signal, Incentive or Ration?",instruction:"Label each situation with the function of the price mechanism it shows MOST directly. Several look like more than one — commit to the strongest before the reveal.",items:["Concert ticket prices rise so only some fans can buy","A price rise tells producers demand has increased","Higher strawberry prices lead growers to plant more next season","A 10p bag charge changes shopper behaviour","A congestion charge reduces driving at peak times"],answer:"Ration: concert tickets. Signal: the price rise conveying information. Incentive: strawberry planting. Signal AND incentive: bag charge, congestion charge. The error is treating all three functions as the same idea — signalling INFORMS, incentive REWARDS a response, rationing ALLOCATES what is scarce."},
  "MC-GE-DISEQ":{type:"diagram",title:"Above or Below Equilibrium?",instruction:"Draw one demand and supply diagram. Add a maximum price BELOW equilibrium, then on a second diagram a minimum price ABOVE it. Shade and label the gap in each. Predict shortage or surplus before you draw.",prompt:"Case 1: rent control set below the market rent. Case 2: a farm price floor set above the market price.",answer:"Max price below equilibrium → SHORTAGE (Qd > Qs) — rent control causes a shortage of homes. Min price above equilibrium → SURPLUS (Qs > Qd) — the farm price floor creates unsold output. The error is assuming a maximum price helps everyone; it helps those who get the good and leaves others queuing. A maximum price set ABOVE equilibrium does nothing at all."},
  "MC-GE-SHIFT-VS-MOVE":{type:"classify",title:"Shift It Or Slide Along It?",instruction:"For each change write SHIFT or MOVEMENT, and name the curve. The test is one question: did the good's OWN price change?",items:["The price of coffee rises and less coffee is bought","Household incomes fall and fewer meals are wanted at every price","The price of train travel rises, so more people want buses","A subsidy lowers the cost of making solar panels","The product's own price falls and more is supplied"],answer:"Movement (own price changed): coffee, the last one. Shift (something else changed): incomes → demand shifts left; train price → demand for buses shifts right; subsidy → supply shifts right. Rule: a change in the good's OWN price moves you ALONG the curve; anything else shifts the whole curve."},
  "MC-GE-DS-DETERMINANTS":{type:"sort",title:"Which Curve, Which Direction?",instruction:"For each change state (i) demand or supply and (ii) left or right. Write both parts — half an answer scores nothing.",items:["A rise in the price of train travel, a substitute for buses","A sharp rise in car prices, where petrol is a complement","Baker wages and energy costs rise","A government subsidy on solar panels","Crude oil supply falls, affecting petrol"],answer:"1 Demand for buses, RIGHT. 2 Demand for petrol, LEFT (fewer cars bought and used). 3 Supply of bread, LEFT. 4 Supply of panels, RIGHT. 5 Supply of petrol, LEFT. The classic error is moving demand when a COST changes — costs shift supply."},
  "MC-GE-EQUILIBRIUM":{type:"correct",title:"Fix the Equilibrium Statement",instruction:"Find and correct the error, then state the equilibrium condition precisely.",prompt:"'At equilibrium the market has sold everything it produced, so demand equals supply and the price can never change again.'",answer:"Two errors. (1) The condition is quantity DEMANDED equals quantity SUPPLIED at that price — not 'demand equals supply', which confuses the whole curve with a quantity at one price. (2) Equilibrium is not permanent: any shift in demand or supply produces a new equilibrium."},
  "MC-GE-ELASTICITY":{type:"calculate",title:"Elastic, Inelastic — and Which Elasticity?",instruction:"Calculate the elasticity, classify it, and state whether it is PED or PES. Show the formula before substituting.",items:["Price rises 10%, quantity demanded falls 2%","Price rises 10%, quantity demanded falls 30%","Tonight's concert has 500 seats; price doubles","New housing: planning takes years, price rises 20%"],answer:"1 PED = −2/10 = −0.2, price INELASTIC. 2 PED = −30/10 = −3, price ELASTIC. 3 PES = 0, perfectly inelastic — quantity cannot respond tonight. 4 PES low, inelastic in the short run. The error to catch is labelling 3 and 4 as PED: they concern how SUPPLY responds, not demand."},
  "MC-GE-REV-COST-PROFIT":{type:"calculate",title:"Three Formulas, No Shortcuts",instruction:"Work each out showing the formula first. One asks for average cost and one for profit — read carefully before calculating.",items:["2,000 notebooks sold at £4 each. Total revenue?","Fixed costs £6,000, variable costs £4,000, output 2,000. Average cost?","Revenue £40,000, total costs £31,000. Profit?","Revenue £24,000, total cost £27,000. State the result."],answer:"1 TR = price × quantity = £8,000. 2 AC = total cost ÷ output = £10,000 ÷ 2,000 = £5 per unit. 3 Profit = TR − TC = £9,000. 4 A £3,000 LOSS. The two errors: forgetting to ADD fixed and variable costs before dividing, and reporting a loss as a negative 'profit' without naming it."},
  "MC-GE-PRODUCTIVITY":{type:"calculate",title:"Production or Productivity?",instruction:"For each, state whether it measures PRODUCTION or PRODUCTIVITY, then calculate where asked. Commit before the reveal.",items:["Six workers produce 900 units. Output per worker?","A factory made 1,200 units this week","Output rises 900 → 1,200 with 6 workers. By how much does output per worker RISE?","A firm's total output doubled after hiring twice as many workers"],answer:"1 Productivity: 900 ÷ 6 = 150 units. 2 Production — a total, not a rate. 3 Productivity rises from 150 to 200, so the RISE is 50 units (not 200 — read the question). 4 Production doubled but productivity is UNCHANGED. The core error is treating 'more output' as 'more productive'."},
  "MC-GE-EOS":{type:"sort",title:"Economy or Diseconomy — and Which Type?",instruction:"Sort each into economy or diseconomy of scale, then name the type (purchasing, technical, managerial, financial).",items:["A large firm buys raw materials in bulk more cheaply","Communication slows as the organisation grows","Specialist machinery spreads fixed costs over more output","A large company borrows at a lower interest rate","A big firm employs specialist managers","Managers struggle to coordinate distant sites"],answer:"Economies: bulk buying (purchasing), specialist machinery (technical), cheaper borrowing (financial), specialist managers (managerial). Diseconomies: slow communication, coordination problems. Both change AVERAGE cost, not total cost — that is the distinction students miss."},
  "MC-GE-MARKET-STRUCT":{type:"compare",title:"How Many Firms?",instruction:"Complete the table, then place each example in the right row: a water network; four supermarkets holding 80% of sales; a town with many independent cafes.",headers:["Structure","Number of firms","Barriers to entry","Example"],rows:[["Monopoly","","",""],["Oligopoly","","",""],["Competitive market","","",""]],answer:"Monopoly: one dominant seller, very high barriers — water network. Oligopoly: a few firms with most market share, high barriers, firms watch each other's pricing — the supermarkets. Competitive: many firms, low barriers — the cafes. The error is calling any large firm a monopoly; market SHARE and barriers decide, not size."},
  "MC-GE-BARRIERS":{type:"classify",title:"Is That Actually a Barrier?",instruction:"Mark each B (barrier to entry) or N (not a barrier). Then explain why a barrier matters for consumers.",items:["A patent protecting a new medicine","An established chain's lower average costs from economies of scale","Existing firms advertise heavily","Customers prefer the incumbent's product","The industry is profitable","High set-up costs for a national network"],answer:"B: patent, economies of scale, heavy advertising, network set-up costs. N: customer preference alone, and profitability — high profits ATTRACT entry, they do not block it. Barriers matter because without the threat of entry an incumbent faces less pressure to keep prices low or quality high."},
  "MC-GE-NONPRICE-COMP":{type:"classify",title:"Price or Non-Price Competition?",instruction:"Label each P or NP. Then answer: why would a firm compete on anything other than price?",items:["A supermarket improves its loyalty scheme, shelf prices unchanged","A cinema sells cheap tickets and expensive drinks","A hotel adds a better breakfast","A firm spends heavily on branding, price unchanged","A shop cuts prices by 10%"],answer:"NP: loyalty scheme, better breakfast, branding. P: the 10% cut. The cinema is a LOSS LEADER — a price tactic used to sell profitable extras. Firms use non-price competition because it can make demand less price elastic: loyal customers see the product as less replaceable, so a rival's price cut takes fewer of them."},
  "MC-GE-DERIVED-DEMAND":{type:"chain",title:"Where Does Labour Demand Come From?",instruction:"Complete the chain. Each arrow must be a specific step, not 'the economy grows'.",prompt:"Online shopping becomes more popular → [step] → [step] → firms hire more delivery drivers. Then answer: if demand for the SERVICE collapsed, what happens to demand for these workers, and why?",answer:"Chain: more online orders → more parcels needing delivery → firms need more driver-hours to meet it → labour demand rises. If service demand collapses, labour demand falls WITH it — that is what 'derived' means. Demand for labour is not wanted for its own sake; it is derived from demand for the output labour helps produce."},
  "MC-GE-LABOUR-SUPPLY":{type:"classify",title:"Who Is In the Supply of Labour?",instruction:"Decide whether each person is part of the supply of labour. Commit before the reveal — two are contested.",items:["A worker actively offering their labour","Someone unemployed and actively seeking work","A retired person not seeking paid work","A full-time student not seeking a job","Someone unavailable for work and not looking"],answer:"IN: the worker, and the unemployed person actively seeking — the unemployed ARE part of labour supply, which is the point students miss. OUT: the retired person, the student, the unavailable person. Supply of labour = all those WILLING AND ABLE to offer labour, employed or not."},
  "MC-GE-WAGE-DIFFERENTIALS":{type:"explain",title:"Why Does a Surgeon Earn More?",instruction:"Write a two-part explanation using demand AND supply. An answer using only one side is incomplete.",prompt:"A specialist surgeon earns far more than a worker in a job needing fewer qualifications. Explain using both blades of the scissors. Then explain the night-shift wage premium the same way.",answer:"Surgeon: long training and qualification requirements RESTRICT supply, while demand for the skill is high — high wage. Night shift: unsocial hours REDUCE willingness to supply labour at any given wage, so employers pay a premium to attract workers. The error is explaining wages by effort or importance alone — nurses work hard and matter greatly, but supply is less restricted."},
  "MC-GE-MIN-WAGE":{type:"diagram",title:"Does the Minimum Wage Bite?",instruction:"Draw a labour market diagram twice: once with a minimum wage ABOVE equilibrium, once BELOW. Predict the effect of each before drawing.",prompt:"Case 1: minimum wage set above the market wage. Case 2: set below the market wage.",answer:"Above equilibrium: BINDING — quantity of labour supplied exceeds quantity demanded, creating excess supply (unemployment) in that market, though workers who keep jobs earn more. Below equilibrium: NON-BINDING — the market wage is already higher, so little or no effect. The error is assuming any minimum wage must cause unemployment; it only bites if it is above the market wage."},
  "MC-GE-IMMOBILITY":{type:"distinguish",title:"Geographical or Occupational?",instruction:"Label each G or O, then name one policy that would address each type.",items:["A qualified worker cannot afford to move to a region with vacancies","A retail worker lacks the qualifications to become an engineer","A miner's skills do not transfer to the new software jobs in town","A worker will not relocate because of family and school ties"],answer:"G: unaffordable move, family ties. O: lacks engineering qualifications, non-transferable mining skills. Policies — geographical: relocation support, affordable housing, better transport. Occupational: retraining and vocational education. The error is calling every mismatch 'geographical' when the barrier is actually skills."},
  "MC-GE-PAY":{type:"calculate",title:"Gross, Deductions, Net",instruction:"Calculate net pay, then state which of the deductions is a direct tax and which is a contribution towards state benefits.",items:["Gross £2,400, deductions £500. Net?","Gross £2,800, deductions £650. Net?"],answer:"1 £1,900. 2 £2,150. Net pay = gross pay − deductions. Income tax is a DIRECT tax on income; National Insurance is a contribution by workers and employers towards state benefits and pensions. The error is describing gross pay as 'what you take home'."},
  "MC-GE-MONEY-FUNC":{type:"match",title:"Which Function of Money?",instruction:"Match each situation to a function of money, then answer the final question.",items:["A shopper compares the prices of two products","Pounds are handed over to pay for a meal","Money is kept in a jar for next year","A price is agreed today for delivery in six months"],answer:"Unit of account (comparing), medium of exchange (paying), store of value (kept for later), standard of deferred payment (future settlement). Final question — why is barter inefficient? It requires a DOUBLE COINCIDENCE OF WANTS: each party must want exactly what the other offers. Rice fails as money because it spoils, is hard to standardise and is too plentiful."},
  "MC-GE-INTEREST":{type:"calculate",title:"Interest — Two Sides of One Rate",instruction:"Calculate each, then state whether the person gains or loses when the rate RISES.",items:["£3,000 saved at 4% simple interest for one year. Interest earned?","£5,000 saved at 3% for one year. Final balance?","A household with a variable-rate mortgage","A saver with a large deposit account"],answer:"1 £120. 2 £5,150 (£5,000 + £150). 3 LOSES — repayments rise, disposable income falls. 4 GAINS — higher return on savings. The interest rate is simultaneously the COST of borrowing and the REWARD for saving; a rise helps savers and hurts borrowers, which is why rate changes create winners and losers at once."},
  "MC-GE-FIN-INST":{type:"match",title:"Who Does What?",instruction:"Match each institution or product to what it actually does. Then answer: why does a bank charge a higher rate to a borrower with a poor credit history?",items:["Commercial bank","Insurance company","Building society","Insurance premium","Insurance excess"],answer:"Commercial bank: takes deposits and lends funds. Insurance company: compensates specified losses in return for a premium, pooling risk. Building society: a MUTUAL owned by its members. Premium: the payment FOR cover. Excess: the amount the policyholder pays TOWARDS a claim. Higher rate for poor credit = compensation for a greater risk of default."},
  "MC-GE-OBJECTIVES":{type:"sort",title:"Is That an Objective?",instruction:"Mark each YES (a UK macroeconomic objective) or NO. Then state the four main ones from memory.",items:["Low and stable inflation","Maximising the exchange rate at all times","Keeping every firm profitable","Low unemployment","Fixing every wage at the same level","A sustainable balance of payments"],answer:"YES: low and stable inflation, low unemployment, sustainable balance of payments — plus economic growth, the fourth. NO: maximising the exchange rate, keeping every firm profitable, fixing wages. Objectives concern the WHOLE economy, and they can conflict — growth may pull against price stability, which is why governments face trade-offs."},
  "MC-GE-GDP":{type:"calculate",title:"Level, Rate, or Per Head?",instruction:"Calculate each and state which of the three the question asked for. Show the formula first.",items:["Real GDP £500bn → £515bn. Growth rate?","Real GDP £800bn → £824bn. Growth rate?","GDP £2.1tn, population 70m. GDP per capita?","Real GDP rises 4%, population rises 3%. GDP per head?"],answer:"1 (15 ÷ 500) × 100 = 3%. 2 (24 ÷ 800) × 100 = 3%. 3 GDP ÷ population = £30,000. 4 Roughly +1%. The error this catches is quoting the LEVEL ('GDP is over £2 trillion') as evidence of high GROWTH — growth is a rate of change, and per capita divides by population."},
  "MC-GE-REAL-VS-NOMINAL":{type:"calculate",title:"Strip Out the Prices",instruction:"Work out what happened to REAL output in each case, then state why economists prefer real GDP.",items:["Nominal GDP rises 6%, prices rise 8%","Nominal GDP rises 3%, prices rise 5%","Nominal GDP rises 5%, prices are flat"],answer:"1 Real GDP FELL by about 2%. 2 Real output FELL by about 2%. 3 Real GDP rose about 5%. Approximate real change ≈ nominal change − inflation. Real GDP is preferred because it removes the effect of price changes, so a rise reflects more OUTPUT rather than higher prices. The error is reading any rise in nominal GDP as growth."},
  "MC-GE-CYCLE":{type:"sequence",title:"Where Are We in the Cycle?",instruction:"Place each description at the right stage of the economic cycle, then give the common definition of a recession.",items:["High activity, high employment, capacity strained","Output falling for two consecutive quarters","Factories below normal capacity, unemployment rising","Output recovering, confidence returning"],answer:"Boom, recession, slump/negative output gap, recovery. A recession is commonly defined as a fall in real GDP for two or more CONSECUTIVE QUARTERS. The error is calling any slowdown a recession — growth falling from 3% to 1% is still growth."},
  "MC-GE-GROWTH-CAUSES":{type:"sort",title:"Actual Growth or Potential Growth?",instruction:"Sort each into 'raises actual output now' or 'raises potential capacity'. One does both — find it.",items:["A tax cut increases household spending, capacity unchanged","Investment in productive machinery","Better worker training","Unemployed workers return to work","Fewer available workers from overseas"],answer:"Actual: the tax cut, unemployed returning to work. Potential: new machinery, training. Fewer overseas workers REDUCES potential growth. Infrastructure spending does both — it raises demand now and capacity later. The error is treating any rise in spending as 'economic growth' in the long-run sense."},
  "MC-GE-GDP-WELLBEING":{type:"evaluate",title:"Same GDP, Different Lives",instruction:"Two countries have identical GDP per capita. One has far greater inequality and pollution. Write two sentences on what GDP per capita misses, then name three indicators that fill the gap.",prompt:"Common error: writing 'GDP per capita is wrong' — it is not wrong, it is incomplete.",answer:"GDP per capita is an AVERAGE, so it hides how income is distributed, and it excludes non-market activity, environmental damage, health and leisure. Fuller indicators: life expectancy, adult literacy or school enrolment, access to clean water, HDI. The mark is earned by saying what is missing, not by dismissing the measure."},
  "MC-GE-SUSTAINABILITY":{type:"distinguish",title:"Growth vs Sustainable Growth",instruction:"Mark each policy S (supports sustainability) or N (not), then define sustainable development in one line.",items:["Investing in reliable low-emission public transport","Subsidising energy efficiency and renewable generation","Raising output as fast as possible regardless of emissions","A transport project improving long-term access for isolated communities"],answer:"S: public transport, energy efficiency, the access project (social sustainability). N: growth at any cost. Sustainable development meets present needs WITHOUT compromising the ability of future generations to meet theirs. The error is treating sustainability as purely environmental — it has social and economic dimensions too."},
  "MC-GE-UNEMP-TYPES":{type:"classify",title:"Name the Type",instruction:"Classify each as structural, cyclical, frictional or seasonal. Then state which type retraining helps most, and why.",items:["A car factory closes as demand shifts permanently to imported electric vehicles","A restaurant cuts staff in a recession because customers spend less","A graduate spends three weeks applying before accepting an offer","A ski instructor is out of work each summer","Automation permanently replaces routine jobs"],answer:"Structural: car factory, automation. Cyclical: restaurant. Frictional: graduate. Seasonal: ski instructor. Retraining helps STRUCTURAL unemployment most, because the jobs are not coming back — the mismatch is skills, not the state of the cycle. Cyclical unemployment needs demand to recover, not retraining."},
  "MC-GE-UNEMP-MEASURE":{type:"calculate",title:"Rate First, Then Who Counts",instruction:"Calculate each rate, then decide whether the last three people are unemployed, economically inactive, or employed.",items:["1.4 million unemployed in a labour force of 28 million","900,000 unemployed in a labour force of 30 million","A retired person not seeking work","A student not seeking or available for a job","Someone actively seeking work and available to start"],answer:"Rates: 1.4 ÷ 28 × 100 = 5%; 0.9 ÷ 30 × 100 = 3%. Watch the decimal — 0.5% and 0.3% are the classic slips. Retired person: INACTIVE. Student: INACTIVE. Actively seeking and available: UNEMPLOYED. To be unemployed you must be out of work AND available AND actively seeking; fail any of those and you are inactive, not unemployed. Full employment does NOT mean zero unemployment — some frictional unemployment always remains."},
  "MC-GE-UNEMP-EFFECTS":{type:"chain",title:"One Closure, Three Losers",instruction:"A factory closes. Complete a chain of consequences for each group. Each step must be specific.",prompt:"(a) the worker → … (b) nearby shops → … (c) the government budget → …",answer:"(a) Lost income → lower spending → possible loss of skills the longer unemployment lasts. (b) Lower household incomes → less spending locally → shops lose customers and may cut staff themselves (a local multiplier). (c) Income tax and NI receipts FALL while benefit spending RISES — the budget worsens from both sides at once. The error is treating unemployment as costly only to the person out of work."},
  "MC-GE-INCOME-VS-WEALTH":{type:"sort",title:"Flow or Stock?",instruction:"Sort each into income (a flow over time) or wealth (a stock of assets owned). Then explain why wealth is usually distributed less equally than income.",items:["The salary paid this month","A house owned by a household","Interest received this year","A weekly benefit payment","Shares held in a pension fund"],answer:"Income (flow): salary, interest received, benefit payment. Wealth (stock): the house, the shares. Wealth is typically MORE unequally distributed because assets accumulate and generate further returns — house price rises benefit existing owners, and returns compound over time, so gaps widen across generations."},
  "MC-GE-INEQUALITY":{type:"calculate",title:"Mean, Median, and the Share",instruction:"Answer each, committing before the reveal.",items:["Incomes: £18k, £20k, £22k, £24k, £300k. Find the mean and the median.","Which better describes a TYPICAL household here?","The richest fifth's share of income rises. More equal or less equal?"],answer:"Mean = £76,800; median = £22,000. The MEDIAN better describes a typical household, because a few very high incomes drag the mean upward and no actual household earns near £76,800. A rising top-fifth share means income is LESS equally distributed. The error is quoting an average income as if it described a typical person."},
  "MC-GE-REDISTRIBUTION":{type:"chain",title:"How Does Redistribution Actually Work?",instruction:"Complete the chain, then write one drawback of the policy.",prompt:"Progressive income tax → [step] → [step] → lower-income households better off. Drawback: ?",answer:"Chain: higher earners pay a higher PERCENTAGE of income → revenue funds benefits and public services (education, healthcare) → lower-income households gain both cash and access. Drawback: high marginal rates may weaken incentives to work extra hours, earn or invest; there may also be administrative cost. A full answer names the mechanism AND the trade-off."},
  "MC-GE-TAX-TYPES":{type:"sort",title:"Direct or Indirect? Progressive or Regressive?",instruction:"Give each tax TWO labels: direct/indirect, and progressive/regressive/proportional where it can be judged.",items:["Income tax","VAT","Corporation tax","A household on a low income pays 8% of income in a tax; a high earner pays 2%"],answer:"Income tax: direct, progressive. VAT: indirect, broadly regressive (it takes a larger share of a low income). Corporation tax: direct. The last case is REGRESSIVE — the rate FALLS as income rises. That one is the trap: students see 'a percentage of income' and answer progressive without checking which direction it moves. Direct = levied on income or wealth; indirect = levied on spending."},
  "MC-GE-INFLATION-DEF":{type:"correct",title:"Falling Inflation Is Not Falling Prices",instruction:"Correct each student statement in one sentence.",items:["'Inflation fell from 6% to 3%, so prices are now falling.'","'Inflation is 0%, so prices have gone back down.'","'The inflation rate is −0.5%, so inflation has stopped.'"],answer:"1 Prices are still RISING, just more slowly (disinflation). 2 Prices are stable at their current level — nothing has been reversed. 3 The price level is FALLING on average — that is DEFLATION, not the absence of inflation. Inflation is a sustained rise in the GENERAL PRICE LEVEL; the rate measures how fast that level is changing, not whether prices are high."},
  "MC-GE-CPI":{type:"calculate",title:"Build the Index",instruction:"Calculate each CPI, then answer the weighting question.",items:["Basket costs £50 in the base year, £60 now. CPI now?","Basket costs £80 in the base year, £88 later. CPI later?","Why does food get a larger weight than a rare leisure purchase?"],answer:"1 (60 ÷ 50) × 100 = 120 — prices are 20% higher than the base year. 2 (88 ÷ 80) × 100 = 110. The common slips are inverting the fraction (giving 83) or forgetting the ×100. Weighting: goods are weighted by the SHARE OF SPENDING they take in a typical household budget, so food moves the index more than an occasional purchase does."},
  "MC-GE-INFLATION-CAUSES":{type:"sort",title:"Demand-Pull or Cost-Push?",instruction:"Label each DP or CP, then state which policy tool best addresses each.",items:["Households spend rapidly while factories are near full capacity","Energy and raw-material costs rise sharply","A 10% wage rise follows a 6% productivity rise","Rapid growth in spending beyond productive capacity"],answer:"DP: rapid spending near capacity, spending beyond capacity. CP: energy costs, and the wage rise outstripping productivity (unit labour costs rise). Demand-pull responds to demand restraint — higher interest rates or tighter fiscal policy. Cost-push is harder: demand restraint worsens output, so supply-side measures that raise productivity work better over time."},
  "MC-GE-INFLATION-EFFECTS":{type:"classify",title:"Who Gains From Unexpected Inflation?",instruction:"Mark each GAINS or LOSES from unanticipated inflation, then calculate the real return.",items:["A borrower with a fixed-rate loan","A saver whose interest is below inflation","A household with a fixed-rate mortgage","Savings earn 2% while inflation is 5%. Real return?"],answer:"Borrower with fixed-rate loan: GAINS — the real value of the debt falls as prices and incomes rise. Saver below inflation: LOSES purchasing power. Fixed-rate mortgage holder: GAINS, same reason. Real return ≈ 2% − 5% = −3%. The error is assuming inflation harms everyone equally; it redistributes from lenders and savers to borrowers when it is unanticipated."},
  "MC-GE-GOVT-SPENDING":{type:"sort",title:"Is That Government Spending?",instruction:"Mark each IN or OUT of government expenditure, then answer the ageing-population question.",items:["Public healthcare","A consumer's private saving","A firm's retained profit","Household pocket money","State pensions"],answer:"IN: public healthcare, state pensions. OUT: private saving, retained profit, pocket money — these are private, not government, spending. Ageing population: spending pressure RISES (pensions, healthcare, social care) while a smaller share of working-age people pays income tax, so the budget is squeezed from both directions. Responses include encouraging later retirement or higher participation."},
  "MC-GE-BUDGET":{type:"calculate",title:"Deficit, Surplus, or Debt?",instruction:"State the answer for each, then write the one-line difference between a deficit and the national debt.",items:["Government collects £720bn, spends £760bn","Government collects £600bn, spends £570bn","Tax revenue equals government spending","'The budget deficit means the UK imports more than it exports.'"],answer:"1 A £40bn DEFICIT (spending exceeds revenue). 2 A £30bn SURPLUS. 3 A BALANCED budget. 4 FALSE — that describes a current account deficit; the two are different measures. Deficit vs debt: a deficit is a YEARLY shortfall; debt is the ACCUMULATED stock of past borrowing. Heavy borrowing can also push up interest rates and crowd out private investment."},
  "MC-GE-FISCAL":{type:"sort",title:"Which Direction Is This Policy Pushing?",instruction:"Label each EXPANSIONARY or CONTRACTIONARY, then state the aim of each.",items:["Cutting income tax and increasing government spending","Raising income tax and cutting public spending","Increasing infrastructure spending during a recession","Cutting spending when inflation is persistently high"],answer:"Expansionary: 1 and 3 — raise aggregate demand to support growth and employment. Contractionary: 2 and 4 — reduce demand to ease inflationary pressure. The error is matching 'higher taxes and lower spending' to expansionary because both words sound active. Ask instead: does this ADD to demand or TAKE FROM it? Expansionary policy near full capacity risks inflation rather than extra output."},
  "MC-GE-AUTO-STABILISERS":{type:"distinguish",title:"Automatic, or a New Decision?",instruction:"Mark each A (automatic stabiliser) or D (a discretionary decision). Then say what makes a stabiliser 'automatic'.",items:["Income tax receipts fall when incomes fall in a recession","Benefits rise as more people lose work","The Chancellor announces a new school-building programme","A temporary VAT cut is legislated in a Budget"],answer:"A: falling tax receipts, rising benefit spending. D: the building programme, the legislated VAT cut. A stabiliser is automatic because it responds to the cycle WITHOUT any new decision — it cushions demand immediately, with no announcement, vote or time lag."},
  "MC-GE-POLICY-LAGS":{type:"sequence",title:"Why Nothing Happens Immediately",instruction:"Put the stages in order for a school-building programme announced today, then estimate where the delay is longest.",items:["Construction begins and workers are hired","The problem is recognised in the data","Budgets are designed and approved","Output and employment respond","The policy is announced"],answer:"Recognition → announcement → design and approval → construction begins → output responds. The longest delays are usually approval and implementation. This is why fiscal policy can arrive after the problem has changed, and why supply-side policies (education, infrastructure) take years before productivity rises — a point worth stating explicitly in evaluation answers."},
  "MC-GE-BOE":{type:"correct",title:"Who Does What at the Bank?",instruction:"Correct each statement in one line.",items:["'The Chancellor sets the UK base interest rate.'","'The Bank of England's target is 0% inflation.'","'Quantitative easing means printing money that goes straight to consumers.'"],answer:"1 The Bank of England's MONETARY POLICY COMMITTEE sets Bank Rate, independently of the Chancellor. 2 The target is 2% CPI — low and stable, not zero; deflation causes its own problems. 3 QE is an EXPANSION OF THE MONEY SUPPLY through the central bank buying assets such as government bonds, which lowers yields and encourages lending and spending — it is not cash handed to households. A credible target helps because it anchors expectations for planning prices and wages."},
  "MC-GE-MONETARY":{type:"chain",title:"From Bank Rate to Spending",instruction:"Complete both chains. Each arrow must be a mechanism, not 'the economy changes'.",prompt:"Rate RISE → [step] → [step] → aggregate demand falls. Rate CUT → [step] → [step] → aggregate demand rises. Then: who loses from a rise, and what is the trade-off?",answer:"Rise: borrowing becomes dearer and saving more attractive → credit-financed purchases and investment fall → demand falls, easing price pressure. Cut: borrowing cheaper, saving less rewarding → spending and investment rise → demand rises. Losers from a rise: households with variable-rate mortgages, borrowers generally. Trade-off: it lowers inflation but weakens growth and employment — sharpest when inflation is high AND growth is already weak. The error is claiming higher rates 'encourage people to spend more'."},
  "MC-GE-RATES-AND-CURRENCY":{type:"chain",title:"Rates, Then the Pound",instruction:"Complete the chain and then predict the opposite case before the reveal.",prompt:"UK interest rates RISE → [step] → [step] → the pound appreciates. Now: UK rates are CUT — what happens to sterling, and why?",answer:"Rise: UK financial assets offer higher returns → overseas investors buy sterling to hold them → demand for pounds increases → the pound appreciates. Cut: some investors seek better returns elsewhere → demand for sterling falls (and supply rises as funds leave) → downward pressure on the pound. The step students skip is that a currency's value comes from DEMAND FOR AND SUPPLY OF that currency."},
  "MC-GE-SUPPLYSIDE":{type:"sort",title:"Capacity or Demand?",instruction:"Mark each SS (supply-side: raises productive capacity) or AD (works mainly through demand). Then say why supply-side policy is slow.",items:["Funding vocational training and skills development","A temporary VAT cut","Building a new rail network","Reducing unnecessary barriers to entry","Privatising a state industry","A one-off payment to households"],answer:"SS: training, rail network, removing barriers, privatisation. AD: VAT cut, one-off payment. Supply-side policy aims to let the economy produce MORE AT A GIVEN PRICE LEVEL — growth without inflation. It is slow because education, infrastructure and investment take years to raise productivity, and some reforms carry high upfront costs with uncertain results. Privatisation can sharpen cost incentives but risks abuse of market power in a natural monopoly without regulation."},
  "MC-GE-EXTERNALITIES":{type:"classify",title:"Who Is the Third Party?",instruction:"For each, name the THIRD PARTY and say whether the externality is positive or negative. If you cannot name a third party, it is not an externality.",items:["A factory's noise affects nearby households that do not buy its product","Training makes workers more productive for future employers too","Second-hand smoke affecting people near a smoker","A firm pays higher wages to its own staff","Pollution from a factory harms residents not involved in the sale"],answer:"1 Neighbours, negative. 2 Future employers and the wider economy, positive. 3 Bystanders, negative. 4 NOT an externality — staff are party to the transaction; this is a private cost. 5 Residents, negative. An externality is a cost or benefit falling on someone OUTSIDE the transaction, which is why the market price fails to reflect it."},
  "MC-GE-MERIT-GOODS":{type:"sort",title:"Merit, Demerit, or Public Good?",instruction:"Sort each and give the defining feature of the group you place it in.",items:["Education","A product with health costs from overconsumption","Street lighting","Vaccination","National defence"],answer:"Merit: education, vaccination — under-consumed because individuals underestimate the private and social benefits. Demerit: the harmful product — over-consumed because costs are underestimated. Public: street lighting, defence — NON-RIVAL and NON-EXCLUDABLE, so private firms under-provide them because of free-riding. The error is calling anything the government provides a public good; the test is the two characteristics, not who supplies it."},
  "MC-GE-MARKET-FAILURE":{type:"classify",title:"Which Kind of Failure?",instruction:"Name the type of market failure in each case, then define market failure in one line.",items:["A buyer knows less about a used car's condition than the seller","Nobody will pay for street lighting they can use for free","A market produces too much pollution at the unregulated equilibrium"],answer:"1 ASYMMETRIC INFORMATION. 2 The FREE-RIDER problem with a public good. 3 A negative externality — social costs are not reflected in the price. Market failure means the market allocation of resources is inefficient and does not maximise social welfare. The error is treating 'market failure' as 'the market collapsed' — it means the outcome is inefficient, not that trade stopped."},
  "MC-GE-INTERVENTION":{type:"match",title:"Match the Tool to the Failure",instruction:"Choose the intervention that fits each problem and state which way it shifts the curve.",items:["A good with negative externalities is over-consumed","A merit good is under-consumed","Pollution of a shared river","Consumers underestimate the benefits of healthy eating"],answer:"1 Indirect tax — raises firms' costs, shifts supply LEFT, raises price, reduces quantity. 2 Subsidy or public provision — lowers the effective price, increases uptake towards the socially efficient level. 3 Property rights or regulation — an owner has an incentive to protect the resource, though monitoring a large shared area is difficult. 4 Information provision. A tax makes producers and consumers face more of the SOCIAL cost — that phrase earns the mark."},
  "MC-GE-GOVT-FAILURE":{type:"evaluate",title:"When the Cure Causes Harm",instruction:"For each intervention, write one way it could make the outcome worse. Then define government failure.",items:["A pollution tax set too high","An information campaign about healthy eating","A subsidy for a good the government has misjudged"],answer:"1 Large fall in employment with little environmental gain — the cost exceeds the benefit. 2 Consumers may ignore or misunderstand the information, so behaviour does not change. 3 Public money spent with no welfare gain, plus the opportunity cost of the next best use of those funds. Government failure = intervention that produces a worse allocation of resources than before, through poor information, high cost or unintended effects. Every intervention answer should acknowledge this possibility."},
  "MC-GE-EXPORTS-IMPORTS":{type:"classify",title:"Which Way Is It Flowing?",instruction:"For the UK, label each an EXPORT or an IMPORT. Then write the two definitions.",items:["A UK firm buys computer equipment made in South Korea","A UK firm sells software to a customer abroad","A foreign visitor pays for a night in a UK hotel","A UK household pays for a hotel abroad","A UK accountancy firm advises an overseas client"],answer:"Imports: the Korean equipment, the UK household's hotel abroad. Exports: software sold abroad, the foreign visitor's UK hotel stay, advice to an overseas client. Exports are goods and services SOLD abroad; imports are BOUGHT from abroad. Services count — the two hotel cases are the ones students reverse, because the money and the customer move in opposite directions."},
  "MC-GE-TRADE-BENEFITS":{type:"explain",title:"Why Import What You Could Make?",instruction:"Answer in two sentences using opportunity cost, then define comparative advantage precisely.",prompt:"A country CAN produce food itself, but imports it and specialises in renewable-energy equipment instead. Why is that rational?",answer:"Because another country produces food at a LOWER OPPORTUNITY COST, so both gain by specialising where they are relatively efficient and exchanging. Comparative advantage means producing a good at a lower opportunity cost than another country — NOT producing it with fewer resources, which is absolute advantage. The gains are wider markets, economies of scale, lower prices and more choice. The error is assuming a country should make anything it is capable of making."},
  "MC-GE-PROTECTIONISM":{type:"evaluate",title:"Tariff on Steel — Who Wins, Who Loses?",instruction:"Complete the table for a tariff on imported steel, then decide whether 'this benefits everyone in the UK' is true.",headers:["Group","Effect","Winner or loser?"],rows:[["UK steel producers","",""],["UK firms that BUY steel","",""],["UK consumers","",""],["Government","",""]],answer:"Producers: protected from cheaper imports, output and jobs supported — winners. Firms buying steel: input costs rise — losers. Consumers: higher prices for steel-containing goods, less choice — losers. Government: gains tariff revenue. So 'benefits everyone' is FALSE: protection redistributes towards the protected industry at others' expense. A quota limits QUANTITY rather than raising price directly, but also raises prices and cuts choice. The infant-industry argument is the strongest case for temporary protection."},
  "MC-GE-TRADING-BLOCS":{type:"explain",title:"Why Join a Bloc?",instruction:"Give one benefit and one cost of joining a trading bloc with a common currency, then define a free trade agreement.",prompt:"Common error: describing a trading bloc as simply 'countries that are friendly'.",answer:"Benefit: trade barriers between members fall and, with a common currency, firms avoid currency-conversion costs and can compare prices easily — trade and competition increase. Cost: loss of independent monetary policy and of freedom to set external trade policy; trade may be diverted from cheaper non-members. A free trade agreement allows goods and services to move between member countries without restrictions such as tariffs and quotas."},
  "MC-GE-TRADE-RISKS":{type:"chain",title:"One Port, Many Factories",instruction:"Complete the chain, then name one way a firm can reduce this risk.",prompt:"A port closure delays components → [step] → [step] → prices rise in several countries. Risk reduction: ?",answer:"Chain: factories cannot obtain the components → production halts or slows in multiple countries → shortages push prices up well beyond the country where the disruption began. Mitigation: diversify suppliers across countries, hold larger buffer stocks, or shorten the supply chain. This is the flip side of interdependence — the same links that lower costs also transmit shocks."},
  "MC-GE-BOP":{type:"sort",title:"Is It In the Current Account?",instruction:"Mark each IN or OUT of the current account. For those in, name the component.",items:["A UK firm exports software to a French customer","An overseas company buys UK industrial land","A UK bank receives interest from a foreign borrower","Foreign aid sent from the UK","An overseas company buys a UK factory"],answer:"IN: software export (trade in services), interest received (primary income), foreign aid sent (secondary income). OUT: buying land, buying a factory — these are investment flows recorded in the financial account, not current trade. The current account records trade in goods and services, primary income and secondary income. The error is putting any transaction with a foreign party into the current account."},
  "MC-GE-BOP-CALC":{type:"calculate",title:"Add the Components",instruction:"Calculate each balance, showing the components before the total. State deficit or surplus explicitly.",items:["Goods exports £200bn, goods imports £250bn, services surplus £30bn","Exports £80bn, imports £95bn, other current items balanced","Goods trade −£70bn, services trade +£50bn","Exports £120bn, imports £100bn"],answer:"1 −50 + 30 = £20bn DEFICIT. 2 £15bn deficit. 3 −70 + 50 = £20bn deficit. 4 £20bn SURPLUS. The two slips are ignoring the services figure entirely and losing the sign — always write the goods balance first as a negative or positive number, then add services."},
  "MC-GE-BOP-EVAL":{type:"evaluate",title:"Is This Deficit a Problem?",instruction:"For each, decide whether the current account deficit is more or less concerning, and give the reason.",items:["Imports are mostly advanced machinery to expand factories","The deficit is persistent and financed by short-term borrowing","The deficit reflects a temporary consumer boom","The deficit is financed by sustainable long-term inward investment"],answer:"Less concerning: machinery imports (they raise future productive capacity and export potential), sustainable inward investment, a temporary boom. More concerning: persistent and hard to finance. The question to ask is: is it TEMPORARY and financing productive investment, or PERSISTENT and difficult to finance? The error is treating any deficit as automatically a crisis."},
  "MC-GE-BOP-POLICY":{type:"sort",title:"What Actually Improves the Balance?",instruction:"Mark each policy LONG-RUN, SHORT-RUN, or UNRELIABLE for improving the current account, and give the mechanism.",items:["Improving productivity so domestic firms become more competitive","Investing in research and development","Allowing the currency to depreciate","Improving export quality"],answer:"Long-run: productivity, R&D, export quality — they make exports more attractive on non-price terms as well as price, which is durable. Depreciation is short-run and UNRELIABLE on its own: it only helps if demand for exports and imports responds sufficiently to the price change. The error is treating a weaker currency as a guaranteed fix."},
  "MC-GE-APPREC-DEPREC":{type:"correct",title:"Which Way Did It Move?",instruction:"State appreciation or depreciation for each, then define an exchange rate in one line.",items:["£1 buys €1.20 instead of €1.10","£1 falls from $1.40 to $1.25","The pound reaches its highest value against the dollar in a decade"],answer:"1 APPRECIATION — each pound buys more euros. 2 DEPRECIATION. 3 Appreciation. An exchange rate is the price of one currency expressed in terms of another. The check that prevents errors: if the number of foreign currency units per pound RISES, sterling has appreciated. Note that a strong pound is not automatically good news — it makes UK exports dearer abroad."},
  "MC-GE-CURRENCY-DEMAND":{type:"classify",title:"Demand for Pounds, or Supply of Pounds?",instruction:"Mark each as increasing DEMAND for sterling or increasing SUPPLY of sterling, then state the effect on its value.",items:["Overseas buyers purchase more UK exports","UK tourists buy goods abroad","A rise in foreign demand for UK financial assets","A country persistently imports much more than it exports"],answer:"Demand for sterling (value up): buying UK exports, buying UK financial assets — foreigners must obtain pounds first. Supply of sterling (value down): UK tourists spending abroad, persistent excess imports — UK residents sell pounds to buy foreign currency. A floating rate is set by demand for and supply of the currency; the error is thinking only governments move it."},
  "MC-GE-EXCHANGE-RATE":{type:"compare",title:"Weak Pound: Good or Bad?",instruction:"Complete the table for a DEPRECIATION of sterling, then write a one-sentence judgement.",headers:["Group","Effect of a weaker pound","Better or worse off?"],rows:[["UK exporters","",""],["UK consumers buying imported food and fuel","",""],["UK manufacturers using imported components","",""],["Inflation","",""]],answer:"Exporters: goods cheaper in foreign currency, more price competitive — better off. Consumers of imports: imported goods dearer — worse off. Manufacturers using imported inputs: input costs rise — worse off. Inflation: imported goods and inputs cost more, adding to cost-push pressure. Judgement: a depreciation REDISTRIBUTES between exporters and importers rather than helping or harming 'everyone'. Reverse every row for an appreciation."},
  "MC-GE-EXR-CALC":{type:"calculate",title:"Multiply or Divide?",instruction:"Work each out and write the rule you used BEFORE calculating. Getting the direction right matters more than the arithmetic.",items:["£1 = $1.25. How many dollars would £400 buy?","A UK company must pay €1,000 when £1 = €1.25. How many pounds?","A UK buyer must pay €18,000 when £1 = €1.20. How many pounds?","£1 falls to $1.25. What does a $28,000 payment cost in pounds?"],answer:"1 £400 × 1.25 = $500. 2 €1,000 ÷ 1.25 = £800. 3 €18,000 ÷ 1.20 = £15,000. 4 $28,000 ÷ 1.25 = £22,400. Rule: pounds → foreign currency, MULTIPLY by the rate; foreign currency → pounds, DIVIDE. The sense-check is whether the answer moved in a plausible direction."},
  "MC-GE-J-CURVE":{type:"diagram",title:"Why Doesn't It Improve Straight Away?",instruction:"Sketch the current account balance against time after a depreciation. Label the initial worsening, the turning point and the improvement. Then state the condition for improvement.",prompt:"Common error: drawing immediate improvement after a depreciation.",answer:"The balance WORSENS first: import prices rise immediately while contracts are already fixed and quantities take time to adjust, so the import bill rises before export volumes grow. It improves later as buyers respond. The condition is that demand for exports and imports must be sufficiently PRICE ELASTIC — if quantities barely respond, a depreciation can leave the balance worse. Price elasticity of demand for exports is the factor to name."},
  "MC-GE-GLOBALISATION":{type:"classify",title:"Is That Evidence of Globalisation?",instruction:"Mark each YES or NO as evidence of greater globalisation. Two are the reverse — find them.",items:["A firm designs in one country, sources components globally and sells worldwide","Every good being produced locally","A factory relying on components from several countries","A country ending all international trade","Online platforms connecting businesses across borders"],answer:"YES: the global firm, the multi-country supply chain, the online platforms. NO: local-only production and ending trade are DE-globalisation. Globalisation is growing economic integration and interdependence between countries; economic interdependence means countries rely on one another through trade and finance."},
  "MC-GE-MNC":{type:"evaluate",title:"Multinational Arrives — Two Columns",instruction:"A multinational builds a factory in a developing country. Complete both columns, then name what this investment is called.",headers:["Benefit to the host country","Concern for the host country"],rows:[["",""],["",""],["",""]],answer:"This is FOREIGN DIRECT INVESTMENT. Benefits: capital and jobs, skills and training, access to technology, tax revenue, export earnings. Concerns: profits shifted abroad rather than reinvested, weak regulation exploited, environmental damage, production moved elsewhere later to cut costs. This is why host governments regulate while trying to retain the investment — an answer with only one column is incomplete."},
  "MC-GE-GLOB-COSTS":{type:"chain",title:"Who Pays for Cheaper Goods?",instruction:"Complete the chain, then name the type of unemployment created and the policy that addresses it.",prompt:"A factory moves production overseas to lower costs → [step] → [step] → workers in the original country are affected.",answer:"Chain: domestic plant closes → workers' skills no longer match locally available vacancies → they face STRUCTURAL unemployment and need retraining. The policy is retraining and skills support, not demand stimulus, because those specific jobs are not returning. Freer movement of labour can ease skills shortages in some sectors, but the costs and benefits of globalisation fall on DIFFERENT groups — consumers gain from lower prices while displaced workers bear the loss."},

  // ---- GCSE Separate Sciences (Edexcel): one starter per topic tag across
  // gcse-sep-bio, gcse-sep-chem and gcse-sep-phys. Each targets the single
  // error that tag represents and makes students commit before the reveal.
  // ---- GCSE Separate Biology
  "MC-SEP-BIO-CELL":{type:"sort",title:"Which Structure Does What?",instruction:"Match each job to ONE structure. Two structures are confused every year — be ready to say which.",items:["Controls what enters and leaves the cell","Gives a plant cell its rigid shape","Site of aerobic respiration","Contains the genetic material","Site of protein synthesis"],answer:"Membrane (control), cell wall (rigid shape), mitochondria, nucleus, ribosomes. The confusion is MEMBRANE vs WALL: the wall is rigid support and is freely permeable — it controls nothing. Only the membrane is selectively permeable. Saying 'the cell wall controls what enters' loses the mark."},
  "MC-SEP-BIO-RIBO":{type:"match",title:"Organelle to Job",instruction:"Write the organelle responsible for each, then name the two cell types that both contain ribosomes.",items:["Joins amino acids into a protein","Releases energy by aerobic respiration","Absorbs light for photosynthesis","Stores cell sap in a plant cell"],answer:"Ribosome, mitochondrion, chloroplast, vacuole. Ribosomes are in BOTH prokaryotic and eukaryotic cells — that is the exam point students miss, because they assume prokaryotes have 'no organelles' and therefore no ribosomes."},
  "MC-SEP-BIO-DIFFUSION":{type:"correct",title:"Fix the Diffusion Sentence",instruction:"Find and correct the error in each statement.",items:["'Diffusion moves particles from low to high concentration.'","'Diffusion needs energy from respiration.'","'Diffusion stops completely once concentrations are equal.'"],answer:"1 High to LOW — down the gradient. 2 Diffusion is PASSIVE; active transport is the one needing energy. 3 Particles keep moving randomly, but there is no NET movement — 'net' is the word that earns the mark."},
  "MC-SEP-BIO-OSMOSIS":{type:"scenario",title:"Which Way Does the Water Go?",instruction:"For each, state which way water moves and what happens to the cell. Commit before the reveal.",items:["A plant cell in pure water","A plant cell in concentrated sugar solution","A red blood cell in pure water","A red blood cell in concentrated salt solution"],answer:"Into the cell (turgid); out (plasmolysed); into the cell (bursts — lysis); out (crenated/shrivels). Osmosis moves WATER only, from dilute to concentrated, through a partially permeable membrane. The common error is describing sugar moving instead of water."},
  "MC-SEP-BIO-ENZYME":{type:"graph",title:"Sketch the Temperature Curve",instruction:"Sketch enzyme activity against temperature. Mark the optimum. Then explain what happens either side of it — the two sides need DIFFERENT explanations.",prompt:"Common error: writing that the enzyme 'dies' above the optimum.",answer:"Below optimum: less kinetic energy, fewer successful collisions with the substrate — the enzyme is unchanged and the effect is reversible. Above optimum: bonds holding the tertiary structure break, the ACTIVE SITE changes shape, the substrate no longer fits — DENATURED, and irreversible. Enzymes are not alive, so they cannot die."},
  "MC-SEP-BIO-PHOTO":{type:"correct",title:"Balance the Word Equation",instruction:"Write the word equation for photosynthesis from memory, then check it against these three student attempts and correct each.",items:["'oxygen + water → glucose + carbon dioxide'","'carbon dioxide + water → glucose (light energy is a reactant)'","'carbon dioxide + oxygen → glucose + water'"],answer:"Correct: carbon dioxide + water → glucose + oxygen (light energy, chlorophyll above the arrow). 1 reverses reactants and products. 2 light is a CONDITION, not a reactant — it goes above the arrow. 3 uses oxygen as a reactant; oxygen is a product."},
  "MC-SEP-BIO-MITOSIS":{type:"compare",title:"Mitosis or Meiosis?",instruction:"Complete the table, then decide which process made each: a skin cell replacing a scab, and a sperm cell.",headers:["Feature","Mitosis","Meiosis"],rows:[["Number of daughter cells","",""],["Genetically identical?","",""],["Chromosome number","",""],["Where it happens","",""]],answer:"Mitosis: 2 cells, identical, diploid maintained, growth/repair/asexual reproduction — the scab. Meiosis: 4 cells, genetically different, haploid (halved), gamete production — the sperm. The error is saying mitosis 'halves' the chromosome number; that is meiosis."},
  "MC-SEP-BIO-GENETICS":{type:"distinguish",title:"Gene or Allele?",instruction:"Label each statement GENE or ALLELE, then write one sentence stating the relationship between them.",items:["A section of DNA coding for a protein","The version for brown eyes rather than blue","There is one for eye colour","A dominant or recessive form"],answer:"Gene: the section of DNA, and 'one for eye colour'. Allele: the brown-eye version, and the dominant/recessive form. Relationship: a gene is the instruction for a characteristic; an allele is one of its alternative VERSIONS. You inherit two alleles of each gene, one from each parent."},
  "MC-SEP-BIO-BLOOD":{type:"match",title:"Four Components, Four Jobs",instruction:"Match each blood component to its job and name one adaptation that fits it for that job.",items:["Red blood cell","White blood cell","Platelet","Plasma"],answer:"Red cell: transports oxygen — biconcave for surface area, no nucleus for more haemoglobin. White cell: defence — can change shape to engulf pathogens, has a nucleus. Platelet: clotting. Plasma: transports dissolved substances, including carbon dioxide, urea and nutrients. The error is saying red cells 'carry carbon dioxide' — most is carried by plasma."},
  "MC-SEP-BIO-DIGEST":{type:"sequence",title:"Digest, Then Absorb",instruction:"Put the organs in order along the gut, then state for each whether it mainly DIGESTS, ABSORBS, or both.",items:["Small intestine","Mouth","Large intestine","Stomach","Oesophagus"],answer:"Mouth, oesophagus, stomach, small intestine, large intestine. Digests: mouth (amylase), stomach (protease, acid), small intestine (enzymes from pancreas). Absorbs: small intestine (nutrients, via villi), large intestine (water). The error is thinking the stomach absorbs food — absorption is overwhelmingly the small intestine, which is why villi matter."},
  "MC-SEP-BIO-TRANSPIRATION":{type:"evaluate",title:"Four Conditions, One Rate",instruction:"For each change, state whether transpiration rate RISES or FALLS, and give the reason in terms of evaporation or diffusion.",items:["Temperature rises","Humidity rises","Wind speed rises","Light intensity falls"],answer:"Rises (more kinetic energy, faster evaporation); FALLS (smaller water-vapour gradient outside the leaf); rises (wind removes humid air, keeping the gradient steep); falls (stomata close in darkness). The trap is humidity — students assume 'more water about' means more transpiration, but it flattens the diffusion gradient."},
  "MC-SEP-BIO-PLANTS":{type:"compare",title:"Xylem or Phloem?",instruction:"Complete the table. Then say which vessel a sugar-tracing radioactive tracer would appear in.",headers:["Feature","Xylem","Phloem"],rows:[["Transports","",""],["Direction","",""],["Living or dead cells?","",""]],answer:"Xylem: water and mineral ions, upwards only, dead hollow cells strengthened with lignin. Phloem: dissolved sugars, both directions (translocation), living cells with sieve plates. A sugar tracer appears in PHLOEM. Mnemonic that survives the exam: phloem = food."},
  "MC-SEP-BIO-DNA":{type:"sequence",title:"Nest the Terms",instruction:"Put these in order from LARGEST to SMALLEST, then write one sentence defining a gene.",items:["Gene","Nucleus","Chromosome","Base","DNA molecule"],answer:"Nucleus > chromosome > DNA molecule > gene > base. A gene is a SECTION of DNA that codes for a protein. The common error is treating gene and chromosome as the same size — a single chromosome carries hundreds of genes."},
  "MC-SEP-BIO-REPRO":{type:"chain",title:"Across the Placenta",instruction:"Draw two arrows across a placenta: one for substances going TO the fetus, one for substances leaving. Label each. Then answer the question below.",prompt:"Does maternal blood mix with fetal blood? Justify your answer.",answer:"To the fetus: oxygen, glucose, nutrients, antibodies. From the fetus: carbon dioxide, urea. The blood does NOT mix — exchange happens by diffusion across a barrier with a large surface area. Mixing would risk immune rejection and blood-group incompatibility. 'The blood mixes' is the single most common error here."},
  "MC-SEP-BIO-DEFENCE":{type:"classify",title:"Three Defences, One Job",instruction:"Name which white-blood-cell defence each describes, then say which one gives long-term protection.",items:["Engulfing and digesting a pathogen","Producing proteins that lock onto a specific antigen","Neutralising the poisons a pathogen releases"],answer:"Phagocytosis; antibody production (lymphocytes); antitoxin production. Long-term protection comes from ANTIBODIES, because memory cells persist. Phagocytosis is non-specific and leaves no memory. Also worth stating: skin, mucus and stomach acid are barriers, not white-cell defences."},
  "MC-SEP-BIO-NUTRITION":{type:"match",title:"Nutrient to Function",instruction:"Match each nutrient group to its main function, then name a deficiency disease for two of them.",items:["Carbohydrate","Protein","Lipid","Vitamin C","Iron","Fibre"],answer:"Energy; growth and repair; energy store and insulation; connective tissue (deficiency: scurvy); haemoglobin (deficiency: anaemia); keeps food moving through the gut. A balanced diet supplies all of these in appropriate AMOUNTS — 'balanced' means proportion, not simply variety."},
  "MC-SEP-BIO-DISEASE":{type:"correct",title:"Why Antibiotics Fail on a Cold",instruction:"A patient asks for antibiotics for a cold. Write the explanation you would give in two sentences, using the words 'bacterial' and 'host cell'.",prompt:"Common error: 'antibiotics only kill strong bacteria' or 'viruses are too small'.",answer:"Antibiotics work by attacking structures and processes specific to BACTERIA — cell walls, bacterial ribosomes, bacterial enzymes. Viruses have none of these and reproduce inside the patient's own HOST CELLS, so there is no bacterial target to attack without damaging the patient. Size is irrelevant. Add: overuse drives antibiotic resistance, which is why it matters."},
  "MC-SEP-BIO-IMMUNITY":{type:"chain",title:"What a Vaccine Actually Does",instruction:"Complete the chain. Each step must be specific — 'it makes you immune' scores nothing.",prompt:"Dead or inactive pathogen injected → [step] → [step] → [step] → fast response on real infection.",answer:"Antigens on the harmless pathogen are recognised → lymphocytes produce specific antibodies → MEMORY CELLS remain in the body → on real infection antibodies are produced faster and in greater quantity, destroying the pathogen before symptoms develop. The error is thinking the vaccine itself provides the protective antibodies; it triggers the body to make its own and, crucially, to remember."},
  "MC-SEP-BIO-HOMEOSTASIS":{type:"sequence",title:"Filter, Then Take Back",instruction:"Put the kidney's stages in order, then state one substance that is ALWAYS reabsorbed and one that never is.",items:["Selective reabsorption","Urine passes to the bladder","Filtration of small molecules from blood","Water balance adjusted by ADH"],answer:"Filtration → selective reabsorption → ADH adjusts water → urine to bladder. Always reabsorbed: glucose (all of it, in a healthy person). Never reabsorbed: urea — it is the waste being removed. The word SELECTIVE is the mark: the kidney filters indiscriminately by size, then takes back what the body needs."},
  "MC-SEP-BIO-NERVOUS":{type:"sequence",title:"Build the Reflex Arc",instruction:"Put the reflex arc in order and label the two synapses. Then say why a reflex is faster than a considered action.",items:["Effector (muscle or gland)","Relay neurone","Stimulus","Sensory neurone","Receptor","Motor neurone","Response"],answer:"Stimulus → receptor → sensory neurone → relay neurone (in spinal cord) → motor neurone → effector → response. Synapses sit between sensory/relay and relay/motor. It is faster because the signal does not travel to the conscious brain — the relay neurone in the spinal cord short-cuts it. Reversing SENSORY and MOTOR is the usual error."},
  "MC-SEP-BIO-HORMONE":{type:"compare",title:"Nervous or Hormonal?",instruction:"Complete the table, then classify each response: pulling your hand off a hot pan; feeling adrenaline before an exam.",headers:["Feature","Nervous system","Endocrine system"],rows:[["Transmitted by","",""],["Speed","",""],["Duration of effect","",""]],answer:"Nervous: electrical impulses along neurones, very fast, short-lived, precise target. Endocrine: chemical hormones in the BLOODSTREAM, slower, longer-lasting, broader target. Hot pan = nervous (reflex). Adrenaline = hormonal. The error is saying hormones travel along nerves."},
  "MC-SEP-BIO-EVOLUTION":{type:"chain",title:"Natural Selection Without the Shortcut",instruction:"Complete the chain for antibiotic-resistant bacteria. Every step must avoid the words 'wanted', 'tried' or 'in order to'.",prompt:"A population of bacteria is exposed to an antibiotic → [step] → [step] → [step] → the population is mostly resistant.",answer:"Random MUTATION means variation already exists — a few bacteria are resistant BEFORE the antibiotic arrives → the antibiotic kills the non-resistant ones → survivors reproduce and pass on the resistance allele → the allele's frequency rises over generations. The error is Lamarckian: bacteria do not become resistant BECAUSE of the antibiotic, and organisms cannot adapt on purpose. Selection acts on variation that is already there."},
  "MC-SEP-BIO-ECOLOGY":{type:"calculate",title:"From Quadrat to Population",instruction:"A 1 m² quadrat is placed 10 times in a 500 m² field. Counts of daisies: 4, 6, 3, 5, 7, 2, 5, 4, 6, 8. Estimate the population, showing both steps.",answer:"Mean = 50 ÷ 10 = 5 per m². Estimated population = 5 × 500 = 2,500 daisies. Two exam points: placement must be RANDOM (e.g. coordinates from a random number generator) to avoid bias, and more quadrats give a more reliable mean. Quadrats suit plants and slow-moving organisms — use a transect if you are studying how distribution changes across a gradient."},
  "MC-SEP-BIO-CYCLES":{type:"chain",title:"Why Decomposers Matter",instruction:"Complete the chain, then answer: what would happen to plant growth if decomposers were removed?",prompt:"A leaf falls and dies → [step] → [step] → a plant takes up a mineral ion.",answer:"Decomposers (bacteria and fungi) break down the dead material → mineral ions are released into the soil → roots absorb them for making proteins and chlorophyll. Without decomposers, nutrients stay locked in dead matter, the soil is depleted and plant growth fails. Warmth, moisture and oxygen speed decay up — which is also why a fridge slows it."},
  "MC-SEP-BIO-FEEDBACK":{type:"diagram",title:"Close the Loop",instruction:"Draw a negative feedback loop for body temperature rising above 37°C. Label: receptor, coordinator, effector, and the response that returns it to normal.",prompt:"Common error: describing the response as making the change bigger.",answer:"Receptor (skin and hypothalamus detect rise) → coordinator (hypothalamus) → effectors (sweat glands secrete sweat; vasodilation of skin arterioles) → temperature FALLS back towards 37°C → the stimulus is removed. NEGATIVE means the response REVERSES the change, returning the variable to its set point. Positive feedback amplifies instead, which is why it is rare in homeostasis."},
  "MC-SEP-BIO-THYROID":{type:"chain",title:"The Thyroxine Loop",instruction:"Complete the loop, then state what happens when thyroxine levels rise too high.",prompt:"Thyroxine level falls → [gland] releases [hormone] → [gland] releases thyroxine → metabolic rate rises → ?",answer:"Pituitary releases TSH → thyroid releases thyroxine → metabolic rate rises → rising thyroxine INHIBITS TSH release from the pituitary → thyroxine production slows. That inhibition is the negative feedback. Thyroxine sets basal metabolic rate; too little slows growth and metabolism."},
  "MC-SEP-BIO-CYCLE":{type:"match",title:"Four Hormones, One Cycle",instruction:"Match each hormone to its role, then say which two are used in the combined contraceptive pill and why.",items:["FSH","LH","Oestrogen","Progesterone"],answer:"FSH: matures a follicle in the ovary and stimulates oestrogen production. LH: triggers OVULATION (around day 14). Oestrogen: rebuilds the uterus lining, inhibits FSH. Progesterone: maintains the lining, inhibits FSH and LH. The pill uses oestrogen and progesterone because both INHIBIT FSH, so no follicle matures. Confusing FSH with LH is the standard error — FSH grows it, LH releases it."},
  "MC-SEP-BIO-TROPHIC":{type:"sequence",title:"Number the Levels",instruction:"Number each organism's trophic level in this chain, then state what level a decomposer occupies.",items:["Fox","Grass","Rabbit"],answer:"Grass = level 1 (producer), rabbit = level 2 (primary consumer), fox = level 3 (secondary consumer). Producers are level ONE — starting the count at the first animal is the usual slip. Decomposers feed on every level, so they are not given a single number; they are usually shown separately."},
  "MC-SEP-BIO-FOODCHAIN":{type:"calculate",title:"Why Chains Run Out",instruction:"10,000 kJ enters the producers. Assuming 10% transfer between levels, work out the energy at each level, then explain why chains rarely exceed five links.",answer:"Producers 10,000 kJ → primary consumer 1,000 → secondary 100 → tertiary 10 → quaternary 1 kJ. By the fifth level there is not enough energy to support a viable population. Energy is lost as heat from respiration, in movement, in waste (faeces and urine), and in uneaten parts such as bone. Note the losses are of ENERGY, not of biomass alone."},
  "MC-SEP-BIO-BIODIVERSITY":{type:"evaluate",title:"Which Ecosystem Is Healthier?",instruction:"Ecosystem A has 40 species; ecosystem B has 6 but far more individuals. Decide which is more biodiverse and why, then give two human actions that reduce biodiversity and two that protect it.",answer:"A — biodiversity is the VARIETY of species and habitats, not the number of individuals. Reduce: deforestation, pollution, habitat destruction, introducing non-native species. Protect: breeding programmes, protected reserves, replanting hedgerows, reducing deforestation. Higher biodiversity generally means greater stability, because a species lost is more easily compensated for."},
  "MC-SEP-BIO-CARBON":{type:"chain",title:"Two Routes From Trees to CO₂",instruction:"Deforestation raises atmospheric carbon dioxide by TWO separate routes. Complete both chains.",prompt:"Route 1: fewer trees → [step] → CO₂ rises.   Route 2: felled timber is burned or decays → [step] → CO₂ rises.",answer:"Route 1: fewer trees means less PHOTOSYNTHESIS, so less CO₂ is removed from the atmosphere. Route 2: combustion or decomposition RELEASES carbon that was locked in the wood. Most students give only route 1 — the mark scheme wants both the reduced uptake and the active release."},
  "MC-SEP-BIO-BREEDING":{type:"compare",title:"Who Does the Selecting?",instruction:"Complete the table, then classify each: a farmer breeding the highest-yield wheat; moths darkening in a sooty city.",headers:["Feature","Selective breeding","Natural selection"],rows:[["Who chooses the parents?","",""],["Speed","",""],["Effect on variation","",""]],answer:"Selective breeding: humans choose, fast, REDUCES variation and the gene pool. Natural selection: environmental pressure decides, slow, acts on existing variation. Wheat = selective breeding; moths = natural selection. The risk of selective breeding is inbreeding: a shrunken gene pool makes inherited disease and total crop failure more likely."},
  // ---- GCSE Separate Chemistry
  "MC-SEP-CHEM-ATOM":{type:"calculate",title:"Fill the Shells",instruction:"Write the electronic structure for each, then state which group and period it is in. Use the shell limits 2, 8, 8.",items:["Sodium (11 electrons)","Chlorine (17)","Calcium (20)","Argon (18)"],answer:"Na 2,8,1 — group 1, period 3. Cl 2,8,7 — group 7, period 3. Ca 2,8,8,2 — group 2, period 4. Ar 2,8,8 — group 0, period 3. The two rules that earn marks: the number of OUTER electrons gives the group, the number of SHELLS gives the period. A neutral atom has electrons equal to protons."},
  "MC-SEP-CHEM-ISOTOPE":{type:"calculate",title:"Protons, Neutrons, Mass Number",instruction:"Complete the table. Then say what makes two atoms isotopes of each other.",headers:["Atom","Protons","Neutrons","Mass number"],rows:[["17 protons, 18 neutrons","17","18",""],["Carbon-14","6","",""],["Oxygen-16","8","",""]],answer:"35; carbon-14 has 8 neutrons; oxygen-16 has 8 neutrons. Mass number = protons + neutrons. Isotopes have the SAME number of protons (so the same element and the same chemistry) but DIFFERENT numbers of neutrons. Because chemistry depends on electrons, isotopes react identically — only mass and stability differ."},
  "MC-SEP-CHEM-BOND":{type:"sort",title:"Which Structure Explains the Property?",instruction:"Sort each substance by structure, then use the structure to explain the property given.",items:["Diamond — very high melting point","Carbon dioxide — gas at room temperature","Sodium chloride — conducts only when molten or dissolved","Copper — conducts electricity as a solid"],answer:"Giant covalent (diamond): many strong covalent bonds throughout the lattice, so a huge amount of energy is needed. Simple molecular (CO₂): weak INTERMOLECULAR forces between molecules — the covalent bonds inside stay intact. Giant ionic (NaCl): ions fixed in a solid lattice, mobile only when molten or aqueous. Metallic (Cu): delocalised electrons free to move. The classic error is saying you 'break covalent bonds' when boiling CO₂ — you overcome the forces BETWEEN molecules."},
  "MC-SEP-CHEM-STATES":{type:"correct",title:"Physical, Not Chemical",instruction:"Correct each statement about melting ice.",items:["'The water molecules break apart into hydrogen and oxygen.'","'Melting makes a new substance.'","'The particles get bigger when the solid melts.'"],answer:"1 Molecules stay intact; only the FORCES between them are overcome. 2 Melting is a PHYSICAL change — the substance is the same and it is reversible. 3 Particles do not change size or mass; their arrangement, spacing and energy change. Getting 'the particles themselves change' out of students' answers is the whole point of this starter."},
  "MC-SEP-CHEM-FORMULA":{type:"calculate",title:"Balance the Charges",instruction:"Work out the formula of each ionic compound by balancing charges. Show the ions first.",items:["Magnesium oxide","Sodium chloride","Calcium chloride","Aluminium oxide"],answer:"Mg²⁺ + O²⁻ → MgO (1:1). Na⁺ + Cl⁻ → NaCl. Ca²⁺ + 2Cl⁻ → CaCl₂. 2Al³⁺ + 3O²⁻ → Al₂O₃. The compound must be electrically NEUTRAL — the total positive charge equals the total negative charge. Writing MgO₂ or AlO shows charges were not balanced."},
  "MC-SEP-CHEM-REACTION":{type:"classify",title:"Chemical Change or Not?",instruction:"Mark each C (chemical change) or P (physical). For the chemical ones, name the evidence.",items:["Bubbles form when magnesium is added to acid","Ice melts into water","A colour change when two solutions are mixed","Salt dissolves in water","A precipitate forms","The mixture gets noticeably hot"],answer:"C: bubbles (gas produced), colour change, precipitate, temperature change. P: melting, dissolving — both reversible with no new substance. The best single indicator is that a NEW SUBSTANCE has formed and the change is not easily reversed. Dissolving fools students because it looks dramatic, but the salt is recoverable by evaporation."},
  "MC-SEP-CHEM-ACID":{type:"sort",title:"Place Them on the Scale",instruction:"Place each on a pH scale from 0 to 14, then answer the question below.",items:["Pure water","Stomach acid","Sodium hydroxide solution","Vinegar","Baking soda solution"],prompt:"A solution moves from pH 5 to pH 3. By what factor has hydrogen ion concentration changed?",answer:"Water 7, stomach acid ~1-2, NaOH ~13-14, vinegar ~3, baking soda ~9. pH 5 to pH 3 is TWO steps, and the scale is logarithmic — hydrogen ion concentration is 100× greater, not 2× . Neutral is pH 7 because hydrogen and hydroxide ion concentrations are equal."},
  "MC-SEP-CHEM-ACIDMETAL":{type:"correct",title:"Three Acid Reactions, Three Products",instruction:"Complete each general equation, then name the test for each gas produced.",items:["acid + metal →","acid + metal carbonate →","acid + metal oxide / alkali →"],answer:"acid + metal → SALT + HYDROGEN (squeaky pop with a lit splint). acid + metal carbonate → SALT + WATER + CARBON DIOXIDE (limewater turns cloudy). acid + base → SALT + WATER only (neutralisation, no gas). The error this catches is giving hydrogen for the carbonate reaction — carbonates give carbon dioxide, and the difference is worth checking every time."},
  "MC-SEP-CHEM-TITRATION":{type:"sequence",title:"Order the Titration",instruction:"Put the steps in order, then say why a rough titration is done first and why readings must be concordant.",items:["Add acid from the burette, swirling, until the indicator just changes","Record the final burette reading","Pipette 25 cm³ of alkali into a conical flask","Repeat until two readings agree within 0.10 cm³","Add a few drops of indicator"],answer:"Pipette alkali → add indicator → add acid to the endpoint → record reading → repeat for concordant results. The rough run finds the approximate endpoint so later runs can be added dropwise near it. Concordant results (within 0.10 cm³) show the measurement is REPEATABLE, so the mean is reliable. A titration measures the VOLUME needed to neutralise — not the strength of the acid directly."},
  "MC-SEP-CHEM-ELECTRO":{type:"diagram",title:"Which Electrode, Which Reaction?",instruction:"Draw an electrolysis cell for molten lead bromide. Label the anode and cathode with their charges, show which ion goes where, and write what happens at each.",prompt:"Common error: sending positive ions to the positive electrode.",answer:"CATHODE is NEGATIVE and attracts CATIONS (positive ions, Pb²⁺), which GAIN electrons — REDUCTION. ANODE is POSITIVE and attracts ANIONS (Br⁻), which LOSE electrons — OXIDATION. Opposite charges attract, so positive ions go to the negative electrode. Memory hook: PANIC — Positive is Anode, Negative Is Cathode. Reduction happens at the cathode (both start with a consonant pairing students can hold)."},
  "MC-SEP-CHEM-YIELD":{type:"calculate",title:"Actual Over Theoretical",instruction:"Calculate the percentage yield, then give three reasons a real yield is below 100%.",prompt:"A reaction could theoretically make 8.0 g of product. A student obtains 6.4 g.",answer:"6.4 ÷ 8.0 × 100 = 80%. Reasons: the reaction is incomplete or reversible; product is lost on transfer or when filtering; side reactions make unwanted products. Note the formula is ACTUAL ÷ THEORETICAL — inverting it gives values above 100%, which should immediately signal an error. Percentage yield says nothing about how FAST or how ECONOMICAL the reaction is; that is rate and atom economy."},
  "MC-SEP-CHEM-ANALYSIS":{type:"match",title:"Flame Test Colours",instruction:"Match each metal ion to its flame colour, then state one limitation of flame tests.",items:["Lithium","Sodium","Potassium","Calcium","Copper"],answer:"Li crimson/red; Na yellow; K lilac; Ca orange-red; Cu green/blue-green. Limitation: a strong sodium yellow MASKS other colours in a mixture, and the test identifies the metal ion only — not the compound or the negative ion. For mixtures, instrumental methods are more reliable and more sensitive."},
  "MC-SEP-CHEM-EQUIL2":{type:"evaluate",title:"What Actually Shifts It?",instruction:"For each change, state whether the equilibrium POSITION shifts, and whether the equilibrium CONSTANT changes.",items:["Raising the temperature","Adding a catalyst","Increasing pressure in a gas reaction with unequal moles","Adding more reactant"],answer:"Temperature: position shifts AND the constant changes — the only one that changes the constant. Catalyst: NEITHER — it speeds both directions equally and only shortens the time to reach equilibrium. Pressure: position shifts towards the side with fewer gas moles; constant unchanged. More reactant: position shifts right; constant unchanged. 'A catalyst improves the yield' is the error to kill here."},
  "MC-SEP-CHEM-MR":{type:"calculate",title:"Count Every Atom",instruction:"Calculate the relative formula mass of each. Use H=1, C=12, N=14, O=16, Ca=40.",items:["H₂O","CO₂","CaCO₃","Ca(OH)₂"],answer:"H₂O = 18. CO₂ = 44. CaCO₃ = 40 + 12 + 48 = 100. Ca(OH)₂ = 40 + 2×(16+1) = 74. The bracket is the trap: everything inside is multiplied by the subscript outside, so there are TWO oxygens and TWO hydrogens, not one of each. Multiply the subscript by the atomic mass, never add it."},
  "MC-SEP-CHEM-NANO":{type:"calculate",title:"Why Small Means Reactive",instruction:"A cube has sides of 10 cm. Work out its surface area, volume and their ratio. Then repeat for a 1 cm cube, and explain what this tells you about nanoparticles.",answer:"10 cm cube: SA 600 cm², volume 1000 cm³, ratio 0.6. 1 cm cube: SA 6 cm², volume 1 cm³, ratio 6 — TEN times higher. As particles get smaller the surface-area-to-volume ratio rises sharply, so a far greater proportion of atoms sit on the surface where reactions occur. That is why nanoparticles are effective catalysts and why less material is needed. Risks: they may pass into cells or the bloodstream, and long-term effects are not fully known."},
  "MC-SEP-CHEM-SURFACE":{type:"diagnose",title:"Powder Beats Lumps — But Why?",instruction:"A student says powdered marble reacts faster with acid than marble chips 'because the powder has more energy'. Identify the error and give the correct explanation in terms of collisions.",answer:"The error is confusing surface area with energy. Breaking a solid into smaller pieces does not change particle energy at all. It exposes MORE SURFACE AREA, so more particles are available at the surface to be hit — collisions become more FREQUENT. Energy per collision is unchanged, which is why the temperature effect is different: temperature raises both frequency AND the proportion of collisions exceeding activation energy."},
  "MC-SEP-CHEM-RATE":{type:"sort",title:"Frequency, Energy, or Both?",instruction:"For each change, state whether it increases collision FREQUENCY, collision ENERGY, or both.",items:["Raising the temperature","Increasing concentration","Using a powder instead of lumps","Adding a catalyst","Increasing gas pressure"],answer:"Temperature: BOTH — particles move faster and more collisions exceed the activation energy. Concentration, surface area and pressure: frequency only. A catalyst: NEITHER — it provides an alternative pathway with LOWER activation energy, so a greater proportion of existing collisions succeed. Temperature is the only one on this list that changes collision energy, and that is why it usually has the largest effect."},
  "MC-SEP-CHEM-EQUIL":{type:"correct",title:"Equal Rates, Not Equal Amounts",instruction:"Correct each statement about dynamic equilibrium in a closed system.",items:["'At equilibrium both reactions stop.'","'At equilibrium there are equal amounts of reactants and products.'","'Equilibrium can be reached in an open beaker.'"],answer:"1 Both reactions CONTINUE — that is what 'dynamic' means; the forward and reverse RATES are equal. 2 Concentrations are CONSTANT, not equal — the position may lie far to either side. 3 It requires a CLOSED system, or products escape and equilibrium can never establish. All three of these appear in student answers every year."},
  "MC-SEP-CHEM-EXTRACT":{type:"sort",title:"Carbon or Electrolysis?",instruction:"For each metal, state the extraction method and justify it using the reactivity series.",items:["Aluminium","Iron","Zinc","Gold","Potassium"],answer:"Above carbon (K, Na, Ca, Mg, Al) → ELECTROLYSIS, because their oxides are too stable for carbon to reduce. Below carbon (Zn, Fe, Cu, Pb) → reduction with CARBON in a furnace, which is cheaper. Gold is so unreactive it is found NATIVE, as the uncombined metal. Aluminium is the one students get wrong — it is common and cheap to buy, so they assume it is easy to extract, but electrolysis makes it energy-intensive."},
  "MC-SEP-CHEM-REDOX":{type:"classify",title:"OIL RIG in Practice",instruction:"For each half-equation, state whether it shows oxidation or reduction and say which species is the reducing agent overall.",items:["Mg → Mg²⁺ + 2e⁻","Cl₂ + 2e⁻ → 2Cl⁻","Fe²⁺ → Fe³⁺ + e⁻","Cu²⁺ + 2e⁻ → Cu"],answer:"1 Oxidation (loss). 2 Reduction (gain). 3 Oxidation. 4 Reduction. OIL RIG — Oxidation Is Loss, Reduction Is Gain (of electrons). In Mg + Cl₂, magnesium is oxidised so it is the REDUCING agent; chlorine is reduced so it is the oxidising agent. That inversion is the part students reliably get backwards: the substance oxidised is the one doing the reducing."},
  "MC-SEP-CHEM-ORGANIC":{type:"distinguish",title:"Alkane or Alkene?",instruction:"Classify each, give its general formula, and name the test that distinguishes the two families.",items:["Ethene, C₂H₄","Methane, CH₄","Propene, C₃H₆","Ethane, C₂H₆"],answer:"Alkenes (C₂H₄, C₃H₆): general formula CₙH₂ₙ, contain a C=C DOUBLE bond, unsaturated. Alkanes (CH₄, C₂H₆): CₙH₂ₙ₊₂, single bonds only, saturated. Test: bromine water goes from ORANGE TO COLOURLESS with an alkene (it adds across the double bond) and stays orange with an alkane. Note 'colourless', not 'clear' — the mark scheme distinguishes them."},
  "MC-SEP-CHEM-POLYMER":{type:"compare",title:"Addition or Condensation?",instruction:"Complete the table, then classify: poly(ethene), and a polyester.",headers:["Feature","Addition polymerisation","Condensation polymerisation"],rows:[["Monomer feature","",""],["Small molecule lost?","",""],["Example","",""]],answer:"Addition: monomers have a C=C double bond, NO small molecule lost, all atoms end up in the polymer (100% atom economy) — poly(ethene). Condensation: monomers have TWO functional groups each, a small molecule (usually water) IS lost each time a link forms — polyester. The error is thinking condensation needs a double bond; it needs two reactive ends."},
  "MC-SEP-CHEM-WATER":{type:"distinguish",title:"Potable Is Not Pure",instruction:"Decide whether each statement describes POTABLE water, PURE water, or both.",items:["Contains dissolved minerals","Boils at exactly 100°C at 1 atmosphere","Safe to drink","Contains only H₂O molecules","Produced by distillation"],answer:"Potable: dissolved minerals, safe to drink. Pure: boils at exactly 100°C, only H₂O molecules, produced by distillation. Only 'safe to drink' can loosely apply to both. In chemistry PURE means a single substance — so tap water is potable but chemically impure, and mineral water advertised as 'pure' is not. Treatment: filtration removes solids, sterilisation (chlorine, ozone or UV) kills microbes."},
  "MC-SEP-CHEM-ATMOS":{type:"correct",title:"Complete or Incomplete?",instruction:"Write the products of each, then say which produces the toxic gas and why it is dangerous.",items:["Complete combustion of methane","Incomplete combustion of methane"],answer:"Complete (plenty of oxygen): carbon dioxide + water. Incomplete (limited oxygen): carbon monoxide and/or carbon (soot) + water. CARBON MONOXIDE is the danger — it is colourless and odourless, and binds to haemoglobin in place of oxygen, so the blood cannot carry oxygen. Carbon dioxide is the greenhouse gas from complete combustion; students frequently swap the two."},
  "MC-SEP-CHEM-GAS":{type:"match",title:"Four Gases, Four Tests",instruction:"Match each gas to its test AND the positive result. Getting only half of each scores nothing.",items:["Carbon dioxide","Oxygen","Hydrogen","Chlorine"],answer:"CO₂: bubble through limewater → turns cloudy/milky. O₂: glowing splint → RELIGHTS. H₂: lit splint → squeaky POP. Cl₂: damp litmus paper → bleached white. Two traps: the oxygen test uses a GLOWING splint and the hydrogen test a LIT one — swapping them loses the mark; and the litmus must be DAMP."},
  "MC-SEP-CHEM-FRACTION":{type:"diagram",title:"Label the Column",instruction:"Draw a fractionating column. Mark where it is hottest and coolest, and where these condense: refinery gases, petrol, kerosene, diesel, bitumen. Then explain what property separates them.",answer:"Hot at the BOTTOM, cool at the top. Bitumen at the very bottom (longest chains), then diesel, kerosene, petrol, refinery gases at the top (shortest). Separation is by BOILING POINT, which rises with chain length because longer molecules have stronger intermolecular forces. Longer chains are also more viscous, less volatile and less flammable — all four properties follow chain length."},
  "MC-SEP-CHEM-CRACK":{type:"chain",title:"Why Crack at All?",instruction:"Complete the reasoning, then write a balanced example equation.",prompt:"Crude oil gives more long-chain hydrocarbons than the market wants → [step] → [step] → cracking is economically worthwhile.",answer:"Demand for short chains (petrol, and alkenes for polymers) exceeds supply → cracking breaks long chains into shorter, more useful alkanes plus alkenes → supply is matched to demand and higher-value products are made. Example: C₁₀H₂₂ → C₈H₁₈ + C₂H₄. Conditions: high temperature with a catalyst, or steam. Note cracking always produces at least one ALKENE — that is what feeds the polymer industry."},
  "MC-SEP-CHEM-FOOD":{type:"match",title:"Food Test to Result",instruction:"Match each nutrient to its test and the positive colour change. State which test needs heating.",items:["Starch","Reducing sugar","Protein","Lipid"],answer:"Starch: iodine solution, orange-brown → BLUE-BLACK. Reducing sugar: Benedict's solution, blue → green/orange/BRICK-RED, and this is the one that must be HEATED in a water bath. Protein: biuret, blue → PURPLE/lilac. Lipid: ethanol emulsion test → cloudy white emulsion. Always state the colour BEFORE and AFTER — 'it goes blue-black' without the starting colour is a half answer."},
  "MC-SEP-CHEM-ENERGY":{type:"sort",title:"Renewable Does Not Mean Harmless",instruction:"Sort each into renewable or non-renewable, then name one environmental drawback of a renewable one.",items:["Coal","Wind","Biofuel","Natural gas","Solar","Nuclear"],answer:"Renewable: wind, biofuel, solar. Non-renewable: coal, natural gas, and nuclear (uranium is a finite resource, which is the one students misfile). Renewable means REPLENISHED on a human timescale — not that it is impact-free. Drawbacks: wind farms affect landscape and habitats; biofuels compete with food crops for land and can drive deforestation; solar panel manufacture is energy- and material-intensive."},
  "MC-SEP-CHEM-BRINE":{type:"diagram",title:"Three Products From Salty Water",instruction:"Draw the electrolysis of concentrated brine. Label what forms at each electrode and what remains in solution, then give a use for each product.",answer:"ANODE: chlorine (bleach, water treatment, PVC). CATHODE: hydrogen (fuel, making ammonia, margarine). SOLUTION: sodium hydroxide (soap, paper, bleach). Sodium is NOT produced despite being in the compound — hydrogen is discharged instead because it is less reactive than sodium. Test the gases: chlorine bleaches damp litmus, hydrogen gives a squeaky pop."},
  "MC-SEP-CHEM-CHROM":{type:"calculate",title:"Work Out the Rf",instruction:"A spot travels 3.6 cm; the solvent front travels 8.0 cm. Calculate the Rf value, then answer the two questions below.",prompt:"(a) Why must the start line be drawn in pencil? (b) Why must the start line sit ABOVE the solvent level?",answer:"Rf = distance moved by spot ÷ distance moved by solvent = 3.6 ÷ 8.0 = 0.45. Rf is always between 0 and 1 — a value above 1 means the two distances were inverted. (a) Pencil is insoluble; ink would dissolve and run, contaminating the result. (b) If the line is below the solvent, the sample dissolves into the solvent reservoir instead of travelling up the paper. Chromatography separates SOLUBLE substances by how strongly each is attracted to the stationary versus mobile phase."},
  "MC-SEP-CHEM-CARBON":{type:"evaluate",title:"Is It Really Carbon-Neutral?",instruction:"A company claims its biofuel is carbon-neutral because the crop absorbed as much CO₂ as burning it releases. List the lifecycle stages the claim ignores, then give your verdict.",answer:"Ignored: fertiliser manufacture and application, farm machinery fuel, processing and refining, transport to market, and land-use change — clearing forest or peatland to plant the crop can release a carbon store that takes decades to repay. Verdict: carbon-neutral AT THE POINT OF USE, but rarely across the full lifecycle. The transferable point is that a boundary drawn narrowly enough makes almost anything look neutral, so always ask where the boundary was drawn."},
  // ---- GCSE Separate Physics
  "MC-SEP-PHYS-MOTION":{type:"calculate",title:"Average Speed, Not Halfway Speed",instruction:"Work each out, showing the formula first.",items:["A runner covers 240 m in 30 s. Average speed?","A car travels 30 km at 60 km/h, then 30 km at 30 km/h. Average speed for the whole trip?"],answer:"1 speed = distance ÷ time = 240 ÷ 30 = 8 m/s. 2 NOT 45 km/h. Time = 0.5 h + 1.0 h = 1.5 h for 60 km, so average = 60 ÷ 1.5 = 40 km/h. Average speed is ALWAYS total distance ÷ total time — averaging the two speeds is the classic trap, and it is wrong whenever the times differ."},
  "MC-SEP-PHYS-FORCE":{type:"calculate",title:"Mass Stays, Weight Changes",instruction:"An astronaut has a mass of 70 kg. Complete the table (g = 10 N/kg on Earth, 1.6 N/kg on the Moon), then state what changes and what does not.",headers:["Location","Mass (kg)","Weight (N)"],rows:[["Earth","70",""],["Moon","",""],["Deep space (g ≈ 0)","",""]],answer:"Earth 70 kg, 700 N. Moon 70 kg, 112 N. Deep space 70 kg, ~0 N. MASS is the amount of matter, measured in kilograms, and never changes. WEIGHT is a force caused by gravity, measured in newtons, W = mg. 'The astronaut is weightless so has no mass' is the error — mass is unchanged everywhere."},
  "MC-SEP-PHYS-NEWTON":{type:"classify",title:"Is the Resultant Force Zero?",instruction:"For each, state whether the resultant force is zero, and what that means for the motion.",items:["A book resting on a table","A car at a steady 30 mph on a straight road","A skydiver at terminal velocity","A car speeding up","A ball at the very top of its flight"],answer:"Zero: book, steady car, terminal-velocity skydiver — all have NO ACCELERATION. Not zero: the accelerating car; and the ball at the top, where velocity is momentarily zero but weight still acts, so it is accelerating downwards. Newton's First Law: zero resultant force means at rest OR constant velocity. 'No force means not moving' is the misconception — a constant speed in a straight line also needs zero resultant."},
  "MC-SEP-PHYS-ENERGY":{type:"chain",title:"Name the Stores, Not the Types",instruction:"For each event, write the energy transfer as: store → store, and name the pathway (mechanically, electrically, by heating, by radiation).",items:["A book is lifted onto a shelf","A ball falls from the shelf","A kettle boils water","A car brakes to a stop"],answer:"Lifting: chemical (in the person) → GRAVITATIONAL potential, mechanically. Falling: gravitational → KINETIC, mechanically. Kettle: electrical supply → THERMAL store of the water, electrically then by heating. Braking: kinetic → thermal store of brakes and surroundings, by heating. Energy is not 'used up' — it is transferred between STORES, and dissipated energy is spread out to the surroundings, not destroyed."},
  "MC-SEP-PHYS-POWER":{type:"calculate",title:"Same Job, Different Power",instruction:"Two cranes each lift a 500 N load 10 m. Crane A takes 5 s, crane B takes 20 s. Calculate the work done and the power of each, then state what differs.",answer:"Work done = force × distance = 500 × 10 = 5000 J for BOTH. Power = work ÷ time: A = 5000 ÷ 5 = 1000 W; B = 5000 ÷ 20 = 250 W. The ENERGY TRANSFERRED is identical; only the RATE differs. Power is energy transferred per second, measured in watts — a watt is a joule per second. Describing the more powerful crane as doing 'more work' is the error."},
  "MC-SEP-PHYS-CIRCUIT":{type:"diagram",title:"Current Is Not Used Up",instruction:"Draw a series circuit with a cell and two identical lamps. Mark the current before the first lamp, between the lamps, and after the second. Then mark the potential difference across each lamp.",prompt:"Common error: showing the current getting smaller after each lamp.",answer:"The CURRENT IS THE SAME at all three points — there is only one path and charge is conserved, so nothing is 'used up'. What IS shared is POTENTIAL DIFFERENCE: the supply p.d. divides between the components, so each identical lamp gets half. Students confuse the two because both lamps do get dimmer as you add more — that is caused by higher total resistance reducing the current everywhere equally."},
  "MC-SEP-PHYS-ELECTRIC":{type:"calculate",title:"Three Power Calculations",instruction:"Use P = IV (and V = IR where needed). Show which equation you chose before substituting.",items:["A 230 V kettle draws 10 A. Power?","A 12 V lamp is rated 24 W. Current?","A 2 A current flows through a 20 Ω resistor. Power?"],answer:"1 P = IV = 230 × 10 = 2300 W. 2 I = P ÷ V = 24 ÷ 12 = 2 A. 3 V = IR = 2 × 20 = 40 V, then P = IV = 2 × 40 = 80 W (or P = I²R = 4 × 20 = 80 W). Choosing the equation before substituting is what prevents the usual muddle between P = IV and V = IR."},
  "MC-SEP-PHYS-TRANSFORM":{type:"correct",title:"Why AC and Not DC?",instruction:"A student writes: 'A transformer works with direct current because the current flows steadily through the coils.' Identify the error and write the correct explanation in three linked steps.",answer:"A transformer needs a CHANGING magnetic field. Steps: alternating current in the primary coil produces a CHANGING magnetic field → the changing field passes through the iron core to the secondary coil → a changing field INDUCES a potential difference in the secondary. Direct current gives a CONSTANT magnetic field, so nothing changes, nothing is induced, and no output p.d. is produced. The core is iron because it is easily magnetised; it does not carry current between the coils."},
  "MC-SEP-PHYS-CHARGE":{type:"calculate",title:"Charge, Current, Time",instruction:"Use Q = It. Then state the unit of each quantity.",items:["A current of 3 A flows for 20 s. Charge transferred?","240 C passes a point in 60 s. Current?","How long for 5 A to transfer 100 C?"],answer:"1 Q = 3 × 20 = 60 C. 2 I = Q ÷ t = 240 ÷ 60 = 4 A. 3 t = Q ÷ I = 100 ÷ 5 = 20 s. Charge in COULOMBS, current in AMPERES, time in SECONDS. Current is the RATE of flow of charge — one ampere is one coulomb per second. Calling current 'the amount of electricity' hides exactly this distinction."},
  "MC-SEP-PHYS-PARALLEL":{type:"diagram",title:"Parallel Shares Current, Not Voltage",instruction:"Draw a 12 V supply with two identical lamps in PARALLEL. Mark the p.d. across each lamp and the current in each branch and in the main circuit.",prompt:"Then repeat for the same two lamps in SERIES and compare.",answer:"Parallel: each lamp gets the FULL 12 V, because each branch connects the same two points. The CURRENT splits between branches and the branch currents sum to the main current. Series: the 12 V DIVIDES (6 V each) and the current is the same throughout. The rule to hold: parallel shares current and shares p.d. equally; series shares p.d. and keeps current equal."},
  "MC-SEP-PHYS-WAVE":{type:"distinguish",title:"Frequency, Wavelength, Period",instruction:"Define each in one line with its unit, then calculate the missing values.",items:["A wave has frequency 50 Hz. What is its period?","A wave travels at 340 m/s with wavelength 2 m. Frequency?","Amplitude is doubled — what happens to frequency?"],answer:"Frequency: complete waves passing a point per second, hertz. Wavelength: distance between two identical points on adjacent waves, metres. Period: time for ONE complete wave, seconds — and T = 1 ÷ f. So 1 ÷ 50 = 0.02 s. Wave speed v = fλ, so f = 340 ÷ 2 = 170 Hz. Doubling amplitude changes NOTHING about frequency — amplitude carries energy/loudness, frequency carries pitch. That independence is the point students miss."},
  "MC-SEP-PHYS-EM":{type:"sort",title:"Which Waves Cross a Vacuum?",instruction:"Sort each into 'can travel through a vacuum' or 'needs a medium', then state the wave type for each group.",items:["Light","Sound","Radio waves","Water ripples","X-rays","Seismic P-waves"],answer:"Vacuum: light, radio, X-rays — all ELECTROMAGNETIC, all transverse, all travelling at 3×10⁸ m/s in a vacuum. Need a medium: sound, water ripples, seismic waves — all MECHANICAL, requiring particles to vibrate. This is why there is no sound in space but we still see the Sun. Order of the EM spectrum: radio, microwave, infrared, visible, ultraviolet, X-ray, gamma."},
  "MC-SEP-PHYS-OHM":{type:"graph",title:"Straight Line or Curve?",instruction:"Sketch current against potential difference for (a) a fixed resistor at constant temperature and (b) a filament lamp. Explain the difference in shape.",answer:"(a) Straight line THROUGH THE ORIGIN — current is directly proportional to p.d., so resistance is constant. This is ohmic behaviour, and it holds only at CONSTANT TEMPERATURE. (b) An S-shaped curve that flattens: as current rises the filament heats, ions vibrate more, electrons collide more often, RESISTANCE INCREASES, so current rises less steeply. A lamp is non-ohmic for exactly that reason — the condition in Ohm's law is not an afterthought."},
  "MC-SEP-PHYS-HOUSE":{type:"evaluate",title:"Why Houses Are Not Wired in Series",instruction:"List three things that would go wrong if a house were wired in series, then state the two advantages of parallel wiring.",answer:"In series: switching off one appliance would break the circuit and stop EVERYTHING; each appliance would receive only a share of the 230 V, so none would work properly; adding an appliance would dim all the others by raising total resistance. Parallel: every appliance receives the FULL supply p.d., and each can be switched independently without affecting the rest. Each branch also has its own fuse or breaker."},
  "MC-SEP-PHYS-MAGNET":{type:"diagram",title:"Field Around a Wire",instruction:"Draw the magnetic field around a straight current-carrying wire and around a solenoid. Mark the field direction and state the rule you used. Then say what happens if the current reverses.",answer:"Straight wire: concentric CIRCLES around the wire, direction from the right-hand grip rule (thumb along conventional current, fingers curl the field). Solenoid: field like a bar magnet, uniform and strong inside, with the ends acting as N and S poles. Reversing the current REVERSES the field direction. Field strength rises with current, with more turns, and with an iron core. A wire with no current has no magnetic field at all."},
  "MC-SEP-PHYS-UNITS":{type:"match",title:"Quantity to Unit",instruction:"Give the correct unit for each, then say which two are most often confused and why.",items:["Energy","Power","Force","Charge","Potential difference","Momentum"],answer:"Joule; watt; newton; coulomb; volt; kg m/s. The pair confused most is ENERGY (joule) and POWER (watt) — a watt is a joule PER SECOND, so power is a rate. That is why an electricity bill in kilowatt-HOURS measures energy, not power: power multiplied by time. Writing 'the kettle uses 2000 W of energy' merges the two."},
  "MC-SEP-PHYS-MOMENTUM":{type:"calculate",title:"Momentum Has Direction",instruction:"Calculate each, treating right as positive.",items:["A 4 kg object moves right at 3 m/s","A 2 kg ball moves left at 5 m/s","Total momentum of both together"],answer:"1 p = mv = 4 × 3 = +12 kg m/s. 2 p = 2 × 5 = −10 kg m/s (LEFT, so negative). 3 Total = +12 − 10 = +2 kg m/s to the right. Momentum is a VECTOR, so direction and sign matter — adding magnitudes to get 22 is the standard error. In a closed system total momentum is conserved, which only works if signs are handled properly."},
  "MC-SEP-PHYS-GAS":{type:"explain",title:"Why Squeezing Raises Pressure",instruction:"A sealed syringe of gas is compressed to half its volume at constant temperature. Explain the pressure change in terms of particles, in three steps.",prompt:"Common error: 'the particles get squashed' or 'the particles get hotter'.",answer:"Smaller volume → the same number of particles travel shorter distances between walls, so they hit the walls MORE OFTEN per second → more frequent collisions means greater total force on each unit area → pressure rises. At constant temperature the particles' average SPEED and kinetic energy are unchanged; only collision FREQUENCY changes. Particles themselves are not compressed — the space between them is."},
  "MC-SEP-PHYS-LIQUID":{type:"evaluate",title:"What Sets the Pressure at Depth?",instruction:"State whether each change increases, decreases, or does not affect the pressure at the bottom of a container of liquid.",items:["Filling it deeper","Using mercury instead of water","Using a much wider container, same depth","Taking it to the Moon"],answer:"Deeper: INCREASES. Denser liquid: INCREASES. Wider container at the same depth: NO CHANGE — this is the one that surprises students, but pressure = height × density × g, and area does not appear. On the Moon: DECREASES, because g is smaller. Pressure at depth depends on depth, density and gravitational field strength only — never on the total volume or the shape of the vessel."},
  "MC-SEP-PHYS-DENSITY":{type:"calculate",title:"Mass Over Volume",instruction:"Calculate each, watching the units.",items:["200 g object, volume 50 cm³","A 2 kg block measuring 10 cm × 10 cm × 10 cm, in g/cm³","Which floats in water (1 g/cm³): a 5 kg log of volume 8000 cm³?"],answer:"1 ρ = m ÷ V = 200 ÷ 50 = 4 g/cm³. 2 2 kg = 2000 g, V = 1000 cm³, so 2 g/cm³. 3 5000 ÷ 8000 = 0.625 g/cm³, which is less than 1, so it FLOATS. Floating depends on DENSITY, not mass — a heavy log floats and a small coin sinks, which is the intuition to correct here."},
  "MC-SEP-PHYS-RESIST":{type:"chain",title:"Hotter Wire, Higher Resistance",instruction:"Complete the chain explaining why a metal wire's resistance rises when heated.",prompt:"Temperature rises → [step] → [step] → resistance increases.",answer:"Metal IONS in the lattice vibrate more strongly with greater amplitude → electrons flowing through collide with them MORE OFTEN → electron flow is impeded, so resistance rises. Note it is the fixed ions that vibrate, not the electrons 'slowing down by themselves'. This is why a filament lamp is non-ohmic, and why a thermistor — a semiconductor — does the OPPOSITE, its resistance falling as temperature rises."},
  "MC-SEP-PHYS-MOTOR":{type:"diagram",title:"Fleming's Left Hand",instruction:"Draw a wire carrying current through a magnetic field between two magnets. Use Fleming's left-hand rule to mark the force direction, then state what happens if you reverse (a) the current and (b) the field.",answer:"Left hand: FIRst finger = FIeld (N to S), seCond finger = Current (conventional, + to −), thuMb = Motion/force. Reversing EITHER the current or the field reverses the force. Reversing BOTH leaves the force unchanged — that is why a motor needs a split-ring commutator, to flip the current every half turn and keep it spinning one way. Force is greatest when the wire is at 90° to the field, and zero when parallel to it."},
  "MC-SEP-PHYS-RADIATION":{type:"compare",title:"Penetration Against Ionisation",instruction:"Complete the table, then answer: which is most dangerous inside the body, and which outside?",headers:["Type","Stopped by","Penetrating power","Ionising power"],rows:[["Alpha","","",""],["Beta","","",""],["Gamma","","",""]],answer:"Alpha: paper/skin, least penetrating, MOST ionising. Beta: a few mm of aluminium, moderate, moderate. Gamma: thick lead or concrete, most penetrating, LEAST ionising. Penetration and ionisation run in OPPOSITE directions — that is the whole table. Inside the body ALPHA is most dangerous, because all its ionising energy is deposited in nearby tissue. Outside the body gamma is the greater hazard, because alpha cannot get through skin."},
  "MC-SEP-PHYS-HALFLIFE":{type:"calculate",title:"Halving What Remains",instruction:"A sample has an activity of 800 Bq and a half-life of 6 days. Complete the table, then answer the question.",headers:["Days elapsed","Half-lives","Activity (Bq)"],rows:[["0","0","800"],["6","1",""],["12","2",""],["18","3",""]],prompt:"After how many days does activity fall to 50 Bq?",answer:"400, 200, 100 Bq. 50 Bq is four half-lives, so 24 days. Each half-life halves WHAT REMAINS, so the decay never reaches zero — two half-lives leave a QUARTER, not nothing. 'Two half-lives means it has all gone' is the misconception this catches. Half-life is also random and unpredictable per nucleus; it is a statistical average over very many nuclei."},
  "MC-SEP-PHYS-BACKGROUND":{type:"sort",title:"Where Background Radiation Comes From",instruction:"Sort each source into NATURAL or HUMAN-MADE, then say which single source contributes most in the UK.",items:["Radon gas from rocks","Cosmic rays","Medical X-rays","Food and drink","Nuclear power waste","Rocks and soil"],answer:"Natural: radon, cosmic rays, food and drink, rocks and soil. Human-made: medical X-rays, nuclear waste. RADON GAS is the largest single UK contributor, and it varies sharply by region depending on local geology (granite areas such as Cornwall are highest). Background radiation is ALWAYS present and must be measured and subtracted before recording a source's true count rate — that subtraction is a standard exam step."},
  "MC-SEP-PHYS-FISSION":{type:"chain",title:"Splitting and the Chain Reaction",instruction:"Complete the chain for nuclear fission, then say what the control rods and moderator each do.",prompt:"A slow neutron is absorbed by a large unstable nucleus → [step] → [step] → chain reaction.",answer:"The nucleus becomes unstable and SPLITS into two smaller daughter nuclei → energy plus two or three more NEUTRONS are released → those neutrons are absorbed by further nuclei, causing more fission. Control rods (boron) ABSORB surplus neutrons to keep the reaction steady; the moderator SLOWS neutrons so they are more readily absorbed. Fission SPLITS a large nucleus — the opposite of fusion, and the pair students most often swap."},
  "MC-SEP-PHYS-FUSION":{type:"compare",title:"Fusion Against Fission",instruction:"Complete the table, then say why fusion is not yet used for power generation on Earth.",headers:["Feature","Fission","Fusion"],rows:[["What happens to nuclei","",""],["Fuel","",""],["Conditions needed","",""],["Waste","",""]],answer:"Fission: a large nucleus SPLITS; uranium/plutonium; achievable in a reactor; long-lived radioactive waste. Fusion: light nuclei JOIN; hydrogen isotopes; extremely high temperature and pressure; little long-lived waste. Fusion is not yet viable because containing a plasma at millions of degrees currently costs more energy than the reaction releases. In both, the mass of the products is slightly less than the reactants, and that lost mass is released as energy."},
  "MC-SEP-PHYS-STARS":{type:"correct",title:"Stars Do Not Burn",instruction:"A student writes: 'The Sun burns hydrogen, and when the fuel runs out the fire will go out.' Identify the two errors and write the correct explanation.",answer:"Error 1: BURNING is combustion, a chemical reaction needing oxygen — there is no oxygen in the Sun and no chemical reaction is involved. The Sun releases energy by nuclear FUSION, joining hydrogen nuclei into helium. Error 2: it will not simply 'go out'. As hydrogen in the core is used up, the Sun will expand into a red giant, then shed its outer layers and leave a white dwarf. Fusion is nuclear, not chemical, and releases far more energy per kilogram."},
  "MC-SEP-PHYS-DOPPLER":{type:"scenario",title:"Higher or Lower?",instruction:"For each, state whether the observed frequency and wavelength rise or fall.",items:["An ambulance siren approaching you","The same siren after it passes","A galaxy moving away from Earth"],answer:"Approaching: frequency HIGHER, wavelength shorter. Receding: frequency LOWER, wavelength longer. Distant galaxy: light shifted to longer wavelengths — RED-SHIFT. Note the source emits a constant frequency throughout; only the OBSERVED frequency changes, because the waves are bunched up ahead of the source and stretched behind it. The siren does not actually change pitch."},
  "MC-SEP-PHYS-UNIVERSE":{type:"chain",title:"From Red-Shift to the Big Bang",instruction:"Complete the reasoning chain, then state one further piece of evidence.",prompt:"Light from distant galaxies is red-shifted → [step] → [step] → the universe began from a single point.",answer:"Red-shift means galaxies are moving AWAY from us → more distant galaxies show GREATER red-shift, so they recede faster → the universe is expanding in all directions, so running it backwards converges on a single hot dense point. Further evidence: cosmic microwave background radiation, the leftover heat of the early universe, detected uniformly in all directions. Current estimate of the age: about 13.8 billion years. Note this does NOT mean Earth is the centre — every observer sees the same recession."},
  "MC-SEP-PHYS-THERMAL":{type:"calculate",title:"Heating Up Against Changing State",instruction:"Use E = mcΔθ. Then explain why the temperature does not rise during melting.",items:["Energy to raise 2 kg of water (c = 4200 J/kg°C) by 30°C?","A 0.5 kg block absorbs 9000 J and rises 20°C. Find c."],answer:"1 E = 2 × 4200 × 30 = 252,000 J. 2 c = E ÷ (mΔθ) = 9000 ÷ (0.5 × 20) = 900 J/kg°C. During MELTING or BOILING the temperature stays constant because the energy supplied breaks the forces BETWEEN particles rather than increasing their kinetic energy — that is LATENT heat, calculated with E = mL, not mcΔθ. Choosing between the two equations is the decision this starter drills."},
  "MC-SEP-PHYS-INSULATION":{type:"match",title:"Which Transfer Does It Block?",instruction:"For each measure, name the energy transfer it mainly reduces: conduction, convection or radiation.",items:["Loft insulation","Double glazing with a vacuum gap","Shiny foil behind a radiator","Draught excluder on a door","Thick carpet on a bare floor"],answer:"Loft insulation: traps air, reducing CONDUCTION and CONVECTION. Vacuum gap: no particles, so it blocks CONDUCTION and CONVECTION entirely. Shiny foil: reflects infrared, reducing RADIATION. Draught excluder: stops convection currents carrying warm air out. Carpet: reduces conduction through the floor. Trapped AIR is the common mechanism in most of these — air is a poor conductor, and trapping it also stops convection currents forming."}
};

// The 13 entries above whose tags no longer appear in BANKS (MC-HIST-01 to
// -13, MC-CRIM-01, MC-LAW-02) come from History and Criminology banks that
// were replaced. They are kept for the same reason MC_LABELS keeps retired
// tags: rows in the `responses` table still reference them, so a teacher
// looking at last year's data should still get the starter, not a bare code.

function getStarterActivity(tag, label) {
  if (tag && MC_STARTERS[tag]) return MC_STARTERS[tag];
  var name = label || (typeof resolveMCLabel === 'function' ? resolveMCLabel(tag) : '') || tag;
  return {
    type: "correct",
    title: "Targeted Misconception Drill",
    instruction: "The most common error this period is: <strong>" + name + "</strong>. Write the correct version on the board with the key terms blanked out. Students fill in the gaps and commit to an answer before you reveal it.",
    prompt: "Tag: " + tag + " — students who answered wrongly on this concept should revisit the scaffold on their Forge profile."
  };
}

if (typeof window !== 'undefined') {
  window.MC_STARTERS = MC_STARTERS;
  window.getStarterActivity = getStarterActivity;
}
